/**
 * ==============================================================================
 * Project: Sample 01 - Push Button ควบคุม LED (Hold-to-Activate & Toggle)
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (AVR-GCC)
 * Author: Embedded System Design Exam Preparation (CDTI)
 * ==============================================================================
 * 
 * [รายละเอียดฮาร์ดแวร์]
 * - สวิตช์ปุ่มกด (Push Button SW1): ต่อเข้าขา PD2 (Digital Pin 2)
 *   * ใช้ Internal Pull-up Resistor ของ MCU (เมื่อกดปุ่ม ขา PD2 จะมีสถานะเป็น LOW/0)
 *   * ขาอีกข้างของสวิตช์ต่อลง GND
 * - หลอดไฟ LED1: ต่อเข้าขา PB0 (Digital Pin 8)
 *   * ขั้ว Anode (+) ต่อเข้าขา PB0
 *   * ขั้ว Cathode (-) ต่อผ่านตัวต้านทาน 470 โอห์ม ลง GND (Active-High)
 *
 * [ฟังก์ชันการทำงาน]
 * 1. Hold-to-Activate: เมื่อกดปุ่มค้างไว้ LED ติด, เมื่อปล่อยปุ่ม LED ดับ
 * 2. Toggle Mode (Option): กดปุ่ม 1 ครั้งติด กดซ้ำอีกครั้งดับ พร้อมระบบกำจัดสัญญาณกระดอน (Software Debounce)
 * ==============================================================================
 */

#define F_CPU 16000000UL    // กำหนดความถี่สัญญาณนาฬิกา 16 MHz สำหรับ _delay_ms()
#include <avr/io.h>         // รวมไลบรารี Register I/O พื้นฐานของ AVR (DDR, PORT, PIN)
#include <util/delay.h>      // รวมฟังก์ชันหน่วงเวลา _delay_ms()

// กำหนดนิยามขาเพื่อความสะดวกและอ่านง่าย (Readable & Maintainable Code)
#define LED_PIN     PB0     // Digital Pin 8 อยู่บน PORTB บิตที่ 0
#define BUTTON_PIN  PD2     // Digital Pin 2 อยู่บน PORTD บิตที่ 2

int main(void) {
    // --------------------------------------------------------------------------
    // 1. ตั้งค่าทิศทางของพอร์ต (Data Direction Register - DDRx)
    // --------------------------------------------------------------------------
    // กำหนดให้ขา PB0 เป็น OUTPUT (บิต 0 = 1) โดยไม่กระทบบิตอื่น
    DDRB |= (1 << LED_PIN);

    // กำหนดให้ขา PD2 เป็น INPUT (บิต 2 = 0)
    DDRD &= ~(1 << BUTTON_PIN);

    // --------------------------------------------------------------------------
    // 2. ตั้งค่าสถานะเริ่มต้นของพอร์ต (Port Output/Pull-up Register - PORTx)
    // --------------------------------------------------------------------------
    // เปิดใช้งานตัวต้านทานพูลอัปภายใน (Internal Pull-Up) ที่ขา PD2 (บิต 2 = 1 ในสถานะ Input)
    // ผลลัพธ์: ปกติขา PD2 จะมีแรงดัน 5V (LOGIC 1), เมื่อกดปุ่มจะต่อลง GND กลายเป็น 0V (LOGIC 0)
    PORTD |= (1 << BUTTON_PIN);

    // เริ่มต้นให้ LED ดับ (ส่งลอจิก 0 ไปที่ PB0)
    PORTB &= ~(1 << LED_PIN);

    // ตัวแปรสำหรับโหมด Toggle (Optional State Tracking)
    uint8_t led_state = 0;       // เก็บสถานะของ LED (0 = ดับ, 1 = ติด)
    uint8_t last_btn_state = 1;  // เก็บสถานะปุ่มกดรอบก่อนหน้า (1 = ปล่อย, 0 = กด)

    // --------------------------------------------------------------------------
    // 3. วงรอบการทำงานหลัก (Super Loop)
    // --------------------------------------------------------------------------
    while (1) {
        /*
         * [แนวทางที่ 1]: แบบ Hold-to-Activate (กดค้างติด ปล่อยดับ - นิยมออกข้อสอบระดับพื้นฐาน)
         * อ่านค่าจาก Register PIND:
         * ถ้า (PIND & (1 << BUTTON_PIN)) == 0 แสดงว่าปุ่มถูกกดลง (Active-Low)
         */

        // ตรวจสอบสถานะปัจจุบันของปุ่มกด
        if (!(PIND & (1 << BUTTON_PIN))) {
            // เมื่อปุ่มถูกกด (Active-Low: ลอจิก 0)
            // เปิดไฟ LED (Set bit PB0 ให้เป็น 1)
            PORTB |= (1 << LED_PIN);
        } else {
            // เมื่อปล่อยปุ่ม (Pull-up: ลอจิก 1)
            // ปิดไฟ LED (Clear bit PB0 ให้เป็น 0)
            PORTB &= ~(1 << LED_PIN);
        }

        /*
         * [แนวทางที่ 2]: แบบ Toggle + Software Debounce (ปลดคอมเมนต์หากต้องการใช้งานโหมดนี้)
         *
        uint8_t current_btn = (PIND & (1 << BUTTON_PIN)) ? 1 : 0;

        // ตรวจจับขอบขาลง (Falling Edge: จากปล่อย 1 เป็น กด 0)
        if (last_btn_state == 1 && current_btn == 0) {
            _delay_ms(20); // หน่วงเวลาแก้สัญญาณกระดอน (Debounce Delay 20ms)
            if (!(PIND & (1 << BUTTON_PIN))) { // ตรวจสอบยืนยันอีกครั้ง
                led_state ^= 1; // สลับสถานะ (0 -> 1 หรือ 1 -> 0)
                if (led_state) {
                    PORTB |= (1 << LED_PIN);  // ติด
                } else {
                    PORTB &= ~(1 << LED_PIN); // ดับ
                }
            }
        }
        last_btn_state = current_btn;
        */

        _delay_ms(10); // หน่วงเวลาเล็กน้อยเพื่อเสถียรภาพการประมวลผล
    }

    return 0; // ไม่มีวันมาถึง (ตามมาตรฐานภาษา C)
}

