/*
 * Project: Sample 02 - Dual Button Hold-to-Light (2 Switches, 2 LEDs)
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (avr-gcc)
 *
 * Description:
 * - SW1 (PD2 / Pin 2) controls LED1 (PB0 / Pin 8) independently
 * - SW2 (PD3 / Pin 3) controls LED2 (PB1 / Pin 9) independently
 * - Momentary Hold Action: กดสวิตช์ตัวไหน ไฟดวงนั้นจะติด ปล่อยจะดับทันที
 */

#define F_CPU 16000000UL
#include <avr/io.h>

int main(void) {
    // 1. ตั้งค่าพอร์ต B (PB0, PB1 เป็น Output สำหรับ LED)
    DDRB |= (1 << PB0) | (1 << PB1);
    PORTB &= ~((1 << PB0) | (1 << PB1)); // เริ่มต้นดับไฟ

    // 2. ตั้งค่าพอร์ต D (PD2, PD3 เป็น Input พร้อมเปิด Internal Pull-Up)
    DDRD &= ~((1 << PD2) | (1 << PD3));
    PORTD |= (1 << PD2) | (1 << PD3);

    while (1) {
        // ช่องสัญญาณที่ 1: ตรวจสอบ SW1 (PD2) -> ควบคุม LED1 (PB0)
        if (!(PIND & (1 << PD2))) {
            PORTB |= (1 << PB0);   // กดปุ่ม SW1 -> เปิด LED1
        } else {
            PORTB &= ~(1 << PB0);  // ปล่อยปุ่ม SW1 -> ดับ LED1
        }

        // ช่องสัญญาณที่ 2: ตรวจสอบ SW2 (PD3) -> ควบคุม LED2 (PB1)
        if (!(PIND & (1 << PD3))) {
            PORTB |= (1 << PB1);   // กดปุ่ม SW2 -> เปิด LED2
        } else {
            PORTB &= ~(1 << PB1);  // ปล่อยปุ่ม SW2 -> ดับ LED2
        }
    }
    return 0;
}

