/*
 * Project: Sample 03 - Quad Button Hold-to-Light (4 Switches, 4 LEDs)
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (avr-gcc)
 *
 * Description:
 * - SW1..SW4 (PD2..PD5) ควบคุม LED1..LED4 (PB0..PB3) อิสระ 4 ช่องสัญญาณ
 * - ใช้เทคนิค Port Bit Mapping: อ่านค่า PIND บิต 2..5 เลื่อนบิตมาที่ 0..3 และขับออก PORTB โดยตรง
 */

#define F_CPU 16000000UL
#include <avr/io.h>

int main(void) {
    // 1. ตั้งค่า PB0..PB3 เป็น Output สำหรับ LED 4 ดวง
    DDRB |= 0x0F;
    PORTB &= ~0x0F; // เริ่มต้นดับไฟทุกดวง

    // 2. ตั้งค่า PD2..PD5 เป็น Input พร้อมเปิด Internal Pull-Up
    DDRD &= ~0x3C;
    PORTD |= 0x3C;

    while (1) {
        // อ่านค่าพอร์ต D, สลับบิต (Invert เพราะ Active-Low), เลื่อนบิต 2 ตำแหน่งให้ตรง PB0..PB3
        uint8_t sw_inputs = (~PIND >> 2) & 0x0F;

        // นำค่าที่ได้เขียนลงเฉพาะบิต 0..3 ของ PORTB โดยไม่รบกวนบิต 4..7
        PORTB = (PORTB & 0xF0) | sw_inputs;
    }
    return 0;
}

