/**
 * ==============================================================================
 * Project: Sample 09 - สวิตช์ปุ่มกดแบบ Toggle (กดติด-กดดับ) และตรวจจับ Long-Press
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (AVR-GCC)
 * Author: Embedded System Design Exam Preparation (CDTI)
 * ==============================================================================
 * 
 * [รายละเอียดฮาร์ดแวร์]
 * - ปุ่มกด SW1: ต่อขา Digital Pin 2 (PD2) แบบ Active-Low (Internal Pull-Up)
 * - หลอด LED 1: ต่อขา Digital Pin 8 (PB0) ผ่านตัวต้านทาน 470 โอห์ม (Main Toggle LED)
 * - หลอด LED 2: ต่อขา Digital Pin 9 (PB1) ผ่านตัวต้านทาน 470 โอห์ม (Long-Press Alert LED)
 *
 * [ฟังก์ชันการทำงาน (Button State Machine)]
 * 1. กดสั้น (Short Click < 1.0 วินาที):
 *    - สลับสถานะของ LED 1: "กดครั้งที่ 1 ไฟติด -> กดครั้งที่ 2 ไฟดับ -> วนซ้ำ" (Toggle Latch)
 * 2. กดยาว (Long Press >= 1.0 วินาที):
 *    - ตรวจจับว่าผู้ใช้กดปุ่มค้างเกิน 1 วินาที
 *    - สั่งกระพริบ LED 2 เตือน 3 ครั้ง แล้วรีเซ็ตดับไฟ LED 1 ทั้งหมด (Master Reset)
 * 3. มีระบบป้องกันการกระดอนของหน้าสัมผัส (Hardware-proof Software Debounce)
 * ==============================================================================
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

#define LED1_PIN    PB0     // Digital Pin 8 (Main Toggle)
#define LED2_PIN    PB1     // Digital Pin 9 (Alert)
#define BTN_PIN     PD2     // Digital Pin 2 (Button)

int main(void) {
    // 1. ตั้งค่าทิศทางพอร์ต (DDRx)
    DDRB |= (1 << LED1_PIN) | (1 << LED2_PIN);  // Output สำหรับ LED
    DDRD &= ~(1 << BTN_PIN);                    // Input สำหรับปุ่มกด

    // 2. เปิด Internal Pull-up และเคลียร์ค่าเอาต์พุตเริ่มต้น
    PORTD |= (1 << BTN_PIN);
    PORTB &= ~((1 << LED1_PIN) | (1 << LED2_PIN));

    uint8_t led_state = 0;       // 0 = ดับ, 1 = ติด
    uint8_t last_button_val = 1; // สถานะรอบก่อนหน้า (1 = ปล่อย)

    while (1) {
        uint8_t current_val = (PIND & (1 << BTN_PIN)) ? 1 : 0;

        // ตรวจจับขอบขาลง (Falling Edge: จากปล่อย 1 กลายเป็นกด 0)
        if (last_button_val == 1 && current_val == 0) {
            _delay_ms(20); // หน่วงเวลากำจัดสัญญาณกระดอน (Debounce)
            if (!(PIND & (1 << BTN_PIN))) {
                // เริ่มจับเวลาการกดค้าง (Hold Timer)
                uint16_t hold_time = 0;
                while (!(PIND & (1 << BTN_PIN))) {
                    _delay_ms(10);
                    hold_time += 10;
                    if (hold_time >= 1000) {
                        break; // กดค้างครบ 1 วินาที (1000 ms)
                    }
                }

                if (hold_time >= 1000) {
                    // [เหตุการณ์ที่ 2: Long Press] กดยาวเกิน 1 วินาที -> กระพริบ LED2 เตือน และดับ LED1
                    led_state = 0;
                    PORTB &= ~(1 << LED1_PIN); // สั่งดับ LED1

                    for (uint8_t i = 0; i < 3; i++) {
                        PORTB |= (1 << LED2_PIN);
                        _delay_ms(100);
                        PORTB &= ~(1 << LED2_PIN);
                        _delay_ms(100);
                    }

                    // รอจนกว่าผู้ใช้จะปล่อยปุ่มจริง ๆ ป้องกันการเด้งซ้ำ
                    while (!(PIND & (1 << BTN_PIN))) {
                        _delay_ms(10);
                    }
                } else {
                    // [เหตุการณ์ที่ 1: Short Click] กดสั้น -> สลับสถานะ Toggle (ติด <-> ดับ)
                    led_state ^= 1;
                    if (led_state) {
                        PORTB |= (1 << LED1_PIN);  // ติด
                    } else {
                        PORTB &= ~(1 << LED1_PIN); // ดับ
                    }
                }
            }
        }

        last_button_val = (PIND & (1 << BTN_PIN)) ? 1 : 0;
        _delay_ms(10);
    }

    return 0;
}

