/*
 * Project: Sample 05 - Dual Button Independent Toggle (2 Switches, 2 LEDs)
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (avr-gcc)
 *
 * Description:
 * - SW1 (PD2) สลับสถานะเปิด/ปิด LED1 (PB0) แบบ Push-On Push-Off
 * - SW2 (PD3) สลับสถานะเปิด/ปิด LED2 (PB1) แบบ Push-On Push-Off
 * - มีระบบ Software Debounce และ Edge Detection ตรวจจับการกดเฉพาะจังหวะขอบขาลง
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

int main(void) {
    DDRB |= (1 << PB0) | (1 << PB1);
    PORTB &= ~((1 << PB0) | (1 << PB1));

    DDRD &= ~((1 << PD2) | (1 << PD3));
    PORTD |= (1 << PD2) | (1 << PD3);

    uint8_t prev_sw1 = 1;
    uint8_t prev_sw2 = 1;

    while (1) {
        uint8_t curr_sw1 = (PIND & (1 << PD2)) ? 1 : 0;
        uint8_t curr_sw2 = (PIND & (1 << PD3)) ? 1 : 0;

        // Channel 1 Edge Detection (1 -> 0: Falling Edge)
        if (prev_sw1 == 1 && curr_sw1 == 0) {
            _delay_ms(20); // Debounce
            if (!(PIND & (1 << PD2))) {
                PORTB ^= (1 << PB0); // Toggle LED1
            }
        }
        prev_sw1 = curr_sw1;

        // Channel 2 Edge Detection (1 -> 0: Falling Edge)
        if (prev_sw2 == 1 && curr_sw2 == 0) {
            _delay_ms(20); // Debounce
            if (!(PIND & (1 << PD3))) {
                PORTB ^= (1 << PB1); // Toggle LED2
            }
        }
        prev_sw2 = curr_sw2;

        _delay_ms(5);
    }
    return 0;
}

