/*
 * Project: Sample 06 - Quad Button Independent Toggle (4 Switches, 4 LEDs)
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (avr-gcc)
 *
 * Description:
 * - สวิตช์ 4 ตัว ควบคุมสลับสถานะ (Toggle) หลอดไฟ 4 ดวงแบบอิสระ 4 ช่องสัญญาณ
 * - เสมือนระบบเปิด-ปิดไฟห้อง 4 ดวงในบ้าน (Home Automation)
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

int main(void) {
    DDRB |= 0x0F;        // PB0..PB3 Output
    PORTB &= ~0x0F;

    DDRD &= ~0x3C;       // PD2..PD5 Input
    PORTD |= 0x3C;       // Pull-Up

    uint8_t prev_sw = 0; // เก็บบิตสถานะการกดก่อนหน้า (1=กด, 0=ปล่อย)

    while (1) {
        // อ่านค่าและกลับบิต: 1 แปลว่ากำลังกดอยู่
        uint8_t curr_sw = (~PIND >> 2) & 0x0F;

        // หาจังหวะกดใหม่ (Rising Edge ของสถานะการกด: ตอนนี้กด แต่รอบก่อนไม่ได้กด)
        uint8_t pressed = curr_sw & (~prev_sw);

        if (pressed) {
            _delay_ms(25); // Debounce
            // สลับสถานะเฉพาะบิตที่มีการกดใหม่
            PORTB ^= pressed;
        }

        prev_sw = curr_sw;
        _delay_ms(10);
    }
    return 0;
}

