/*
 * Project: Sample 07 - Two-Way Staircase Switch (2 Switches, 1 LED)
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (avr-gcc)
 *
 * Description:
 * - สวิตช์บันได 2 ทาง (Two-Way Switching) ด้วยตรรกะ XOR
 * - สวิตช์ SW1 อยู่ชั้นล่าง (PD2) และ SW2 อยู่ชั้นบน (PD3) ควบคุมหลอดไฟบันไดดวงเดียวกัน (PB0)
 * - กดสวิตช์ตัวไหนก็ตาม หลอดไฟจะสลับสถานะ (เปิดหรือปิด) ทันที
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

int main(void) {
    DDRB |= (1 << PB0);    // PB0 Output
    PORTB &= ~(1 << PB0);

    DDRD &= ~((1 << PD2) | (1 << PD3));
    PORTD |= (1 << PD2) | (1 << PD3);

    uint8_t sw1_state = 0;
    uint8_t sw2_state = 0;
    uint8_t prev_sw1 = 1;
    uint8_t prev_sw2 = 1;

    while (1) {
        uint8_t curr_sw1 = (PIND & (1 << PD2)) ? 1 : 0;
        uint8_t curr_sw2 = (PIND & (1 << PD3)) ? 1 : 0;

        if (prev_sw1 == 1 && curr_sw1 == 0) {
            _delay_ms(20);
            sw1_state ^= 1; // สลับสถานะสวิตช์ตัวล่าง
        }
        prev_sw1 = curr_sw1;

        if (prev_sw2 == 1 && curr_sw2 == 0) {
            _delay_ms(20);
            sw2_state ^= 1; // สลับสถานะสวิตช์ตัวบน
        }
        prev_sw2 = curr_sw2;

        // สถานะหลอดไฟ = sw1_state XOR sw2_state
        if (sw1_state ^ sw2_state) {
            PORTB |= (1 << PB0);  // หลอดไฟสว่าง
        } else {
            PORTB &= ~(1 << PB0); // หลอดไฟดับ
        }

        _delay_ms(5);
    }
    return 0;
}

