/*
 * Project: Sample 08 - 1-of-3 Exclusive Mode Selector (Radio Buttons)
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (avr-gcc)
 *
 * Description:
 * - สวิตช์ 3 ตัวเลือกโหมดการทำงานแบบ Mutually Exclusive (Radio Button Logic)
 * - กด SW1 -> ติดเฉพาะ LED1 (LED2, LED3 ดับ)
 * - กด SW2 -> ติดเฉพาะ LED2 (LED1, LED3 ดับ)
 * - กด SW3 -> ติดเฉพาะ LED3 (LED1, LED2 ดับ)
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

int main(void) {
    DDRB |= 0x07;       // PB0, PB1, PB2 เป็น Output
    PORTB = (PORTB & ~0x07) | (1 << PB0); // เริ่มต้นที่โหมด 1 (LED1 ติด)

    DDRD &= ~0x1C;      // PD2, PD3, PD4 เป็น Input
    PORTD |= 0x1C;      // Pull-Up

    while (1) {
        if (!(PIND & (1 << PD2))) {
            _delay_ms(20);
            if (!(PIND & (1 << PD2))) {
                PORTB = (PORTB & ~0x07) | (1 << PB0); // เลือกโหมด 1
            }
        }
        else if (!(PIND & (1 << PD3))) {
            _delay_ms(20);
            if (!(PIND & (1 << PD3))) {
                PORTB = (PORTB & ~0x07) | (1 << PB1); // เลือกโหมด 2
            }
        }
        else if (!(PIND & (1 << PD4))) {
            _delay_ms(20);
            if (!(PIND & (1 << PD4))) {
                PORTB = (PORTB & ~0x07) | (1 << PB2); // เลือกโหมด 3
            }
        }
        _delay_ms(10);
    }
    return 0;
}

