 * ==============================================================================
 * 
 * [รายละเอียดฮาร์ดแวร์]
 * 1. สวิตช์ปุ่มกด 4 ปุ่ม (Active-Low พร้อม Internal Pull-up):
 *    - SW1 : PD2 (Arduino Pin 2) -> กดติด 1 หลอด (LED1)
 *    - SW2 : PD3 (Arduino Pin 3) -> กดติด 2 หลอด (LED1, LED2)
 *    - SW3 : PD4 (Arduino Pin 4) -> กดติด 3 หลอด (LED1, LED2, LED3)
 *    - SW4 : PD5 (Arduino Pin 5) -> กดติด 4 หลอด (LED1, LED2, LED3, LED4)
 *    - เมื่อไม่กดปุ่มใดๆ: ไฟดับทั้งหมด
 * 
 * 2. หลอดไฟ LED 4 ดวง (Active-High ผ่าน R = 470 โอห์ม):
 *    - LED1 : PB0 (Arduino Pin 8)
 *    - LED2 : PB1 (Arduino Pin 9)
 *    - LED3 : PB2 (Arduino Pin 10)
 *    - LED4 : PB3 (Arduino Pin 11)
 * ==============================================================================
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>
#include <stdbool.h>

#define SW1_PIN     PD2     // Pin 2
#define SW2_PIN     PD3     // Pin 3
#define SW3_PIN     PD4     // Pin 4
#define SW4_PIN     PD5     // Pin 5

#define LED_MASK    0x0F    // PB0..PB3 (Pins 8..11)

int main(void) {
    // 1. กำหนดทิศทาง I/O:
    // PB0..PB3 เป็น OUTPUT (เขียน 1 ลง DDRB)
    DDRB |= LED_MASK;
    PORTB &= ~LED_MASK;     // เริ่มต้นปิดไฟ LED ทุกดวง (LOW)

    // PD2..PD5 เป็น INPUT (เขียน 0 ลง DDRD)
    DDRD &= ~((1 << SW1_PIN) | (1 << SW2_PIN) | (1 << SW3_PIN) | (1 << SW4_PIN));
    // เปิดใช้งานตัวต้านทานพูลอัปภายใน (Internal Pull-Up) ให้ PD2..PD5
    PORTD |= ((1 << SW1_PIN) | (1 << SW2_PIN) | (1 << SW3_PIN) | (1 << SW4_PIN));

    while (1) {
        // อ่านค่าระดับลอจิกจากพอร์ต D
        uint8_t pind_val = PIND;

        // ตรวจสอบเงื่อนไขแบบลำดับความสำคัญ (Priority Logic: 4 -> 3 -> 2 -> 1):
        if (!(pind_val & (1 << SW4_PIN))) {
            // กด SW4 -> เปิดไฟ 4 ดวง (PB0, PB1, PB2, PB3)
            PORTB = (PORTB & ~LED_MASK) | 0x0F;
        } else if (!(pind_val & (1 << SW3_PIN))) {
            // กด SW3 -> เปิดไฟ 3 ดวง (PB0, PB1, PB2)
            PORTB = (PORTB & ~LED_MASK) | 0x07;
        } else if (!(pind_val & (1 << SW2_PIN))) {
            // กด SW2 -> เปิดไฟ 2 ดวง (PB0, PB1)
            PORTB = (PORTB & ~LED_MASK) | 0x03;
        } else if (!(pind_val & (1 << SW1_PIN))) {
            // กด SW1 -> เปิดไฟ 1 ดวง (PB0)
            PORTB = (PORTB & ~LED_MASK) | 0x01;
        } else {
            // ไม่ได้กดสวิตช์ใดๆ -> ปิดไฟ LED ทั้งหมด
            PORTB = (PORTB & ~LED_MASK);
        }

        _delay_ms(10); // หน่วงเวลาสั้นๆ เพื่อเสถียรภาพในการสแกน
    }

    return 0;
}

