/*
 * Project: Sample 10 - Multi-Switch OR Logic Emergency Alarm (3 Switches, 1 LED)
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (avr-gcc)
 *
 * Description:
 * - สวิตช์ 3 ตัวต่อขนานตรรกะแบบ OR (Any-Button Alarm)
 * - หากมีสวิตช์ตัวใดตัวหนึ่ง (SW1, SW2, หรือ SW3) ถูกกด ไฟเตือนภัย ALARM_LED (PB0) จะติดสว่างทันที
 */

#define F_CPU 16000000UL
#include <avr/io.h>

int main(void) {
    DDRB |= (1 << PB0);      // PB0 Output (ALARM_LED)
    PORTB &= ~(1 << PB0);    // เริ่มต้นดับไฟ

    DDRD &= ~((1 << PD2) | (1 << PD3) | (1 << PD4)); // PD2..PD4 Input
    PORTD |= (1 << PD2) | (1 << PD3) | (1 << PD4);   // Enable Pull-Up

    while (1) {
        // ตรวจสอบว่ามีปุ่มใดปุ่มหนึ่งถูกกดหรือไม่ (Active-Low: ค่าเป็น 0)
        if (!(PIND & (1 << PD2)) || !(PIND & (1 << PD3)) || !(PIND & (1 << PD4))) {
            PORTB |= (1 << PB0);  // กดตัวใดตัวหนึ่ง -> เปิดไฟเตือน
        } else {
            PORTB &= ~(1 << PB0); // ปล่อยทุกตัว -> ดับไฟ
        }
    }
    return 0;
}

