/**
 * ==============================================================================
 * Project: Sample 02 - สวิตช์ 2 ปุ่ม ควบคุม LED 2 หลอด (Multi-Button Logic Control)
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (AVR-GCC)
 * Author: Embedded System Design Exam Preparation (CDTI)
 * ==============================================================================
 * 
 * [รายละเอียดฮาร์ดแวร์]
 * - ปุ่มกด SW1: ต่อขา PD2 (Digital Pin 2) แบบ Active-Low (Internal Pull-Up)
 * - ปุ่มกด SW2: ต่อขา PD3 (Digital Pin 3) แบบ Active-Low (Internal Pull-Up)
 * - หลอด LED 1: ต่อขา PB0 (Digital Pin 8) ผ่าน R = 470 โอห์ม (Active-High)
 * - หลอด LED 2: ต่อขา PB1 (Digital Pin 9) ผ่าน R = 470 โอห์ม (Active-High)
 *
 * [เงื่อนไขการทำงาน (Logic Specifications)]
 * 1. ถ้าไม่กดปุ่มใดเลย (SW1=0, SW2=0 ทางกายภาพ): LED1 ดับ, LED2 ดับ
 * 2. ถ้ากดเฉพาะ SW1 (SW1=1, SW2=0): LED1 ติด, LED2 ดับ
 * 3. ถ้ากดเฉพาะ SW2 (SW1=0, SW2=1): LED1 ดับ, LED2 ติด
 * 4. ถ้ากดพร้อมกันทั้งสองปุ่ม (SW1=1, SW2=1): ให้ LED1 และ LED2 สลับกันติด-ดับ (Blink Alternately)
 * ==============================================================================
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

// กำหนดนิยามขาของ LED
#define LED1_PIN    PB0     // Arduino Pin 8
#define LED2_PIN    PB1     // Arduino Pin 9

// กำหนดนิยามขาของ Switch
#define SW1_PIN     PD2     // Arduino Pin 2
#define SW2_PIN     PD3     // Arduino Pin 3

int main(void) {
    // --------------------------------------------------------------------------
    // 1. กำหนดทิศทางพอร์ต (Data Direction Register)
    // --------------------------------------------------------------------------
    // ตั้ง PB0 และ PB1 เป็น OUTPUT
    DDRB |= (1 << LED1_PIN) | (1 << LED2_PIN);

    // ตั้ง PD2 และ PD3 เป็น INPUT
    DDRD &= ~((1 << SW1_PIN) | (1 << SW2_PIN));

    // --------------------------------------------------------------------------
    // 2. ตั้งค่าสถานะเริ่มต้นของพอร์ต (Pull-Up & Initial Output)
    // --------------------------------------------------------------------------
    // เปิด Internal Pull-Up Resistor ให้กับ PD2 และ PD3
    PORTD |= (1 << SW1_PIN) | (1 << SW2_PIN);

    // เริ่มต้นให้ LED ทั้งสองดวงดับ
    PORTB &= ~((1 << LED1_PIN) | (1 << LED2_PIN));

    // --------------------------------------------------------------------------
    // 3. วงรอบการทำงานหลัก (Main Super Loop)
    // --------------------------------------------------------------------------
    while (1) {
        // อ่านค่าสถานะจากพอร์ต D (Active-Low: กด = 0, ปล่อย = 1)
        // แปลงให้เป็นตรรกะแบบบวก (1 = ถูกกด, 0 = ไม่ได้กด)
        uint8_t sw1_pressed = !(PIND & (1 << SW1_PIN));
        uint8_t sw2_pressed = !(PIND & (1 << SW2_PIN));

        // ตรวจสอบเงื่อนไขตามตารางความจริง (Truth Table Logic)
        if (sw1_pressed && sw2_pressed) {
            // [กรณีที่ 4]: กดพร้อมกันทั้ง 2 ปุ่ม -> กระพริบสลับกัน
            PORTB |= (1 << LED1_PIN);
            PORTB &= ~(1 << LED2_PIN);
            _delay_ms(150);

            PORTB &= ~(1 << LED1_PIN);
            PORTB |= (1 << LED2_PIN);
            _delay_ms(150);
        }
        else if (sw1_pressed) {
            // [กรณีที่ 2]: กดเฉพาะ SW1 -> LED1 ติด, LED2 ดับ
            PORTB |= (1 << LED1_PIN);
            PORTB &= ~(1 << LED2_PIN);
            _delay_ms(20);
        }
        else if (sw2_pressed) {
            // [กรณีที่ 3]: กดเฉพาะ SW2 -> LED1 ดับ, LED2 ติด
            PORTB &= ~(1 << LED1_PIN);
            PORTB |= (1 << LED2_PIN);
            _delay_ms(20);
        }
        else {
            // [กรณีที่ 1]: ไม่ได้กดปุ่มใดเลย -> ดับทั้งคู่
            PORTB &= ~((1 << LED1_PIN) | (1 << LED2_PIN));
            _delay_ms(20);
        }
    }

    return 0;
}

