            }

            if (latched_run) {
                PORTB |= (1 << PB0);
                PORTB &= ~(1 << PB1);
            } else {
                PORTB &= ~(1 << PB0);
                PORTB |= (1 << PB1);
            }
        }

        _delay_ms(10);
    }
    return 0;
}

