/**
 * ==============================================================================
 * Project: Sample 05 - ระบบความปลอดภัยควบคุมเครื่องจักรด้วยการกด 2 ปุ่มพร้อมกัน (Two-Hand Safety)
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (AVR-GCC)
 * Author: Embedded System Design Exam Preparation (CDTI)
 * ==============================================================================
 * 
 * [หลักการและข้อกำหนดความปลอดภัย (Machinery Safety Standard)]
 * - ระบบอินเตอร์ล็อกสองมือ (Two-Hand Safety Control): ผู้ควบคุมต้องใช้ทั้งสองมือกดสวิตช์
 *   SW1 (มือซ้าย) และ SW2 (มือขวา) พร้อมกัน เพื่อป้องกันไม่ให้มือของผู้ปฏิบัติงาน
 *   เข้าไปอยู่ในเขตอันตรายของเครื่องปั๊มโลหะหรือใบมีดตัด
 * - หากกดสวิตช์ทั้งสองพร้อมกัน (SW1=0 และ SW2=0): เครื่องจักรทำงาน (LED_SAFE ติดสว่างสีเขียว, LED_WARN ดับ)
 * - หากกดเพียงปุ่มเดียว (ผิดเงื่อนไขความปลอดภัย): เครื่องจักรหยุดทันที และหลอด LED_WARN สีแดงจะกะพริบเตือน
 * - หากไม่กดปุ่มใดๆ: เครื่องจักรหยุดทำงาน (LED_SAFE ดับ, LED_WARN ดับ)
 * ==============================================================================
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>
#include <stdbool.h>

#define SW1_PIN         PD2     // Pin 2 (มือซ้าย / Left Hand)
#define SW2_PIN         PD3     // Pin 3 (มือขวา / Right Hand)

#define LED_SAFE_PIN    PB0     // Pin 8 (ไฟเขียว / Machine Running)
#define LED_WARN_PIN    PB1     // Pin 9 (ไฟแดง / Safety Violation / Standby)

int main(void) {
    // 1. กำหนด PB0, PB1 เป็น OUTPUT
    DDRB |= (1 << LED_SAFE_PIN) | (1 << LED_WARN_PIN);
    PORTB &= ~((1 << LED_SAFE_PIN) | (1 << LED_WARN_PIN)); // เริ่มต้นปิดไฟ

    // 2. กำหนด PD2, PD3 เป็น INPUT พร้อมเปิด Internal Pull-Up
    DDRD &= ~((1 << SW1_PIN) | (1 << SW2_PIN));
    PORTD |= (1 << SW1_PIN) | (1 << SW2_PIN);

    uint8_t blink_counter = 0;

    while (1) {
        bool sw1_pressed = !(PIND & (1 << SW1_PIN));
        bool sw2_pressed = !(PIND & (1 << SW2_PIN));

        if (sw1_pressed && sw2_pressed) {
            // ปลอดภัยสมบูรณ์: ทั้งสองมือกดพร้อมกัน -> รันเครื่องจักร
            PORTB |= (1 << LED_SAFE_PIN);       // LED_SAFE ติด
            PORTB &= ~(1 << LED_WARN_PIN);      // LED_WARN ดับ
            blink_counter = 0;
        } else if (sw1_pressed || sw2_pressed) {
            // ละเมิดความปลอดภัย: กดเพียงมือเดียว -> สั่งหยุดทันที และไฟเตือนกะพริบ
            PORTB &= ~(1 << LED_SAFE_PIN);      // หยุดเครื่องจักรทันที

            // กะพริบไฟเตือนทุก 200 ms
            blink_counter++;
            if (blink_counter >= 20) {
                PORTB ^= (1 << LED_WARN_PIN);   // Toggle ไฟเตือน
                blink_counter = 0;
            }
        } else {
            // สแตนด์บาย: ไม่มีใครกดสวิตช์ -> ปิดทุกหลอด
            PORTB &= ~((1 << LED_SAFE_PIN) | (1 << LED_WARN_PIN));
            blink_counter = 0;
        }

        _delay_ms(10);
    }

    return 0;
}

