/**
 * ==============================================================================
 * Project: Sample 06 - วงจรนับเลขฐานสอง 4 บิต (0-15) แสดงผลผ่าน 4 LEDs พร้อมปุ่ม Up/Down
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (AVR-GCC)
 * Author: Embedded System Design Exam Preparation (CDTI)
 * ==============================================================================
 * 
 * [รายละเอียดฮาร์ดแวร์]
 * 1. สวิตช์ปุ่มกด 2 ปุ่ม (Active-Low พร้อม Internal Pull-up):
 *    - SW_UP   : PD2 (Arduino Pin 2) -> เพิ่มค่าทีละ 1 (0 -> 1 -> ... -> 15 -> 0)
 *    - SW_DOWN : PD3 (Arduino Pin 3) -> ลดค่าทีละ 1 (15 -> 14 -> ... -> 0 -> 15)
 * 
 * 2. หลอดไฟ LED แสดงผลเลขฐานสอง 4 บิต (Active-High ผ่าน R = 470 โอห์ม):
 *    - LED_B0 : PB0 (Arduino Pin 8)  -> บิต 0 (น้ำหนัก 2^0 = 1)
 *    - LED_B1 : PB1 (Arduino Pin 9)  -> บิต 1 (น้ำหนัก 2^1 = 2)
 *    - LED_B2 : PB2 (Arduino Pin 10) -> บิต 2 (น้ำหนัก 2^2 = 4)
 *    - LED_B3 : PB3 (Arduino Pin 11) -> บิต 3 (น้ำหนัก 2^3 = 8)
 * ==============================================================================
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>
#include <stdbool.h>

#define SW_UP_PIN       PD2     // Pin 2
#define SW_DOWN_PIN     PD3     // Pin 3
#define LED_MASK        0x0F    // PB0..PB3

int main(void) {
    // 1. กำหนด PB0..PB3 เป็น OUTPUT
    DDRB |= LED_MASK;
    PORTB &= ~LED_MASK;         // เริ่มต้นค่า 0 (ดับหมด)

    // 2. กำหนด PD2, PD3 เป็น INPUT พร้อมเปิด Internal Pull-Up
    DDRD &= ~((1 << SW_UP_PIN) | (1 << SW_DOWN_PIN));
    PORTD |= (1 << SW_UP_PIN) | (1 << SW_DOWN_PIN);

    uint8_t count = 0;
    bool last_up_state = true;
    bool last_down_state = true;

    while (1) {
        bool current_up = (PIND & (1 << SW_UP_PIN)) != 0;
        bool current_down = (PIND & (1 << SW_DOWN_PIN)) != 0;

        // ตรวจจับขอบขาลงของ SW_UP (กดปุ่ม)
        if (last_up_state && !current_up) {
            _delay_ms(30);      // ซอฟต์แวร์ดีบาวน์
            if (!(PIND & (1 << SW_UP_PIN))) {
                count = (count + 1) & 0x0F; // นับวนรอบ 0..15
            }
        }

        // ตรวจจับขอบขาลงของ SW_DOWN (กดปุ่ม)
        if (last_down_state && !current_down) {
            _delay_ms(30);      // ซอฟต์แวร์ดีบาวน์
            if (!(PIND & (1 << SW_DOWN_PIN))) {
                count = (count - 1) & 0x0F; // ถอยหลังวนรอบ 15..0
            }
        }

        last_up_state = current_up;
        last_down_state = current_down;

        // อัปเดตเอาต์พุตเลขฐานสองไปยัง PB0..PB3
        PORTB = (PORTB & ~LED_MASK) | (count & LED_MASK);

        _delay_ms(10);
    }

    return 0;
}

