/*
 * Project: Sample 15 - Push Button Short Press vs Long Press Reset (1 SW, 4 LEDs)
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (avr-gcc)
 *
 * Description:
 * - SW (PD2): กดสั้น (< 1.5s) เพิ่มค่านับเลขฐานสองบน 4 LEDs (0..15)
 * - กดค้างยาว (> 1.5s): รีเซ็ตค่านับกลับเป็น 0 ทันที
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

int main(void) {
    DDRB |= 0x0F;       // PB0..PB3 Output
    PORTB &= ~0x0F;

    DDRD &= ~(1 << PD2); // PD2 Input
    PORTD |= (1 << PD2);  // Pull-Up

    uint8_t count = 0;

    while (1) {
        if (!(PIND & (1 << PD2))) {
            _delay_ms(20); // Debounce
            if (!(PIND & (1 << PD2))) {
                uint16_t duration_ms = 0;
                while (!(PIND & (1 << PD2))) {
                    _delay_ms(10);
                    duration_ms += 10;
                    if (duration_ms >= 1500) {
                        // Long press detected! Flash once to notify and reset
                        PORTB |= 0x0F;
                        _delay_ms(150);
                        PORTB &= ~0x0F;
                        count = 0;
                        while (!(PIND & (1 << PD2))); // รอจนปล่อยปุ่ม
                        break;
                    }
                }
                if (duration_ms < 1500) {
                    // Short press detected
                    count = (count + 1) & 0x0F;
                }
            }
        }
        PORTB = (PORTB & 0xF0) | (count & 0x0F);
        _delay_ms(10);
    }
    return 0;
}

