/*
 * Project: Sample 14 - 4-Level LED Bar Stepper (2 Buttons, 4 LEDs)
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (avr-gcc)
 *
 * Description:
 * - ตัวปรับระดับไฟแถบ 4 ระดับ (Unary Level Accumulator)
 * - SW_UP (PD2): เพิ่มระดับ 0 -> 1 -> 2 -> 3 -> 4
 * - SW_DOWN (PD3): ลดระดับ 4 -> 3 -> 2 -> 1 -> 0
 * - LED1..LED4 (PB0..PB3): แสดงผลแถบแสงสะสมตามระดับปัจจุบัน
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

const uint8_t level_patterns[5] = {
    0b00000000, // Level 0: ดับหมด
    0b00000001, // Level 1: 1 ดวง
    0b00000011, // Level 2: 2 ดวง
    0b00000111, // Level 3: 3 ดวง
    0b00001111  // Level 4: 4 ดวง
};

int main(void) {
    DDRB |= 0x0F;       // PB0..PB3 Output
    PORTB &= ~0x0F;

    DDRD &= ~0x0C;      // PD2, PD3 Input
    PORTD |= 0x0C;      // Pull-Up

    uint8_t level = 0;
    uint8_t prev_up = 1;
    uint8_t prev_down = 1;

    while (1) {
        uint8_t curr_up   = (PIND & (1 << PD2)) ? 1 : 0;
        uint8_t curr_down = (PIND & (1 << PD3)) ? 1 : 0;

        // ตรวจจับปุ่ม UP (ขอบขาลง)
        if (prev_up == 1 && curr_up == 0) {
            _delay_ms(20);
            if (level < 4) {
                level++;
            }
        }
        prev_up = curr_up;

        // ตรวจจับปุ่ม DOWN (ขอบขาลง)
        if (prev_down == 1 && curr_down == 0) {
            _delay_ms(20);
            if (level > 0) {
                level--;
            }
        }
        prev_down = curr_down;

        // ขับเอาต์พุตตามตารางระดับ
        PORTB = (PORTB & 0xF0) | level_patterns[level];

        _delay_ms(10);
    }
    return 0;
}

