/**
 * ==============================================================================
 * Project: Sample 07 - ไฟกะพริบสลับข้างและไฟฉุกเฉิน (Alternating Hazard Strobe) พร้อมปรับความเร็ว
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (AVR-GCC)
 * Author: Embedded System Design Exam Preparation (CDTI)
 * ==============================================================================
 * 
 * [รายละเอียดฮาร์ดแวร์]
 * 1. สวิตช์ปุ่มกด 2 ปุ่ม (Active-Low พร้อม Internal Pull-up):
 *    - SW_MODE  : PD2 (Arduino Pin 2) -> สลับโหมด [Alternating Flasher] / [Hazard Flasher]
 *    - SW_SPEED : PD3 (Arduino Pin 3) -> สลับความเร็ว [ช้า 400ms] / [เร็ว 150ms]
 * 
 * 2. หลอดไฟ LED 2 ดวง (Active-High ผ่าน R = 470 โอห์ม):
 *    - LED_LEFT  : PB0 (Arduino Pin 8)
 *    - LED_RIGHT : PB1 (Arduino Pin 9)
 * ==============================================================================
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>
#include <stdbool.h>

#define SW_MODE_PIN     PD2     // Pin 2
#define SW_SPEED_PIN    PD3     // Pin 3

#define LED_LEFT_PIN    PB0     // Pin 8
#define LED_RIGHT_PIN   PB1     // Pin 9

int main(void) {
    // 1. กำหนด PB0, PB1 เป็น OUTPUT
    DDRB |= (1 << LED_LEFT_PIN) | (1 << LED_RIGHT_PIN);
    PORTB &= ~((1 << LED_LEFT_PIN) | (1 << LED_RIGHT_PIN));

    // 2. กำหนด PD2, PD3 เป็น INPUT พร้อมเปิด Internal Pull-Up
    DDRD &= ~((1 << SW_MODE_PIN) | (1 << SW_SPEED_PIN));
    PORTD |= (1 << SW_MODE_PIN) | (1 << SW_SPEED_PIN);

    bool hazard_mode = false;   // false = Alternating, true = Hazard
    bool fast_speed = false;    // false = 400ms, true = 150ms

    bool last_mode_sw = true;
    bool last_speed_sw = true;

    uint8_t phase = 0;

    while (1) {
        // ตรวจจับการกดปุ่ม SW_MODE
        bool cur_mode_sw = (PIND & (1 << SW_MODE_PIN)) != 0;
        if (last_mode_sw && !cur_mode_sw) {
            _delay_ms(30);
            if (!(PIND & (1 << SW_MODE_PIN))) {
                hazard_mode = !hazard_mode;
                phase = 0;
            }
        }
        last_mode_sw = cur_mode_sw;

        // ตรวจจับการกดปุ่ม SW_SPEED
        bool cur_speed_sw = (PIND & (1 << SW_SPEED_PIN)) != 0;
        if (last_speed_sw && !cur_speed_sw) {
            _delay_ms(30);
            if (!(PIND & (1 << SW_SPEED_PIN))) {
                fast_speed = !fast_speed;
            }
        }
        last_speed_sw = cur_speed_sw;

        // ขับสัญญาณไฟ LED ตามโหมดและเฟส
        if (!hazard_mode) {
            // โหมด Alternating: สลับซ้าย-ขวา
            if (phase == 0) {
                PORTB |= (1 << LED_LEFT_PIN);
                PORTB &= ~(1 << LED_RIGHT_PIN);
            } else {
                PORTB &= ~(1 << LED_LEFT_PIN);
                PORTB |= (1 << LED_RIGHT_PIN);
            }
        } else {
            // โหมด Hazard: กะพริบพร้อมกันทั้งสองข้าง
            if (phase == 0) {
                PORTB |= (1 << LED_LEFT_PIN) | (1 << LED_RIGHT_PIN);
            } else {
                PORTB &= ~((1 << LED_LEFT_PIN) | (1 << LED_RIGHT_PIN));
            }
        }

        phase = 1 - phase; // สลับเฟส 0 <-> 1

        // หน่วงเวลาตามความเร็ว
        if (fast_speed) {
            _delay_ms(150);
        } else {
            _delay_ms(400);
        }
    }

    return 0;
}

