#include <avr/io.h>

int main(void) {
    DDRB |= (1 << PB0);      // PB0 Output
    PORTB &= ~(1 << PB0);    // LED OFF
    DDRD &= ~((1 << PD2) | (1 << PD3)); // PD2, PD3 Input
    PORTD |= (1 << PD2) | (1 << PD3);   // Pull-Up

    while (1) {
        // AND Logic: Both must be pressed (0)
        if (!(PIND & (1 << PD2)) && !(PIND & (1 << PD3))) {
            PORTB |= (1 << PB0);  // Both pressed -> LED ON
        } else {
            PORTB &= ~(1 << PB0); // Any released -> LED OFF
        }
    }
    return 0;
}

