#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

int main(void) {
    DDRB |= (1 << PB0);      // PB0 Output
    PORTB &= ~(1 << PB0);
    DDRD &= ~(1 << PD2);     // PD2 Input
    PORTD |= (1 << PD2);      // Pull-Up

    uint8_t count = 0;
    uint8_t last_sw = 1;
    uint16_t idle_ticks = 0;

    while (1) {
        uint8_t sw = (PIND & (1 << PD2)) ? 1 : 0;
        if (last_sw == 1 && sw == 0) {
            _delay_ms(20);
            if (!(PIND & (1 << PD2))) {
                count++;
                idle_ticks = 0;
            }
        }
        last_sw = sw;

        if (count > 0) {
            idle_ticks++;
            // If idle for ~1000ms after last click, echo blinks
            if (idle_ticks > 100) {
                _delay_ms(400);
                for (uint8_t i = 0; i < count; i++) {
                    PORTB |= (1 << PB0);
                    _delay_ms(200);
                    PORTB &= ~(1 << PB0);
                    _delay_ms(200);
                }
                count = 0;
                idle_ticks = 0;
            }
        }

        _delay_ms(10);
    }
    return 0;
}

