/*
 * Project: Sample 18 - Knight Rider / Ping-Pong 6-LED Scanner
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (avr-gcc)
 *
 * Description:
 * - ไฟวิ่งสะท้อนขอบไป-กลับ 6 ดวง (0 -> 1 -> 2 -> 3 -> 4 -> 5 -> 4 -> 3 -> 2 -> 1 -> 0)
 * - เลื่อนบิตไปทางซ้ายจนชนบิต 5 แล้วสลับทิศทางเลื่อนไปทางขวาจนชนบิต 0
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

int main(void) {
    DDRB |= 0x3F;       // PB0..PB5 Output
    PORTB &= ~0x3F;

    uint8_t pos = 0;
    int8_t dir = 1;     // 1 = shift up (0->5), -1 = shift down (5->0)

    while (1) {
        PORTB = (PORTB & ~0x3F) | (1 << pos);
        _delay_ms(80);

        pos += dir;
        if (pos == 5) {
            dir = -1; // ชนขอบบน -> สะท้อนกลับลง
        } else if (pos == 0) {
            dir = 1;  // ชนขอบล่าง -> สะท้อนกลับขึ้น
        }
    }
    return 0;
}

