#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

// Patterns: Center out and back (3 frames)
// PB2+PB3 (0x0C), PB1+PB4 (0x12), PB0+PB5 (0x21)
const uint8_t curtain_frames[6] = {0x0C, 0x12, 0x21, 0x12, 0x0C, 0x00};

int main(void) {
    DDRB |= 0x3F;   // PB0..PB5 Output
    PORTB &= ~0x3F; // All LEDs OFF
    DDRD &= ~(1 << PD2); // PD2 Input
    PORTD |= (1 << PD2);  // Pull-up

    uint8_t step = 0;
    uint8_t paused = 0;
    uint8_t last_sw = 1;

    while (1) {
        uint8_t sw = (PIND & (1 << PD2)) ? 1 : 0;
        if (last_sw == 1 && sw == 0) {
            _delay_ms(20);
            if (!(PIND & (1 << PD2))) {
                paused = !paused;
            }
        }
        last_sw = sw;

        if (!paused) {
            PORTB = (PORTB & ~0x3F) | curtain_frames[step];
            step = (step + 1) % 6;
        }
        _delay_ms(200);
    }
    return 0;
}

