int main(void) {
    DDRB |= 0x3F;   // PB0..PB5 Output
    PORTB &= ~0x3F;

    while (1) {
        uint8_t stacked = 0;
        // Fill phase: stack from bottom (PB0) to top (PB5)
        for (int target = 0; target < 6; target++) {
            for (int pos = 5; pos >= target; pos--) {
                PORTB = stacked | (1 << pos);
                _delay_ms(100);
            }
            stacked |= (1 << target);
            PORTB = stacked;
            _delay_ms(150);
        }
        _delay_ms(400);

        // Drain phase: drain out from top to bottom
        for (int target = 5; target >= 0; target--) {
            stacked &= ~(1 << target);
            PORTB = stacked;
            _delay_ms(150);
        }
        _delay_ms(400);
    }
    return 0;
}

