/**
 * ==============================================================================
 * Project: Sample 03 - วงจรไฟวิ่ง LED 6 ดวง ควบคุมทิศทางและความเร็วด้วยสวิตช์
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (AVR-GCC)
 * Author: Embedded System Design Exam Preparation (CDTI)
 * ==============================================================================
 * 
 * [รายละเอียดฮาร์ดแวร์]
 * - หลอดไฟ LED 6 ดวง (LED1 - LED6): ต่อเข้ากับขา Digital Pin 8 ถึง 13 (PB0 - PB5)
 *   ผ่านตัวต้านทานจำกัดกระแส 470 โอห์ม (Active-High)
 * - สวิตช์ปุ่มกด SW1: ต่อเข้ากับขา Digital Pin 2 (PD2) - ใช้สลับทิศทางวิ่ง (ซ้าย <-> ขวา)
 * - สวิตช์ปุ่มกด SW2: ต่อเข้ากับขา Digital Pin 3 (PD3) - ใช้สลับความเร็ว (ช้า <-> เร็ว)
 *   * ปุ่มทั้งสองใช้ Internal Pull-Up (Active-Low)
 *
 * [ฟังก์ชันการทำงาน]
 * 1. ไฟวิ่งทีละ 1 หลอดเรียงลำดับจากดวงที่ 1 ไปดวงที่ 6 (หรือ 6 มา 1)
 * 2. กด SW1 เพื่อ Toggle ทิศทาง (ซ้ายไปขวา หรือ ขวาไปซ้าย)
 * 3. กด SW2 เพื่อ Toggle ความเร็ว (ช้า 250ms หรือ เร็ว 80ms)
 * 4. ระบบตรวจจับการกดปุ่มแบบมี Software Debounce
 * ==============================================================================
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

// กำหนด Mask ของไฟ LED 6 ดวงบน PORTB (บิต 0 ถึง 5)
#define LED_MASK    0b00111111  // PB0, PB1, PB2, PB3, PB4, PB5

#define SW_DIR_PIN  PD2         // สวิตช์เปลี่ยนทิศทาง (Arduino Pin 2)
#define SW_SPD_PIN  PD3         // สวิตช์เปลี่ยนความเร็ว (Arduino Pin 3)

// ฟังก์ชันหน่วงเวลาแบบกำหนดมิลลิวินาทีแปรผันได้
void delay_variable_ms(uint16_t ms) {
    while (ms--) {
        _delay_ms(1);
    }
}

int main(void) {
    // --------------------------------------------------------------------------
    // 1. ตั้งค่าทิศทางพอร์ต (DDRx)
    // --------------------------------------------------------------------------
    // กำหนด PB0 - PB5 เป็น OUTPUT (1)
    DDRB |= LED_MASK;

    // กำหนด PD2, PD3 เป็น INPUT (0)
    DDRD &= ~((1 << SW_DIR_PIN) | (1 << SW_SPD_PIN));

    // --------------------------------------------------------------------------
    // 2. ตั้งค่า Pull-up และค่าเริ่มต้น
    // --------------------------------------------------------------------------
    // เปิด Internal Pull-up บน PD2, PD3
    PORTD |= (1 << SW_DIR_PIN) | (1 << SW_SPD_PIN);

    // ดับไฟ LED ทั้งหมดบน PORTB
    PORTB &= ~LED_MASK;

    // ตัวแปรควบคุมสถานะของระบบ
    int8_t current_led = 0;     // ตำแหน่งหลอดปัจจุบัน (0 ถึง 5)
    uint8_t direction = 1;      // 1 = วิ่งขึ้น (0->5), 0 = วิ่งลง (5->0)
    uint16_t speed_delay = 200; // ค่าดีเลย์ความเร็วเริ่มต้น (200 ms)

    uint8_t last_sw1 = 1;
    uint8_t last_sw2 = 1;

    // --------------------------------------------------------------------------
    // 3. ลูปการทำงานหลัก
    // --------------------------------------------------------------------------
    while (1) {
        // อัปเดตการแสดงผลหลอดไฟ LED ตามตำแหน่ง current_led
        // ล้างบิต 0-5 ก่อน แล้วค่อยเซ็ตบิตเฉพาะหลอดที่ต้องการให้สว่าง
        PORTB = (PORTB & ~LED_MASK) | (1 << current_led);

        // ตรวจสอบปุ่มกดระหว่างรอบการวิ่ง (Polling พร้อม Debounce)
        // แบ่งการหน่วงเวลาเป็นท่อนย่อยๆ เพื่อให้ตอบสนองปุ่มกดได้ฉับไว
        uint16_t slices = speed_delay / 10;
        for (uint16_t i = 0; i < slices; i++) {
            uint8_t btn1 = (PIND & (1 << SW_DIR_PIN)) ? 1 : 0;
            uint8_t btn2 = (PIND & (1 << SW_SPD_PIN)) ? 1 : 0;

            // ตรวจจับการกด SW1 (Falling Edge: 1 -> 0) เพื่อสลับทิศทาง
            if (last_sw1 == 1 && btn1 == 0) {
                _delay_ms(15); // Debounce
                if (!(PIND & (1 << SW_DIR_PIN))) {
                    direction ^= 1; // สลับทิศทาง (0 <-> 1)
                }
            }
            last_sw1 = btn1;

            // ตรวจจับการกด SW2 (Falling Edge: 1 -> 0) เพื่อสลับความเร็ว
            if (last_sw2 == 1 && btn2 == 0) {
                _delay_ms(15); // Debounce
                if (!(PIND & (1 << SW_SPD_PIN))) {
                    if (speed_delay == 200) {
                        speed_delay = 70;  // ปรับเป็นเร็ว
                    } else {
                        speed_delay = 200; // ปรับเป็นช้า
                    }
                }
            }
            last_sw2 = btn2;

            _delay_ms(10);
        }

        // คำนวณตำแหน่งหลอดไฟถัดไปตามทิศทาง
        if (direction == 1) {
            current_led++;
            if (current_led > 5) {
                current_led = 0; // วนกลับจุดเริ่มต้น
            }
        } else {
            current_led--;
            if (current_led < 0) {
                current_led = 5; // วนกลับปลายทาง
            }
        }
    }

    return 0;
}

