/*
 * Project: Sample 20 - Dual Police Strobe & Alternating Flasher (1 SW, 2 LEDs)
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (avr-gcc)
 *
 * Description:
 * - หลอดไฟตำรวจกระพริบฉุกเฉิน (Blue on PB0, Red on PB1)
 * - โหมด 1: Police Strobe (กระพริบเร็ว 3 ครั้งซ้าย -> 3 ครั้งขวา -> หยุดสั้น)
 * - โหมด 2: Alternating Flash (กระพริบสลับช้าๆ 250ms)
 * - ปุ่ม SW1 (PD2) สลับโหมดการทำงาน
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

int main(void) {
    DDRB |= (1 << PB0) | (1 << PB1);
    PORTB &= ~((1 << PB0) | (1 << PB1));

    DDRD &= ~(1 << PD2);
    PORTD |= (1 << PD2);

    uint8_t mode = 0;
    uint8_t prev_sw = 1;

    while (1) {
        uint8_t curr_sw = (PIND & (1 << PD2)) ? 1 : 0;
        if (prev_sw == 1 && curr_sw == 0) {
            _delay_ms(20);
            mode ^= 1;
        }
        prev_sw = curr_sw;

        if (mode == 0) {
            // Police Strobe: 3 flashes Left, 3 flashes Right
            for (uint8_t i = 0; i < 3; i++) {
                PORTB |= (1 << PB0); _delay_ms(40);
                PORTB &= ~(1 << PB0); _delay_ms(40);
            }
            _delay_ms(50);
            for (uint8_t i = 0; i < 3; i++) {
                PORTB |= (1 << PB1); _delay_ms(40);
                PORTB &= ~(1 << PB1); _delay_ms(40);
            }
            _delay_ms(80);
        } else {
            // Alternating Blink
            PORTB = (PORTB & ~((1<<PB0)|(1<<PB1))) | (1 << PB0);
            _delay_ms(250);
            PORTB = (PORTB & ~((1<<PB0)|(1<<PB1))) | (1 << PB1);
            _delay_ms(250);
        }
    }
    return 0;
}

