#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

void flash_dot(void) {
    PORTB |= (1 << PB0);
    _delay_ms(150);
    PORTB &= ~(1 << PB0);
    _delay_ms(150);
}

void flash_dash(void) {
    PORTB |= (1 << PB0);
    _delay_ms(450);
    PORTB &= ~(1 << PB0);
    _delay_ms(150);
}

int main(void) {
    DDRB |= (1 << PB0) | (1 << PB1); // PB0 Red, PB1 Green
    PORTB &= ~((1 << PB0) | (1 << PB1));
    DDRD &= ~(1 << PD2); // PD2 Input
    PORTD |= (1 << PD2);  // Pull-up

    uint8_t active = 0;
    uint8_t last_sw = 1;

    while (1) {
        uint8_t sw = (PIND & (1 << PD2)) ? 1 : 0;
        if (last_sw == 1 && sw == 0) {
            _delay_ms(20);
            if (!(PIND & (1 << PD2))) {
                active = !active;
            }
        }
        last_sw = sw;

        if (active) {
            PORTB |= (1 << PB1); // Green armed
            // S: ...
            flash_dot(); flash_dot(); flash_dot();
            _delay_ms(300);
            // O: ---
            flash_dash(); flash_dash(); flash_dash();
            _delay_ms(300);
            // S: ...
            flash_dot(); flash_dot(); flash_dot();
            _delay_ms(1000);
        } else {
            PORTB &= ~((1 << PB0) | (1 << PB1));
            _delay_ms(50);
        }
    }
    return 0;
}

