typedef enum { STATE_IDLE, STATE_RUNNING, STATE_FAULT } MachState;

int main(void) {
    DDRB |= (1 << PB0) | (1 << PB1) | (1 << PB2); // PB0: Grn, PB1: Red, PB2: Motor
    PORTB &= ~0x07;
    DDRD &= ~((1 << PD2) | (1 << PD3) | (1 << PD4)); // PD2: Start, PD3: Stop, PD4: Fault
    PORTD |= (1 << PD2) | (1 << PD3) | (1 << PD4);

    MachState state = STATE_IDLE;
    uint8_t tick = 0;

    while (1) {
        // Read inputs (Active-Low)
        uint8_t sw_start = !(PIND & (1 << PD2));
        uint8_t sw_stop  = !(PIND & (1 << PD3));
        uint8_t sw_fault = !(PIND & (1 << PD4));

        if (sw_fault) {
            state = STATE_FAULT;
        }

        switch (state) {
            case STATE_IDLE:
                PORTB &= ~((1 << PB1) | (1 << PB2));
                // Slow pulse green
                if (tick % 10 < 5) PORTB |= (1 << PB0);
                else PORTB &= ~(1 << PB0);

                if (sw_start && !sw_stop) {
                    state = STATE_RUNNING;
                }
                break;

            case STATE_RUNNING:
                PORTB |= (1 << PB0) | (1 << PB2); // Green + Motor solid ON
                PORTB &= ~(1 << PB1);

                if (sw_stop) {
                    state = STATE_IDLE;
                }
                break;

            case STATE_FAULT:
                PORTB &= ~((1 << PB0) | (1 << PB2)); // Shut off motor & green
                // Rapid flash red (5Hz)
                if (tick % 2 == 0) PORTB |= (1 << PB1);
                else PORTB &= ~(1 << PB1);

                // Reset fault with STOP button
                if (sw_stop && !sw_fault) {
                    state = STATE_IDLE;
                }
                break;
        }

        tick++;
        _delay_ms(100);
    }
    return 0;
}

