/**
 * ==============================================================================
 * Project: Sample 10 - สวิตช์ปุ่มเดียวเปลี่ยนโหมดไฟ 5 สเต็ป (Sequential Mode Selector)
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (AVR-GCC)
 * Author: Embedded System Design Exam Preparation (CDTI)
 * ==============================================================================
 * 
 * [รายละเอียดฮาร์ดแวร์]
 * - สวิตช์เลือกโหมด SW1: ต่อเข้ากับขา Digital Pin 2 (PD2) แบบ Active-Low (Pull-Up)
 * - หลอดไฟ LED 6 ดวง: ต่อเข้ากับขา Digital Pin 8 ถึง 13 (PB0 ถึง PB5) ผ่าน R 470 โอห์ม
 *
 * [ลำดับสเต็ปโหมดการทำงาน (Mode Cycle)]
 * - Mode 0: ปิดไฟทั้งหมด (All OFF)
 * - Mode 1: เปิดไฟระดับต่ำ (2 หลอดแรกติด: LED1, LED2)
 * - Mode 2: เปิดไฟระดับกลาง (4 หลอดติด: LED1 ถึง LED4)
 * - Mode 3: เปิดไฟระดับสูงสุด (ติดครบ 6 หลอด: LED1 ถึง LED6)
 * - Mode 4: โหมดไฟกระพริบเตือน (All LEDs Strobe Flashing)
 * * กดอีกครั้งจะวนกลับไปที่ Mode 0
 * ==============================================================================
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

#define LED_MASK    0b00111111  // PB0 ถึง PB5
#define SW_PIN      PD2         // Digital Pin 2

int main(void) {
    // ตั้งค่าพอร์ต
    DDRB |= LED_MASK;           // PB0 - PB5 เป็น OUTPUT
    DDRD &= ~(1 << SW_PIN);     // PD2 เป็น INPUT
    PORTD |= (1 << SW_PIN);     // เปิด Pull-Up บน PD2
    PORTB &= ~LED_MASK;         // ดับไฟเริ่มต้น

    uint8_t mode = 0;           // ตัวแปรโหมด (0 ถึง 4)
    uint8_t last_btn = 1;
    uint8_t strobe_state = 0;

    while (1) {
        // ตรวจจับการกดปุ่ม SW1 (ขอบขาลง 1 -> 0)
        uint8_t cur_btn = (PIND & (1 << SW_PIN)) ? 1 : 0;
        if (last_btn == 1 && cur_btn == 0) {
            _delay_ms(25); // Debounce
            if (!(PIND & (1 << SW_PIN))) {
                mode++;
                if (mode > 4) {
                    mode = 0; // วนกลับสู่โหมด 0
                }
            }
        }
        last_btn = cur_btn;

        // ควบคุมหลอดไฟ LED ตามโหมดปัจจุบัน
        switch (mode) {
            case 0:
                PORTB &= ~LED_MASK; // ดับหมด
                _delay_ms(20);
                break;
            case 1:
                PORTB = (PORTB & ~LED_MASK) | 0b00000011; // 2 หลอด
                _delay_ms(20);
                break;
            case 2:
                PORTB = (PORTB & ~LED_MASK) | 0b00001111; // 4 หลอด
                _delay_ms(20);
                break;
            case 3:
                PORTB = (PORTB & ~LED_MASK) | 0b00111111; // 6 หลอดเต็ม
                _delay_ms(20);
                break;
            case 4:
                // ไฟกระพริบเป็นจังหวะ
                strobe_state ^= 1;
                if (strobe_state) {
                    PORTB |= LED_MASK;
                } else {
                    PORTB &= ~LED_MASK;
                }
                _delay_ms(150);
                break;
            default:
                mode = 0;
                break;
        }
    }

    return 0;
}

