/**
 * ==============================================================================
 * Project: Sample 17 - ระบบไฟจราจรคนข้ามอัจฉริยะ พร้อมนับถอยหลัง 7-Segment (Traffic Light)
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (AVR-GCC)
 * Author: Embedded System Design Exam Preparation (CDTI)
 * ==============================================================================
 * 
 * [การจัดสรรขาพอร์ตฮาร์ดแวร์]
 * 1. หลอดไฟสัญญาณจราจรรถยนต์ (Vehicle Traffic Lights):
 *    - CAR_RED    : PB5 (Arduino Pin 13) ผ่าน R = 470 โอห์ม
 *    - CAR_YELLOW : PB4 (Arduino Pin 12) ผ่าน R = 470 โอห์ม
 *    - CAR_GREEN  : PB3 (Arduino Pin 11) ผ่าน R = 470 โอห์ม
 *
 * 2. หลอดไฟสัญญาณคนเดินข้าม (Pedestrian Signals):
 *    - PED_RED    : PB2 (Arduino Pin 10) ผ่าน R = 470 โอห์ม (ห้ามข้าม)
 *    - PED_GREEN  : PB1 (Arduino Pin 9)  ผ่าน R = 470 โอห์ม (ข้ามได้)
 *
 * 3. ปุ่มกดขอข้ามถนน (Pedestrian Request Button):
 *    - SW_CROSS   : PB0 (Arduino Pin 8)  ใช้ Internal Pull-up (Active-Low)
 *
 * 4. หน้าจอ 7-Segment Common Cathode (นับเวลาถอยหลัง 9..0):
 *    - ขั้ว a-g ต่อเข้ากับ PD0 ถึง PD6 ผ่านตัวต้านทาน 470 โอห์ม
 *    - ขั้ว COM ต่อลงกราวด์ GND
 * ==============================================================================
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>
#include <stdbool.h>

// กำหนดนิยามขาของไฟจราจรและคนข้าม
#define SW_CROSS_PIN    PB0     // Pin 8 (Button)
#define PED_GREEN_PIN   PB1     // Pin 9 (Pedestrian Walk)
#define PED_RED_PIN     PB2     // Pin 10 (Pedestrian Don't Walk)
#define CAR_GREEN_PIN   PB3     // Pin 11 (Car Green)
#define CAR_YELLOW_PIN  PB4     // Pin 12 (Car Yellow)
#define CAR_RED_PIN     PB5     // Pin 13 (Car Red)

// ตารางถอดรหัส 0-9 สำหรับ 7-Segment Common Cathode
const uint8_t SEG_LUT[11] = {
    0x3F,  // 0
    0x06,  // 1
    0x5B,  // 2
    0x4F,  // 3
    0x66,  // 4
    0x6D,  // 5
    0x7D,  // 6
    0x07,  // 7
    0x7F,  // 8
    0x6F,  // 9
    0x40   // 10 : สัญลักษณ์ '-'
};

void seg_display(uint8_t num) {
    if (num <= 10) {
        PORTD = SEG_LUT[num];
    } else {
        PORTD = 0x00; // ปิดจอ
    }
}

int main(void) {
    // --------------------------------------------------------------------------
    // 1. ตั้งค่าทิศทางพอร์ต I/O
    // --------------------------------------------------------------------------
    // พอร์ต D (PD0..PD6) เป็น OUTPUT สำหรับ 7-Segment
    DDRD |= 0b01111111;
    PORTD = 0x00;

    // พอร์ต B: PB1..PB5 เป็น OUTPUT สำหรับหลอดไฟ 5 หลอด
    DDRB |= (1 << PED_GREEN_PIN) | (1 << PED_RED_PIN) |
            (1 << CAR_GREEN_PIN) | (1 << CAR_YELLOW_PIN) | (1 << CAR_RED_PIN);

    // PB0 เป็น INPUT สำหรับปุ่มขอข้ามถนน พร้อมเปิด Pull-up
    DDRB &= ~(1 << SW_CROSS_PIN);
    PORTB |= (1 << SW_CROSS_PIN);

    while (1) {
        // ======================================================================
        // สถานะที่ 1: รถวิ่งปกติ (Car Green, Pedestrian Red)
        // ======================================================================
        // ปิดไฟอื่นทั้งหมด เปิดเฉพาะ CAR_GREEN และ PED_RED
        PORTB &= ~((1 << CAR_RED_PIN) | (1 << CAR_YELLOW_PIN) | (1 << PED_GREEN_PIN));
        PORTB |= (1 << CAR_GREEN_PIN) | (1 << PED_RED_PIN);
        seg_display(10); // แสดง '-'

        // รอตราบใดที่ไม่มีคนกดปุ่มขอข้ามถนน
        while (PINB & (1 << SW_CROSS_PIN)) {
            _delay_ms(20);
        }

        _delay_ms(30); // Debounce
        while (!(PINB & (1 << SW_CROSS_PIN))); // รอจนปล่อยปุ่ม

        // ======================================================================
        // สถานะที่ 2: เตือนรถเตรียมหยุด (Car Yellow, Pedestrian Red) - 2 วินาที
        // ======================================================================
        PORTB &= ~(1 << CAR_GREEN_PIN);
        PORTB |= (1 << CAR_YELLOW_PIN);
        _delay_ms(2000);

        // ======================================================================
        // สถานะที่ 3: รถหยุด คนเริ่มข้าม (Car Red, Pedestrian Green)
        // นับถอยหลังบน 7-Segment จาก 9 ถึง 0 วินาที
        // ======================================================================
        PORTB &= ~((1 << CAR_YELLOW_PIN) | (1 << PED_RED_PIN));
        PORTB |= (1 << CAR_RED_PIN) | (1 << PED_GREEN_PIN);

        for (int8_t sec = 9; sec >= 0; sec--) {
            seg_display((uint8_t)sec);

            if (sec <= 3 && sec > 0) {
                // ช่วง 3 วินาทีสุดท้าย: ไฟเขียวคนข้ามกะพริบเตือนเร่งรีบข้าม!
                for (uint8_t flash = 0; flash < 2; flash++) {
                    PORTB &= ~(1 << PED_GREEN_PIN);
                    _delay_ms(250);
                    PORTB |= (1 << PED_GREEN_PIN);
                    _delay_ms(250);
                }
            } else {
                _delay_ms(1000); // หน่วงเวลา 1 วินาทีเต็ม
            }
        }

        // ======================================================================
        // สถานะที่ 4: สิ้นสุดเวลาข้าม (Pedestrian Red, Car Red สั้นๆ เพื่อความปลอดภัย)
        // ======================================================================
        PORTB &= ~(1 << PED_GREEN_PIN);
        PORTB |= (1 << PED_RED_PIN);
        seg_display(10); // แสดง '-'
        _delay_ms(1000); // All-Red Clearance Time 1 วินาที

        // ระบบวนกลับสู่สถานะที่ 1 รถไฟเขียวเริ่มวิ่งใหม่
    }

    return 0;
}

