/*
 * Project: Sample 23 - Auto 1-Second 0-9 Counter with Blinking DP on 7-Segment
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (avr-gcc)
 *
 * Description:
 * - แสดงผลนับตัวเลข 0 ถึง 9 อัตโนมัติทุกๆ 1 วินาทีวนลูป
 * - จุดทศนิยม (DP on PD7) กระพริบทุกๆ 500 ms เพื่อบอกจังหวะวินาที
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

const uint8_t seg_digits[10] = {
    0x3F, 0x06, 0x5B, 0x4F, 0x66, 0x6D, 0x7D, 0x07, 0x7F, 0x6F
};

int main(void) {
    DDRD = 0xFF; // PD0..PD7 Output
    PORTD = 0x00;

    uint8_t count = 0;

    while (1) {
        // ครึ่งวินาทีแรก: แสดงตัวเลข + จุดทศนิยมติด (DP=1)
        PORTD = seg_digits[count] | (1 << 7);
        _delay_ms(500);

        // ครึ่งวินาทีหลัง: แสดงตัวเลข + จุดทศนิยมดับ (DP=0)
        PORTD = seg_digits[count] & ~(1 << 7);
        _delay_ms(500);

        count = (count + 1) % 10;
    }
    return 0;
}

