/**
 * ==============================================================================
 * Project: Sample 04 - ตัวนับเลข 0-9 แสดงผลบน 7-Segment (Common Cathode)
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (AVR-GCC)
 * Author: Embedded System Design Exam Preparation (CDTI)
 * ==============================================================================
 * 
 * [รายละเอียดฮาร์ดแวร์]
 * - 7-Segment Display (1 หลัก แบบ Common Cathode):
 *   * ขั้ว a -> PD0 (Arduino Pin 0) ผ่าน R = 470 โอห์ม
 *   * ขั้ว b -> PD1 (Arduino Pin 1) ผ่าน R = 470 โอห์ม
 *   * ขั้ว c -> PD2 (Arduino Pin 2) ผ่าน R = 470 โอห์ม
 *   * ขั้ว d -> PD3 (Arduino Pin 3) ผ่าน R = 470 โอห์ม
 *   * ขั้ว e -> PD4 (Arduino Pin 4) ผ่าน R = 470 โอห์ม
 *   * ขั้ว f -> PD5 (Arduino Pin 5) ผ่าน R = 470 โอห์ม
 *   * ขั้ว g -> PD6 (Arduino Pin 6) ผ่าน R = 470 โอห์ม
 *   * ขั้ว Common Cathode (COM) ต่อลงกราวด์ GND
 *
 * - สวิตช์ปุ่มกด (Active-Low พร้อม Internal Pull-Up):
 *   * SW_UP    : ต่อเข้า PB0 (Arduino Pin 8)  -> กดเพื่อนับขึ้น (+1)
 *   * SW_DOWN  : ต่อเข้า PB1 (Arduino Pin 9)  -> กดเพื่อนับลง (-1)
 *   * SW_RESET : ต่อเข้า PB2 (Arduino Pin 10) -> กดเพื่อรีเซ็ตเป็น 0
 * ==============================================================================
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

// กำหนดนิยามขาของสวิตช์
#define SW_UP_PIN       PB0     // Pin 8
#define SW_DOWN_PIN     PB1     // Pin 9
#define SW_RESET_PIN    PB2     // Pin 10

// ตารางถอดรหัสตัวเลข 0-9 สำหรับ 7-Segment ชนิด Common Cathode (Active-High)
// บิต: [g f e d c b a]
const uint8_t SEG_LUT[10] = {
    0x3F,  // 0 : a, b, c, d, e, f
    0x06,  // 1 : b, c
    0x5B,  // 2 : a, b, d, e, g
    0x4F,  // 3 : a, b, c, d, g
    0x66,  // 4 : b, c, f, g
    0x6D,  // 5 : a, c, d, f, g
    0x7D,  // 6 : a, c, d, e, f, g
    0x07,  // 7 : a, b, c
    0x7F,  // 8 : a, b, c, d, e, f, g
    0x6F   // 9 : a, b, c, d, f, g
};

int main(void) {
    // --------------------------------------------------------------------------
    // 1. ตั้งค่าทิศทางพอร์ต (DDRx)
    // --------------------------------------------------------------------------
    // ขา PD0 ถึง PD6 เป็น OUTPUT (1) เพื่อขับเซกเมนต์ a-g
    DDRD |= 0b01111111;

    // ขา PB0, PB1, PB2 เป็น INPUT (0) สำหรับรับค่าจากสวิตช์
    DDRB &= ~((1 << SW_UP_PIN) | (1 << SW_DOWN_PIN) | (1 << SW_RESET_PIN));

    // --------------------------------------------------------------------------
    // 2. เปิดใช้งาน Pull-up และกำหนดค่าเริ่มต้น
    // --------------------------------------------------------------------------
    PORTB |= (1 << SW_UP_PIN) | (1 << SW_DOWN_PIN) | (1 << SW_RESET_PIN);

    int8_t count = 0; // ตัวนับค่าเริ่มต้น 0

    // แสดงผลเลข 0 เริ่มต้น
    PORTD = (PORTD & 0x80) | SEG_LUT[count];

    uint8_t last_up = 1;
    uint8_t last_down = 1;
    uint8_t last_reset = 1;

    // --------------------------------------------------------------------------
    // 3. วงรอบการทำงานหลัก (Main Loop)
    // --------------------------------------------------------------------------
    while (1) {
        uint8_t cur_up    = (PINB & (1 << SW_UP_PIN)) ? 1 : 0;
        uint8_t cur_down  = (PINB & (1 << SW_DOWN_PIN)) ? 1 : 0;
        uint8_t cur_reset = (PINB & (1 << SW_RESET_PIN)) ? 1 : 0;

        // ตรวจจับปุ่ม UP (ขอบขาลง 1 -> 0)
        if (last_up == 1 && cur_up == 0) {
            _delay_ms(20); // Debounce
            if (!(PINB & (1 << SW_UP_PIN))) {
                count++;
                if (count > 9) count = 0; // วนกลับ 0
                PORTD = (PORTD & 0x80) | SEG_LUT[count];
            }
        }
        last_up = cur_up;

        // ตรวจจับปุ่ม DOWN (ขอบขาลง 1 -> 0)
        if (last_down == 1 && cur_down == 0) {
            _delay_ms(20); // Debounce
            if (!(PINB & (1 << SW_DOWN_PIN))) {
                count--;
                if (count < 0) count = 9; // วนกลับ 9
                PORTD = (PORTD & 0x80) | SEG_LUT[count];
            }
        }
        last_down = cur_down;

        // ตรวจจับปุ่ม RESET (ขอบขาลง 1 -> 0)
        if (last_reset == 1 && cur_reset == 0) {
            _delay_ms(20); // Debounce
            if (!(PINB & (1 << SW_RESET_PIN))) {
                count = 0;
                PORTD = (PORTD & 0x80) | SEG_LUT[count];
            }
        }
        last_reset = cur_reset;

        _delay_ms(10);
    }

    return 0;
}

