#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

const uint8_t seg_digits[10] = {
    0x3F, 0x06, 0x5B, 0x4F, 0x66, 0x6D, 0x7D, 0x07, 0x7F, 0x6F
};

int main(void) {
    DDRD = 0x7F;        // PD0..PD6 Output for 7Seg
    PORTD = seg_digits[9]; // Initial display 9
    DDRB &= ~((1 << PB0) | (1 << PB1)); // PB0: Start, PB1: Reset
    PORTB |= (1 << PB0) | (1 << PB1);   // Pull-Up
    DDRB |= (1 << PB2);                 // PB2: Alarm LED
    PORTB &= ~(1 << PB2);

    int8_t val = 9;
    uint8_t running = 0;

    while (1) {
        if (!(PINB & (1 << PB0))) {
            _delay_ms(20);
            if (!(PINB & (1 << PB0))) running = 1;
        }
        if (!(PINB & (1 << PB1))) {
            _delay_ms(20);
            if (!(PINB & (1 << PB1))) {
                running = 0;
                val = 9;
                PORTB &= ~(1 << PB2);
                PORTD = seg_digits[9];
            }
        }

        if (running) {
            PORTD = seg_digits[val];
            _delay_ms(800);
            if (val > 0) {
                val--;
            } else {
                running = 0;
                // Alarm trigger: flash LED and 7seg '0' 5 times
                for (int i = 0; i < 5; i++) {
                    PORTB |= (1 << PB2);
                    PORTD = seg_digits[0];
                    _delay_ms(150);
                    PORTB &= ~(1 << PB2);
                    PORTD = 0;
                    _delay_ms(150);
                }
                PORTD = seg_digits[0];
            }
        }
        _delay_ms(50);
    }
    return 0;
}

