#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

const uint8_t seg_digits[10] = {
    0x3F, 0x06, 0x5B, 0x4F, 0x66, 0x6D, 0x7D, 0x07, 0x7F, 0x6F
};
const uint8_t mod_limits[4] = {4, 6, 8, 10};

int main(void) {
    DDRD = 0x7F;
    PORTD = seg_digits[0];
    DDRB &= ~((1 << PB0) | (1 << PB1)); // PB0: Count, PB1: Mod Select
    PORTB |= (1 << PB0) | (1 << PB1);
    DDRB |= (1 << PB2); // Limit indicator LED
    PORTB &= ~(1 << PB2);

    uint8_t count = 0;
    uint8_t mod_idx = 1; // Default mod 6 (0..5)
    uint8_t last_c = 1, last_m = 1;

    while (1) {
        uint8_t c = (PINB & (1 << PB0)) ? 1 : 0;
        uint8_t m = (PINB & (1 << PB1)) ? 1 : 0;

        if (last_c == 1 && c == 0) {
            _delay_ms(20);
            if (!(PINB & (1 << PB0))) {
                count = (count + 1) % mod_limits[mod_idx];
            }
        }
        last_c = c;

        if (last_m == 1 && m == 0) {
            _delay_ms(20);
            if (!(PINB & (1 << PB1))) {
                mod_idx = (mod_idx + 1) % 4;
                count = 0;
            }
        }
        last_m = m;

        PORTD = seg_digits[count];
        // Turn ON indicator LED if at limit - 1
        if (count == mod_limits[mod_idx] - 1) PORTB |= (1 << PB2);
        else PORTB &= ~(1 << PB2);

        _delay_ms(20);
    }
    return 0;
}

