#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

// Outer perimeter segments: a(0), b(1), c(2), d(3), e(4), f(5)
const uint8_t ring_cw[6] = {
    (1 << 0), // a
    (1 << 1), // b
    (1 << 2), // c
    (1 << 3), // d
    (1 << 4), // e
    (1 << 5)  // f
};

int main(void) {
    DDRD = 0x7F;
    PORTD = 0x00;
    DDRB &= ~((1 << PB0) | (1 << PB1)); // PB0: Dir, PB1: Speed
    PORTB |= (1 << PB0) | (1 << PB1);

    int8_t step = 0;
    int8_t dir = 1; // 1 = CW, -1 = CCW
    uint8_t speed_fast = 0;
    uint8_t last_d = 1, last_s = 1;

    while (1) {
        uint8_t d = (PINB & (1 << PB0)) ? 1 : 0;
        uint8_t s = (PINB & (1 << PB1)) ? 1 : 0;

        if (last_d == 1 && d == 0) {
            _delay_ms(20);
            if (!(PINB & (1 << PB0))) dir = -dir;
        }
        last_d = d;

        if (last_s == 1 && s == 0) {
            _delay_ms(20);
            if (!(PINB & (1 << PB1))) speed_fast = !speed_fast;
        }
        last_s = s;

        PORTD = ring_cw[step];
        step = (step + dir + 6) % 6;

        if (speed_fast) _delay_ms(50);
        else _delay_ms(150);
    }
    return 0;
}

