arduinoCode:
/**
 * ==============================================================================
 * Project: Sample 15 - ลูกเต๋าอิเล็กทรอนิกส์ 1-6 สุ่มตัวเลขบน 7-Segment (Electronic Dice)
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (AVR-GCC)
 * Author: Embedded System Design Exam Preparation (CDTI)
 * ==============================================================================
 * 
 * [รายละเอียดฮาร์ดแวร์]
 * 1. ตัวแสดงผล 7-Segment (1 หลัก ชนิด Common Cathode):
 *    - ขั้ว a -> PD0 (Arduino Pin 0) ผ่าน R = 470 โอห์ม
 *    - ขั้ว b -> PD1 (Arduino Pin 1) ผ่าน R = 470 โอห์ม
 *    - ขั้ว c -> PD2 (Arduino Pin 2) ผ่าน R = 470 โอห์ม
 *    - ขั้ว d -> PD3 (Arduino Pin 3) ผ่าน R = 470 โอห์ม
 *    - ขั้ว e -> PD4 (Arduino Pin 4) ผ่าน R = 470 โอห์ม
 *    - ขั้ว f -> PD5 (Arduino Pin 5) ผ่าน R = 470 โอห์ม
 *    - ขั้ว g -> PD6 (Arduino Pin 6) ผ่าน R = 470 โอห์ม
 *    - ขั้ว COM (Pin 3 หรือ 8) ต่อลง GND
 *
 * 2. หลอดไฟแจ้งเตือนรางวัลใหญ่ (Jackpot LED - ทอยได้เลข 6):
 *    - ขั้ว Anode -> PB2 (Arduino Pin 10) ผ่าน R = 470 โอห์ม
 *    - ขั้ว Cathode -> GND
 *
 * 3. สวิตช์ปุ่มกดทอยลูกเต๋า (SW_ROLL):
 *    - ต่อเข้ากับ PB0 (Arduino Pin 8) ใช้ Internal Pull-up (Active-Low)
 * 
 * [หลักการทำงานของเกมลูกเต๋า]
 * - สถานะรอ (Standby): แสดงขีดกลาง '-' บน 7-Segment
 * - เมื่อกดปุ่ม SW_ROLL ค้างไว้: ตัวเลข 1 ถึง 6 จะหมุนวนอย่างรวดเร็ว (ความเร็วสูง ~25ms ต่อเฟรม)
 * - เมื่อปล่อยปุ่ม: ระบบจะเข้าสู่โหมด "ชะลอความเร็ว" (Deceleration Animation)
 *   โดยเพิ่มระยะเวลาหน่วงในแต่ละก้าว (25ms -> 50ms -> 90ms -> 150ms -> 240ms -> 380ms -> 550ms)
 * - หยุดที่ตัวเลขสุดท้ายที่สุ่มได้ (1 ถึง 6)
 * - หากทอยได้เลข 6: หลอดไฟ Jackpot LED จะกะพริบฉลอง 5 ครั้ง พร้อมตัวเลขกะพริบ
 * ==============================================================================
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>
#include <stdbool.h>

#define SW_ROLL_PIN     PB0     // Arduino Pin 8 (Roll Button)
#define LED_JACKPOT_PIN PB2     // Arduino Pin 10 (Jackpot Indicator)

// ตารางถอดรหัสตัวเลข 1-6 และสัญลักษณ์ขีดกลาง '-' สำหรับ Common Cathode
// บิต: [dp g f e d c b a]
const uint8_t DICE_LUT[7] = {
    0x40,  // Index 0: สัญลักษณ์ '-' (ขีดกลาง segment g)
    0x06,  // Index 1: เลข 1 (b, c)
    0x5B,  // Index 2: เลข 2 (a, b, d, e, g)
    0x4F,  // Index 3: เลข 3 (a, b, c, d, g)
    0x66,  // Index 4: เลข 4 (b, c, f, g)
    0x6D,  // Index 5: เลข 5 (a, c, d, f, g)
    0x7D   // Index 6: เลข 6 (a, c, d, e, f, g)
};

/**
 * ฟังก์ชันส่งรหัสออกพอร์ต D เพื่อแสดงผลบน 7-Segment
 */
void display_dice(uint8_t num) {
    if (num <= 6) {
        PORTD = DICE_LUT[num];
    }
}

int main(void) {
    // --------------------------------------------------------------------------
    // 1. ตั้งค่าทิศทางพอร์ต I/O
    // --------------------------------------------------------------------------
    // PD0 - PD6 เป็น OUTPUT (1) เพื่อขับ 7-Segment a-g
    DDRD |= 0b01111111;
    PORTD = 0x00;

    // PB2 (Jackpot LED) เป็น OUTPUT
    DDRB |= (1 << LED_JACKPOT_PIN);
    PORTB &= ~(1 << LED_JACKPOT_PIN); // ดับไฟเริ่มต้น

    // PB0 (SW_ROLL) เป็น INPUT พร้อมเปิด Internal Pull-up
    DDRB &= ~(1 << SW_ROLL_PIN);
    PORTB |= (1 << SW_ROLL_PIN);

    // แสดงสัญลักษณ์ '-' เริ่มต้น
    display_dice(0);

    uint8_t current_dice = 1;

    while (1) {
        // ตรวจสอบว่ามีการกดปุ่ม SW_ROLL หรือไม่ (Active-Low: 0 คือกด)
        if (!(PINB & (1 << SW_ROLL_PIN))) {
            _delay_ms(15); // Debounce
            if (!(PINB & (1 << SW_ROLL_PIN))) {
                PORTB &= ~(1 << LED_JACKPOT_PIN); // ดับไฟแจ็กพอต

                // --- เฟสที่ 1: หมุนเร็วต่อเนื่องตราบใดที่ยังกดปุ่มค้างอยู่ ---
                while (!(PINB & (1 << SW_ROLL_PIN))) {
                    current_dice++;
                    if (current_dice > 6) {
                        current_dice = 1;
                    }
                    display_dice(current_dice);
                    _delay_ms(25); // หมุนไวมากสร้างความสุ่มตามจังหวะปล่อยมือของผู้เล่น
                }

                // --- เฟสที่ 2: หน่วงเวลาชะลอความเร็ว (Deceleration / Slow Down) ---
                // กำหนดช่วงการหน่วงเวลาค่อยๆ ยืดออกสร้างเอฟเฟกต์ลูกเต๋าใกล้หยุด
                const uint16_t slow_delays[] = { 40, 70, 110, 160, 230, 320, 450, 600 };
                uint8_t total_steps = sizeof(slow_delays) / sizeof(slow_delays[0]);

                for (uint8_t i = 0; i < total_steps; i++) {
                    current_dice++;
                    if (current_dice > 6) {
                        current_dice = 1;
                    }
                    display_dice(current_dice);

                    // หน่วงเวลาตามอาร์เรย์แบบไดนามิก
                    for (uint16_t d = 0; d < slow_delays[i]; d += 10) {
                        _delay_ms(10);
                    }
                }

                // --- เฟสที่ 3: หยุดนิ่งที่ผลลัพธ์สุดท้าย ---
                // หากทอยได้เลข 6 (Jackpot!) ให้กะพริบไฟและหน้าจอฉลอง
                if (current_dice == 6) {
                    for (uint8_t b = 0; b < 5; b++) {
                        PORTB |= (1 << LED_JACKPOT_PIN);
                        PORTD = 0x00; // ดับเลข
                        _delay_ms(120);

                        PORTB &= ~(1 << LED_JACKPOT_PIN);
                        display_dice(6); // ติดเลข 6
                        _delay_ms(120);
                    }
                }

                _delay_ms(300); // ป้องกันการกดซ้ำซ้อนทันที
            }
        }

        _delay_ms(10);
    }

    return 0;
}

