/**
 * ==============================================================================
 * Project: Sample 11 - นาฬิกาจับเวลา 0-9 วินาที ด้วย Hardware Timer1 CTC Mode แสดงผล 7-Segment
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (AVR-GCC)
 * Author: Embedded System Design Exam Preparation (CDTI)
 * ==============================================================================
 * 
 * [หลักการและทฤษฎีการทำงาน]
 * 1. Hardware Timer1 (16-bit Timer/Counter):
 *    - ตั้งค่าโหมด CTC (Clear Timer on Compare Match) โหมด 4 (WGM12 = 1 ใน TCCR1B)
 *    - ความถี่สัญญาณนาฬิกา F_CPU = 16,000,000 Hz
 *    - เลือกใช้ Prescaler = 1024 (บิต CS12 = 1, CS10 = 1 ใน TCCR1B)
 *    - อัตราการนับของ Timer1 = 16,000,000 / 1024 = 15,625 Hz (Ticks ต่อวินาที)
 *    - คำนวณค่า OCR1A สำหรับเวลา 1 วินาที:
 *        OCR1A = (F_CPU / (Prescaler * F_target)) - 1
 *        OCR1A = (16,000,000 / (1024 * 1)) - 1 = 15,625 - 1 = 15,624 (0x3D08)
 *    - เปิดใช้งานอินเตอร์รัปต์ Compare Match A: TIMSK1 |= (1 << OCIE1A)
 *    - เมื่อ Timer1 นับถึง 15,624 จะเกิดเวกเตอร์อินเตอร์รัปต์ TIMER1_COMPA_vect ทุกๆ 1.000 วินาทีพอดี
 *
 * 2. การควบคุม (User Controls):
 *    - SW_START_STOP (Pin 8 / PB0): กดเพื่อ Start (เริ่มนับ) หรือ Pause (หยุดชั่วคราว)
 *    - SW_RESET      (Pin 9 / PB1): กดเพื่อ Reset ค่ากลับเป็น 0 และหยุดการนับ
 *
 * 3. การแสดงผล (7-Segment Common Cathode):
 *    - ขั้ว a-g ต่อเข้ากับพอร์ต PD0-PD6 ผ่านตัวต้านทาน 470 โอห์ม
 *    - ขั้ว dp ต่อเข้ากับ PD7 สำหรับกะพริบแสดงสถานะกำลังเดินเวลา (Running Indicator)
 * ==============================================================================
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <avr/interrupt.h>
#include <util/delay.h>
#include <stdbool.h>

// กำหนดนิยามขาของสวิตช์
#define SW_START_STOP_PIN   PB0     // Arduino Pin 8 (Start/Pause Toggle)
#define SW_RESET_PIN        PB1     // Arduino Pin 9 (Reset to 0)

// ตาราง Lookup Table รหัส 7-Segment (Common Cathode - Active High)
// รูปแบบบิต: [dp g f e d c b a]
const uint8_t SEG_LUT[10] = {
    0x3F,  // 0 : a, b, c, d, e, f
    0x06,  // 1 : b, c
    0x5B,  // 2 : a, b, d, e, g
    0x4F,  // 3 : a, b, c, d, g
    0x66,  // 4 : b, c, f, g
    0x6D,  // 5 : a, c, d, f, g
    0x7D,  // 6 : a, c, d, e, f, g
    0x07,  // 7 : a, b, c
    0x7F,  // 8 : a, b, c, d, e, f, g
    0x6F   // 9 : a, b, c, d, f, g
};

// ตัวแปรส่วนกลาง (แชร์ระหว่าง Main Loop และ ISR ต้องระบุ volatile)
volatile uint8_t g_seconds = 0;          // ตัวนับวินาที 0 - 9
volatile bool    g_is_running = false;    // สถานะการจับเวลา (true = กำลังนับ, false = หยุด)
volatile bool    g_dp_state = false;      // สถานะจุด DP

/**
 * ฟังก์ชันเริ่มต้นตั้งค่า Hardware Timer1 ในโหมด CTC ความถี่ 1 Hz
 */
void timer1_init_ctc(void) {
    // 1. ล้างค่ารีจิสเตอร์ TCCR1A และ TCCR1B
    TCCR1A = 0x00;  // โหมด Normal สำหรับขา OC1A/OC1B ไม่ต้องตัดต่อขาฮาร์ดแวร์โดยตรง
    TCCR1B = 0x00;
    TCNT1  = 0;     // รีเซ็ตตัวนับ Timer เป็น 0

    // 2. กำหนดค่าเปรียบเทียบใน OCR1A เพื่อให้เกิดอินเตอร์รัปต์ทุกๆ 1 วินาที
    // 16,000,000 / (1024 * 1) - 1 = 15,624 (0x3D08)
    OCR1A = 15624;

    // 3. ตั้งค่าโหมด CTC (Mode 4: WGM12 = 1 ใน TCCR1B)
    TCCR1B |= (1 << WGM12);

    // 4. เปิดใช้งานอินเตอร์รัปต์ Output Compare A Match
    TIMSK1 |= (1 << OCIE1A);

    // ยังไม่เริ่มจ่ายสัญญาณนาฬิกา (Prescaler = 0) จนกว่าจะกดปุ่ม Start
}

/**
 * ฟังก์ชันเปิดสัญญาณนาฬิกาให้ Timer1 เริ่มนับ (Prescaler 1024)
 */
void timer1_start(void) {
    // บิต CS12 = 1, CS10 = 1 สำหรับ Prescaler 1024
    TCCR1B |= (1 << CS12) | (1 << CS10);
    g_is_running = true;
}

/**
 * ฟังก์ชันหยุดสัญญาณนาฬิกา Timer1 ชั่วคราว (Pause)
 */
void timer1_stop(void) {
    // ปิดบิต CS12, CS11, CS10 (CS = 000 หมายถึงหยุดการจ่ายสัญญาณนาฬิกา)
    TCCR1B &= ~((1 << CS12) | (1 << CS11) | (1 << CS10));
    g_is_running = false;
}

/**
 * ฟังก์ชันแสดงผลตัวเลขบน 7-Segment (พอร์ต D)
 */
void display_digit(uint8_t num, bool show_dp) {
    if (num > 9) num = 9;
    uint8_t pattern = SEG_LUT[num];
    if (show_dp) {
        pattern |= 0x80; // บิตที่ 7 คือขั้ว DP (PD7)
    }
    PORTD = pattern;
}

/**
 * Interrupt Service Routine (ISR) สำหรับ Timer1 Compare Match A
 * จะถูกเรียกทำงานโดยอัตโนมัติทุกๆ 1.000 วินาที เมื่อ Timer1 กำลังทำงาน
 */
ISR(TIMER1_COMPA_vect) {
    if (g_is_running) {
        g_seconds++;
        if (g_seconds > 9) {
            g_seconds = 0; // วนกลับมา 0 เมื่อครบ 9 วินาที
        }
        g_dp_state = !g_dp_state; // สลับสถานะจุดทศนิยม DP เพื่อแสดงจังหวะ 1 วินาที
    }
}

int main(void) {
    // --------------------------------------------------------------------------
    // 1. ตั้งค่าทิศทางพอร์ต (Data Direction Registers)
    // --------------------------------------------------------------------------
    // PD0 - PD7 เป็น OUTPUT (1) เพื่อขับเซกเมนต์ a-g และ dp
    DDRD = 0xFF;
    PORTD = 0x00; // ปิดเซกเมนต์ทั้งหมดเริ่มต้น

    // PB0, PB1 เป็น INPUT (0) สำหรับสวิตช์
    DDRB &= ~((1 << SW_START_STOP_PIN) | (1 << SW_RESET_PIN));

    // เปิดใช้งาน Internal Pull-up Resistor ที่ PB0, PB1
    PORTB |= (1 << SW_START_STOP_PIN) | (1 << SW_RESET_PIN);

    // --------------------------------------------------------------------------
    // 2. เริ่มต้นระบบ Timer1 และเปิด Global Interrupt
    // --------------------------------------------------------------------------
    timer1_init_ctc();
    sei(); // เปิดการทำงานของระบบอินเตอร์รัปต์ส่วนกลาง (Set Global Interrupt Flag I)

    // แสดงผลเลข 0 เริ่มต้น
    display_digit(g_seconds, false);

    // ตัวแปรเก็บสถานะก่อนหน้าของปุ่มกดเพื่อตรวจจับขอบขาลง (Edge Detection)
    uint8_t prev_sw_start = 1;
    uint8_t prev_sw_reset = 1;

    // --------------------------------------------------------------------------
    // 3. วนลูปหลัก (Super-Loop)
    // --------------------------------------------------------------------------
    while (1) {
        // อ่านค่าสถานะปัจจุบันของปุ่มกด (Active-Low: 0 คือกด, 1 คือปล่อย)
        uint8_t curr_sw_start = (PINB & (1 << SW_START_STOP_PIN)) ? 1 : 0;
        uint8_t curr_sw_reset = (PINB & (1 << SW_RESET_PIN)) ? 1 : 0;

        // ตรวจจับการกดปุ่ม START/STOP (Transition: 1 -> 0)
        if (prev_sw_start == 1 && curr_sw_start == 0) {
            _delay_ms(20); // Software Debounce 20ms
            if (!(PINB & (1 << SW_START_STOP_PIN))) { // ตรวจสอบยืนยัน
                if (g_is_running) {
                    timer1_stop(); // กำลังเดินอยู่ -> หยุดชั่วคราว (Pause)
                } else {
                    timer1_start(); // หยุดอยู่ -> สั่งเริ่มนับ (Start)
                }
            }
        }
        prev_sw_start = curr_sw_start;

        // ตรวจจับการกดปุ่ม RESET (Transition: 1 -> 0)
        if (prev_sw_reset == 1 && curr_sw_reset == 0) {
            _delay_ms(20); // Software Debounce 20ms
            if (!(PINB & (1 << SW_RESET_PIN))) { // ตรวจสอบยืนยัน
                timer1_stop();   // หยุดการนับทันที
                TCNT1 = 0;       // รีเซ็ตค่าตัวนับเวลาฮาร์ดแวร์ใน Timer1 กลับเป็น 0
                g_seconds = 0;   // รีเซ็ตตัวเลขวินาทีเป็น 0
                g_dp_state = false;
            }
        }
        prev_sw_reset = curr_sw_reset;

        // อัปเดตการแสดงผลบน 7-Segment ตลอดเวลา
        display_digit(g_seconds, g_is_running ? g_dp_state : false);

        _delay_ms(10); // หน่วงเวลาการประมวลผลลูปสั้นๆ
    }

    return 0;
}

