/**
 * ==============================================================================
 * Project: Sample 05 - ระบบอินเทอร์รัปต์ภายนอก (External Interrupt INT0) ควบคุม LED
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (AVR-GCC)
 * Author: Embedded System Design Exam Preparation (CDTI)
 * ==============================================================================
 * 
 * [รายละเอียดฮาร์ดแวร์]
 * - ปุ่มกดฉุกเฉิน / สวิตช์ตรวจจับเหตุการณ์ (Interrupt SW): ต่อเข้ากับขา Digital Pin 2 (PD2 / INT0)
 *   * เปิด Internal Pull-up (Active-Low)
 * - หลอดไฟ LED 6 ดวง: ต่อเข้ากับขา Digital Pin 8 ถึง 13 (PB0 ถึง PB5)
 *   * ขับไฟวิ่งเป็นงานเบื้องหลัง (Background Task)
 *
 * [ทฤษฎีและการทำงานของ Interrupt]
 * 1. CPU ทำงานวนรอบไฟวิ่งในลูปหลัก (Main Loop) ตลอดเวลา
 * 2. เมื่อมีสัญญาณกดสวิตช์ที่ขา PD2 (INT0) เกิดสัญญาณขอบขาลง (Falling Edge: 1 -> 0)
 * 3. ฮาร์ดแวร์จะพักการทำงานของลูปหลักทันที แล้วกระโดดไปประมวลผลฟังก์ชัน ISR(INT0_vect)
 * 4. ใน ISR จะทำการสลับทิศทางการวิ่ง หรือสั่งหยุดชั่วขณะ (Toggle Pause/Run) แล้วกลับมาทำงานต่อ
 * 5. ไม่มีการหน่วงเวลาหรือเสียจังหวะตรวจจับ (Zero Latency Response)
 * ==============================================================================
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <avr/interrupt.h>  // ไลบรารีสำหรับ Interrupt (sei, cli, ISR)
#include <util/delay.h>

#define LED_MASK    0b00111111  // PB0 ถึง PB5
#define INT0_PIN    PD2         // ขา INT0 บน ATmega328P

// ตัวแปรที่ใช้งานร่วมกันระหว่าง ISR และ Main Loop ต้องประกาศเป็น 'volatile' เสมอ
// เพื่อป้องกันคอมไพเลอร์ Optimize ค่าในรีจิสเตอร์ทิ้ง
volatile uint8_t is_paused = 0;
volatile uint8_t run_direction = 1; // 1 = วิ่งขึ้น, 0 = วิ่งลง

// ------------------------------------------------------------------------------
// Interrupt Service Routine (ISR) สำหรับ INT0 (External Interrupt 0)
// ------------------------------------------------------------------------------
ISR(INT0_vect) {
    // กำจัดสัญญาณกระดอนแบบสั้น (Debounce ภายใน ISR)
    _delay_ms(15);
    if (!(PIND & (1 << INT0_PIN))) {
        // สลับทิศทางการวิ่งของไฟทันทีที่เกิดการกดปุ่ม
        run_direction ^= 1;
    }
}

int main(void) {
    // --------------------------------------------------------------------------
    // 1. ตั้งค่าทิศทางพอร์ต (I/O Configuration)
    // --------------------------------------------------------------------------
    DDRB |= LED_MASK;           // PB0 - PB5 เป็น OUTPUT สำหรับ LED
    DDRD &= ~(1 << INT0_PIN);   // PD2 (INT0) เป็น INPUT

    PORTD |= (1 << INT0_PIN);   // เปิด Internal Pull-Up บนขา PD2 (INT0)
    PORTB &= ~LED_MASK;         // เริ่มต้นดับไฟ LED ทั้งหมด

    // --------------------------------------------------------------------------
    // 2. ตั้งค่า External Interrupt Registers (หัวใจของบทเรียน Mazidi Ch.10)
    // --------------------------------------------------------------------------
    // EICRA (External Interrupt Control Register A):
    // กำหนดรูปแบบการกระตุ้น (Trigger Sense Control):
    // ISC01 = 1, ISC00 = 0 -> ตรวจจับสัญญาณขอบขาลง (The falling edge of INT0 generates an interrupt)
    EICRA |= (1 << ISC01);
    EICRA &= ~(1 << ISC00);

    // EIMSK (External Interrupt Mask Register):
    // เปิดใช้งานอินเทอร์รัปต์ภายนอกช่อง INT0 (เซ็ตบิต INT0 = 1)
    EIMSK |= (1 << INT0);

    // เปิดใช้งาน Global Interrupt Enable (I-bit ใน SREG)
    sei();                      // ส่งคำสั่ง Assembly: SEI

    // --------------------------------------------------------------------------
    // 3. ลูปการทำงานเบื้องหลัง (Background Task)
    // --------------------------------------------------------------------------
    int8_t current_pos = 0;

    while (1) {
        // แสดงผลหลอดไฟปัจจุบัน
        PORTB = (PORTB & ~LED_MASK) | (1 << current_pos);
        _delay_ms(120);

        // คำนวณตำแหน่งถัดไปตามตัวแปร run_direction ที่อาจถูกเปลี่ยนค่าโดย ISR ทุกเมื่อ!
        if (run_direction) {
            current_pos++;
            if (current_pos > 5) current_pos = 0;
        } else {
            current_pos--;
            if (current_pos < 0) current_pos = 5;
        }
    }

    return 0;
}

