#include <avr/io.h>
#include <avr/interrupt.h>
#include <util/delay.h>

ISR(INT0_vect) {
    PORTB ^= (1 << PB0); // Toggle LED 1
}

ISR(INT1_vect) {
    PORTB ^= (1 << PB1); // Toggle LED 2
}

int main(void) {
    DDRB |= (1 << PB0) | (1 << PB1); // PB0, PB1 Output
    PORTB &= ~((1 << PB0) | (1 << PB1));

    DDRD &= ~((1 << PD2) | (1 << PD3)); // PD2 (INT0), PD3 (INT1) Input
    PORTD |= (1 << PD2) | (1 << PD3);   // Enable Pull-Ups

    // Configure External Interrupts on Falling Edge:
    // ISC01=1, ISC00=0 (INT0 Falling)
    // ISC11=1, ISC10=0 (INT1 Falling)
    EICRA |= (1 << ISC01) | (1 << ISC11);
    EICRA &= ~((1 << ISC00) | (1 << ISC10));

    // Enable INT0 and INT1 masks
    EIMSK |= (1 << INT0) | (1 << INT1);

    sei(); // Enable Global Interrupts

    while (1) {
        // Main loop is free to perform other tasks
        _delay_ms(100);
    }
    return 0;
}

