ISR(TIMER1_COMPA_vect) {
    // Exact 1.000 Hz interrupt
    PORTB ^= (1 << PB0); // Toggle Heartbeat LED
    seconds = (seconds + 1) & 0x0F; // 0..15 counter
    PORTB = (PORTB & ~0x1E) | (seconds << 1); // Output on PB1..PB4
}

