    DDRB |= 0x1F;   // PB0..PB4 Output
    PORTB &= ~0x1F;

    // Timer 1 Configuration: CTC Mode (Mode 4: WGM12 = 1)
    TCCR1A = 0;
    TCCR1B = (1 << WGM12) | (1 << CS12) | (1 << CS10); // Prescaler = 1024

    // OCR1A = (16MHz / (1024 * 1Hz)) - 1 = 15624
    OCR1A = 15624;

    // Enable Timer1 Compare Match A Interrupt
    TIMSK1 |= (1 << OCIE1A);

    sei(); // Global Interrupt Enable

    while (1) {
        // CPU can sleep or run main app
    }
    return 0;
}

