/*
 * Project: Sample 29 - Variable LED Blink Rate Controlled by Potentiometer (ADC0)
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (avr-gcc)
 *
 * Description:
 * - อ่านค่าแอนะล็อก ADC0 (0-1023) จาก Potentiometer 10k
 * - แปลงค่า ADC เป็นระยะเวลาหน่วงในการกระพริบของ LED (50 ms ถึง 1000 ms)
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

void adc_init(void) {
    ADMUX = (1 << REFS0); // AVCC ref, ADC0
    ADCSRA = (1 << ADEN) | (1 << ADPS2) | (1 << ADPS1) | (1 << ADPS0); // Prescaler 128
}

uint16_t adc_read(void) {
    ADCSRA |= (1 << ADSC);
    while (ADCSRA & (1 << ADSC));
    return ADC;
}

void delay_var_ms(uint16_t ms) {
    while (ms--) {
        _delay_ms(1);
    }
}

int main(void) {
    DDRB |= (1 << PB0);   // PB0 Output
    PORTB &= ~(1 << PB0);

    adc_init();

    while (1) {
        uint16_t val = adc_read();
        // คำนวณช่วงเวลา: 50ms + (val * 950 / 1023)
        uint16_t delay_time = 50 + ((uint32_t)val * 950) / 1023;

        PORTB ^= (1 << PB0); // สลับไฟติด/ดับ
        delay_var_ms(delay_time);
    }
    return 0;
}

