#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

uint16_t adc_read(void) {
    ADCSRA |= (1 << ADSC);
    while (ADCSRA & (1 << ADSC));
    return ADC;
}

int main(void) {
    DDRB |= (1 << PB0) | (1 << PB1); // PB0: Night Lamp, PB1: Day Status
    PORTB &= ~((1 << PB0) | (1 << PB1));

    // ADC Setup: AVcc reference, Prescaler 128
    ADMUX = (1 << REFS0);
    ADCSRA = (1 << ADEN) | (1 << ADPS2) | (1 << ADPS1) | (1 << ADPS0);

    // Hysteresis thresholds:
    // Low threshold: <1.8V (<368) -> Turn ON Night Lamp
    // High threshold: >3.2V (>655) -> Turn OFF Night Lamp
    uint8_t lamp_on = 0;

    while (1) {
        uint16_t val = adc_read();

        if (val < 368) {
            lamp_on = 1; // Darkness detected
        } else if (val > 655) {
            lamp_on = 0; // Daylight detected
        }
        // Between 368 and 655: Maintain state (No chattering!)

        if (lamp_on) {
            PORTB |= (1 << PB0);
            PORTB &= ~(1 << PB1);
        } else {
            PORTB &= ~(1 << PB0);
            PORTB |= (1 << PB1);
        }
        _delay_ms(100);
    }
    return 0;
}

