/*
 * Project: Sample 30 - 3-Level Voltage Window Comparator with 3 LEDs (ADC0)
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (avr-gcc)
 *
 * Description:
 * - ตรวจสอบระดับแรงดันแอนะล็อก 3 ช่วง:
 *   1. V < 1.5V (ADC < 307): ไฟเหลือง UNDER (PB0) ติด
 *   2. 1.5V <= V <= 3.5V (307 <= ADC <= 716): ไฟเขียว NORMAL (PB1) ติด
 *   3. V > 3.5V (ADC > 716): ไฟแดง OVER (PB2) ติด
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

void adc_init(void) {
    ADMUX = (1 << REFS0);
    ADCSRA = (1 << ADEN) | (1 << ADPS2) | (1 << ADPS1) | (1 << ADPS0);
}

uint16_t adc_read(void) {
    ADCSRA |= (1 << ADSC);
    while (ADCSRA & (1 << ADSC));
    return ADC;
}

int main(void) {
    DDRB |= 0x07;       // PB0, PB1, PB2 Output
    PORTB &= ~0x07;

    adc_init();

    while (1) {
        uint16_t adc_val = adc_read();

        PORTB &= ~0x07; // ล้างไฟทุกดวงก่อนเปรียบเทียบ

        if (adc_val < 307) {
            PORTB |= (1 << PB0); // Yellow (Under)
        } else if (adc_val <= 716) {
            PORTB |= (1 << PB1); // Green (Normal)
        } else {
            PORTB |= (1 << PB2); // Red (Over)
        }

        _delay_ms(50);
    }
    return 0;
}

