#include <util/delay.h>

uint16_t adc_read(void) {
    ADCSRA |= (1 << ADSC);
    while (ADCSRA & (1 << ADSC));
    return ADC;
}

int main(void) {
    DDRB |= 0x0F; // PB0..PB3 Output
    PORTB &= ~0x0F;

    ADMUX = (1 << REFS0);
    ADCSRA = (1 << ADEN) | (1 << ADPS2) | (1 << ADPS1) | (1 << ADPS0);

    uint8_t flash = 0;

    while (1) {
        uint16_t val = adc_read();

        if (val >= 818) { // > 4.0V: 100%
            PORTB = 0x0F;
        } else if (val >= 614) { // 3.0V - 4.0V: 75%
            PORTB = 0x07;
        } else if (val >= 409) { // 2.0V - 3.0V: 50%
            PORTB = 0x03;
        } else { // < 2.0V: Low Battery Warning! Flash PB0
            if (flash) PORTB = 0x01;
            else PORTB = 0x00;
            flash = !flash;
        }
        _delay_ms(150);
    }
    return 0;
}

