/**
 * ==============================================================================
 * Project: Sample 13 - วงจรหรี่ไฟ LED ด้วย Hardware Timer0 Fast PWM ควบคุมด้วย Potentiometer
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (AVR-GCC)
 * Author: Embedded System Design Exam Preparation (CDTI)
 * ==============================================================================
 * 
 * [หลักการและทฤษฎีการทำงาน]
 * 1. ระบบแปลงสัญญาณอนาล็อกเป็นดิจิทัล (ADC - Analog to Digital Converter):
 *    - อินพุต: ช่อง ADC0 (ขา A0 / PC0) ต่อเข้ากับขากลางของ Potentiometer 10k
 *    - แรงดันอ้างอิง: AVCC (+5V) พร้อมคาปาซิเตอร์ที่ขา AREF (REFS0=1, REFS1=0 ใน ADMUX)
 *    - อัตราการจัดรูปแบบ: เลือกระดับความละเอียด 10 บิต (0 ถึง 1023)
 *    - การแบ่งความถี่ Prescaler: 128 (ADPS2=1, ADPS1=1, ADPS0=1 ใน ADCSRA)
 *      ความถี่ ADC Clock = 16,000,000 / 128 = 125 kHz (อยู่ในช่วงมาตรฐาน 50 - 200 kHz)
 *
 * 2. การสร้างสัญญาณ PWM ด้วย Hardware Timer0 (8-bit Timer/Counter):
 *    - โหมดการทำงาน: Fast PWM Mode (Mode 3: WGM01=1, WGM00=1 ใน TCCR0A)
 *    - ขาส่งออกสัญญาณ: ขา OC0A ซึ่งตรงกับขา PD6 (Arduino Pin 6)
 *    - รูปแบบเอาต์พุต: Non-inverting Mode (COM0A1=1, COM0A0=0 ใน TCCR0A)
 *        * ลอจิก HIGH ตั้งแต่ค่า 0 จนถึงค่าใน OCR0A
 *        * ลอจิก LOW ตั้งแต่ค่า OCR0A จนถึงค่า TOP (255)
 *    - Prescaler: 64 (CS01=1, CS00=1 ใน TCCR0B)
 *    - ความถี่สัญญาณ PWM:
 *        F_PWM = F_CPU / (Prescaler * 256)
 *        F_PWM = 16,000,000 / (64 * 256) = 976.56 Hz (ความถี่มาตรฐานของขา 5 และ 6 บน Arduino Uno)
 *
 * 3. การแมปค่าและแสดงผล (Mapping & Display):
 *    - ค่า ADC (0-1023) ถูกปรับสเกลเป็น 8 บิต (0-255) ด้วยการเลื่อนบิต: OCR0A = adc_val >> 2;
 *    - ขา PB0 ถึง PB4 (Pin 8 ถึง 12) ต่อหลอด LED จำนวน 5 หลอด เพื่อแสดงระดับเปอร์เซ็นต์ความสว่าง (Bar Graph)
 * ==============================================================================
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

/**
 * ฟังก์ชันเริ่มต้นตั้งค่า ADC (ADC0 / Pin A0)
 */
void adc_init(void) {
    // 1. ตั้งค่าแรงดันอ้างอิง AVCC (5V) และเลือกช่อง ADC0 (MUX[3:0] = 0000)
    ADMUX = (1 << REFS0);

    // 2. เปิดใช้งาน ADC (ADEN) และตั้ง Prescaler = 128 (ADPS2:0 = 111)
    ADCSRA = (1 << ADEN) | (1 << ADPS2) | (1 << ADPS1) | (1 << ADPS0);
}

/**
 * ฟังก์ชันอ่านค่าแรงดันอนาล็อกจาก ADC0 (คืนค่าเป็น 0 - 1023)
 */
uint16_t adc_read(void) {
    // สั่งเริ่มต้นการแปลงสัญญาณ (Start Conversion)
    ADCSRA |= (1 << ADSC);

    // รอจนกว่ากระบวนการแปลงจะเสร็จสมบูรณ์ (บิต ADSC จะถูกเคลียร์เป็น 0 อัตโนมัติ)
    while (ADCSRA & (1 << ADSC));

    // คืนค่ารีจิสเตอร์ ADCW (ADC ขนาด 10 บิต: ADCL + ADCH)
    return ADC;
}

/**
 * ฟังก์ชันเริ่มต้นตั้งค่า Hardware Timer0 ในโหมด Fast PWM ที่ขา OC0A (Pin 6 / PD6)
 */
void timer0_pwm_init(void) {
    // 1. กำหนดขา PD6 (OC0A) เป็น Output
    DDRD |= (1 << PD6);

    // 2. ตั้งค่า TCCR0A:
    //    - COM0A1 = 1, COM0A0 = 0 (Clear OC0A on Compare Match, set at BOTTOM -> Non-inverting)
    //    - WGM01 = 1, WGM00 = 1   (Fast PWM Mode, TOP = 0xFF)
    TCCR0A = (1 << COM0A1) | (1 << WGM01) | (1 << WGM00);

    // 3. ตั้งค่า TCCR0B:
    //    - CS01 = 1, CS00 = 1 (Prescaler = 64 -> F_PWM = 976.56 Hz)
    TCCR0B = (1 << CS01) | (1 << CS00);

    // 4. กำหนด Duty Cycle เริ่มต้น = 0%
    OCR0A = 0;
}

/**
 * ฟังก์ชันอัปเดต LED Bar Graph (PB0 - PB4 / Pin 8 - Pin 12)
 */
void update_led_bar(uint8_t duty) {
    // ล้างค่าหลอดไฟทั้ง 5 หลอดเดิมก่อน
    PORTB &= ~0b00011111;

    uint8_t bar_mask = 0;
    if (duty >= 51)  bar_mask |= (1 << PB0); // >= 20%
    if (duty >= 102) bar_mask |= (1 << PB1); // >= 40%
    if (duty >= 153) bar_mask |= (1 << PB2); // >= 60%
    if (duty >= 204) bar_mask |= (1 << PB3); // >= 80%
    if (duty >= 245) bar_mask |= (1 << PB4); // >= 96%

    PORTB |= bar_mask;
}

int main(void) {
    // --------------------------------------------------------------------------
    // 1. ตั้งค่าทิศทางพอร์ต I/O
    // --------------------------------------------------------------------------
    // ขา PB0 - PB4 เป็น Output สำหรับ LED Bar Graph
    DDRB |= 0b00011111;
    PORTB &= ~0b00011111; // ดับไฟทุกดวงเริ่มต้น

    // --------------------------------------------------------------------------
    // 2. เริ่มต้นระบบ ADC และ Timer0 PWM
    // --------------------------------------------------------------------------
    adc_init();
    timer0_pwm_init();

    // --------------------------------------------------------------------------
    // 3. ลูปการทำงานหลัก (Super-Loop)
    // --------------------------------------------------------------------------
    while (1) {
        // อ่านค่าอนาล็อกจาก Potentiometer (0 - 1023)
        uint16_t raw_adc = adc_read();

        // แปลงช่วงข้อมูล 10 บิต (0-1023) ให้เป็น 8 บิต (0-255) สำหรับเขียนลง OCR0A
        uint8_t duty_cycle = (uint8_t)(raw_adc >> 2);

        // อัปเดตรีจิสเตอร์เปรียบเทียบค่า OCR0A เพื่อเปลี่ยนความกว้างพัลส์ (Duty Cycle) ทันที
        OCR0A = duty_cycle;

        // แสดงผลระดับความสว่างบน LED Bar Graph (5 ระดับ)
        update_led_bar(duty_cycle);

        _delay_ms(15); // หน่วงเวลาสั้นๆ เพื่อให้การอ่านค่านิ่งและประหยัดพลังงาน
    }

    return 0;
}

