/**
 * ==============================================================================
 * Project: Sample 06 - การอ่านสัญญาณแอนะล็อก (ADC) ด้วย Potentiometer ขับ LED Bar Graph
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (AVR-GCC)
 * Author: Embedded System Design Exam Preparation (CDTI)
 * ==============================================================================
 * 
 * [รายละเอียดฮาร์ดแวร์]
 * - ตัวต้านทานปรับค่าได้ (Potentiometer 10k โอห์ม):
 *   * ขาซ้าย ต่อเข้าไฟเลี้ยง 5V
 *   * ขาขวา ต่อลงกราวด์ GND
 *   * ขากลาง (Wiper) ต่อเข้าขา Analog Pin A0 (PC0 / ช่อง ADC0)
 * - หลอดไฟ LED 6 ดวง: ต่อเข้ากับขา Digital Pin 8 ถึง 13 (PB0 ถึง PB5)
 *   ผ่านตัวต้านทาน 470 โอห์ม
 *
 * [ทฤษฎีและการแปลงสัญญาณ ADC (Mazidi Chapter 13)]
 * 1. แรงดันอ้างอิง (Vref): ใช้ AVcc = 5.0 V
 * 2. ความละเอียด ADC: 10-bit ($2^{10} = 1024$ ระดับ, ค่าดิจิทัล 0 ถึง 1023)
 * 3. Step Size: $5.0\text{ V} / 1024 \approx 4.88\text{ mV}$
 * 4. ค่าดิจิทัล: $D_{out} = \frac{V_{in} \times 1024}{V_{ref}}$
 * 5. นำค่าดิจิทัล 0-1023 มาจัดแบ่งช่วงเป็น Bar Graph 6 ระดับ (ประมาณช่วงละ 170 ขั้น)
 * ==============================================================================
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

#define LED_MASK 0b00111111 // PB0 ถึง PB5

// ฟังก์ชันกำหนดค่าเริ่มต้นให้กับโมดูล ADC
void adc_init(void) {
    // 1. ตั้งค่า ADMUX (ADC Multiplexer Selection Register):
    // REFS0 = 1, REFS1 = 0 : เลือกแรงดันอ้างอิงเป็น AVcc (5V)
    // ADLAR = 0 : จัดข้อมูลชิดขวา (Right Adjusted 10-bit: ADCL 8 บิตล่าง, ADCH 2 บิตบน)
    // MUX3:0 = 0000 : เลือกช่องสัญญาณอนาล็อกขาเข้าเป็น ADC0 (ขา A0)
    ADMUX = (1 << REFS0);

    // 2. ตั้งค่า ADCSRA (ADC Control and Status Register A):
    // ADEN = 1 : เปิดการทำงานของวงจร ADC (ADC Enable)
    // ADPS2:0 = 111 : กำหนด Prescaler เท่ากับ 128
    // ความถี่สัญญาณนาฬิกา ADC = 16 MHz / 128 = 125 kHz (อยู่ในช่วงมาตรฐาน 50 - 200 kHz)
    ADCSRA = (1 << ADEN) | (1 << ADPS2) | (1 << ADPS1) | (1 << ADPS0);
}

// ฟังก์ชันสั่งเริ่มแปลงสัญญาณและอ่านค่า ADC 10 บิต
uint16_t adc_read(uint8_t channel) {
    // เลือกช่องสัญญาณ (จำกัดเฉพาะช่อง 0-7)
    channel &= 0x07;
    ADMUX = (ADMUX & 0xF8) | channel;

    // สั่งเริ่มต้นการแปลงสัญญาณ (Set bit ADSC = 1)
    ADCSRA |= (1 << ADSC);

    // วนลูปรอจนกระทั่งการแปลงเสร็จสมบูรณ์ (บิต ADSC จะถูกฮาร์ดแวร์เคลียร์กลับเป็น 0 อัตโนมัติ)
    while (ADCSRA & (1 << ADSC));

    // อ่านค่า 10-bit: ต้องอ่าน ADCL ก่อน ADCH เสมอ (ในภาษา C คำสั่ง ADC รวมจะจัดการให้ถูกต้อง)
    return ADC;
}

int main(void) {
    // ตั้งค่า PB0 - PB5 เป็น OUTPUT สำหรับขับ LED
    DDRB |= LED_MASK;
    PORTB &= ~LED_MASK; // ดับไฟเริ่มต้น

    // เรียกฟังก์ชันตั้งค่า ADC
    adc_init();

    while (1) {
        // อ่านค่าดิจิทัลจากช่อง ADC0 (ขา A0) ได้ค่าช่วง 0 ถึง 1023
        uint16_t adc_val = adc_read(0);

        // คำนวณรูปแบบการติดของ LED Bar Graph 6 ระดับ (บิต PB0 ถึง PB5)
        uint8_t bar_pattern = 0;

        if (adc_val >= 900) {
            bar_pattern = 0b00111111; // ติดหมด 6 หลอด (~4.4V - 5.0V)
        } else if (adc_val >= 750) {
            bar_pattern = 0b00011111; // ติด 5 หลอด (~3.6V - 4.4V)
        } else if (adc_val >= 580) {
            bar_pattern = 0b00001111; // ติด 4 หลอด (~2.8V - 3.6V)
        } else if (adc_val >= 400) {
            bar_pattern = 0b00000111; // ติด 3 หลอด (~2.0V - 2.8V)
        } else if (adc_val >= 230) {
            bar_pattern = 0b00000011; // ติด 2 หลอด (~1.1V - 2.0V)
        } else if (adc_val >= 60) {
            bar_pattern = 0b00000001; // ติด 1 หลอด (~0.3V - 1.1V)
        } else {
            bar_pattern = 0b00000000; // ดับทั้งหมด (< 0.3V)
        }

        // ส่งค่าออกพอร์ต B
        PORTB = (PORTB & ~LED_MASK) | bar_pattern;

        _delay_ms(50); // หน่วงเวลาสำหรับรีเฟรชค่า 20 ครั้งต่อวินาที
    }

    return 0;
}

