    PORTB |= (1 << LCD_RS_PIN);
    lcd_write_4bits((data >> 4) & 0x0F);
    lcd_write_4bits(data & 0x0F);
    _delay_us(50);
}

void lcd_print(const char *str) {
    while (*str) lcd_send_data(*str++);
}

void lcd_set_cursor(uint8_t row, uint8_t col) {
    uint8_t addr = (row == 0) ? (0x80 + col) : (0xC0 + col);
    lcd_send_cmd(addr);
}

void lcd_init(void) {
    DDRB |= (1 << LCD_RS_PIN) | (1 << LCD_EN_PIN);
    PORTB &= ~((1 << LCD_RS_PIN) | (1 << LCD_EN_PIN));
    DDRD |= (1 << PD2) | (1 << PD3) | (1 << PD4) | (1 << PD5);

    _delay_ms(50);
    lcd_write_4bits(0x03); _delay_ms(5);
    lcd_write_4bits(0x03); _delay_us(150);
    lcd_write_4bits(0x03); _delay_us(150);
    lcd_write_4bits(0x02); _delay_us(150);

    lcd_send_cmd(0x28); // 4-bit, 2 lines, 5x8
    lcd_send_cmd(0x0C); // Display ON, Cursor OFF
    lcd_send_cmd(0x06); // Auto increment
    lcd_send_cmd(0x01); // Clear
    _delay_ms(2);
}


void adc_init(void) {
    ADMUX = (1 << REFS0);
    ADCSRA = (1 << ADEN) | (1 << ADPS2) | (1 << ADPS1) | (1 << ADPS0);
}

uint16_t adc_read(void) {
    ADCSRA |= (1 << ADSC);
    while (ADCSRA & (1 << ADSC));
    return ADC;
}

void print_4digits(uint16_t val) {
    lcd_send_data((val / 1000) + '0');
    lcd_send_data(((val / 100) % 10) + '0');
    lcd_send_data(((val / 10) % 10) + '0');
    lcd_send_data((val % 10) + '0');
}

int main(void) {
    lcd_init();
    adc_init();

    lcd_set_cursor(0, 0);
    lcd_print("ADC Raw:        ");

    lcd_set_cursor(1, 0);
    lcd_print("Volt:    0.00 V ");

    while (1) {
        uint16_t raw = adc_read();
        uint16_t centivolts = ((uint32_t)raw * 500) / 1023; // 0..500 cV (0.00V - 5.00V)

        // แสดงผลค่า ADC Raw
        lcd_set_cursor(0, 9);
        print_4digits(raw);

        // แสดงผลค่า Volt X.XX V
        lcd_set_cursor(1, 9);
        lcd_send_data((centivolts / 100) + '0'); // เลขหน้าทศนิยม
        lcd_send_data('.');
        lcd_send_data(((centivolts / 10) % 10) + '0'); // ทศนิยมตำแหน่งที่ 1
        lcd_send_data((centivolts % 10) + '0');        // ทศนิยมตำแหน่งที่ 2

        _delay_ms(100);
    }
    return 0;
}

