    lcd_send_data(((val / 100) % 10) + '0');
    lcd_send_data(((val / 10) % 10) + '0');
    lcd_send_data((val % 10) + '0');
}

int main(void) {
    lcd_init();
    adc_init();

    lcd_set_cursor(0, 0);
    lcd_print("ADC Raw:        ");

    lcd_set_cursor(1, 0);
    lcd_print("Volt:    0.00 V ");

    while (1) {
        uint16_t raw = adc_read();
        uint16_t centivolts = ((uint32_t)raw * 500) / 1023; // 0..500 cV (0.00V - 5.00V)

        // แสดงผลค่า ADC Raw
        lcd_set_cursor(0, 9);
        print_4digits(raw);

        // แสดงผลค่า Volt X.XX V
        lcd_set_cursor(1, 9);
        lcd_send_data((centivolts / 100) + '0'); // เลขหน้าทศนิยม
        lcd_send_data('.');
        lcd_send_data(((centivolts / 10) % 10) + '0'); // ทศนิยมตำแหน่งที่ 1
        lcd_send_data((centivolts % 10) + '0');        // ทศนิยมตำแหน่งที่ 2

        _delay_ms(100);
    }
    return 0;
}

