/**
 * ==============================================================================
 * Project: Sample 07 - หน้าจอ LCD 16x2 โหมด 4-Bit (HD44780 Controller)
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (AVR-GCC)
 * Author: Embedded System Design Exam Preparation (CDTI)
 * ==============================================================================
 * 
 * [รายละเอียดฮาร์ดแวร์]
 * - จอแสดงผล LCD 16x2 (โมเดล HD44780):
 *   * RS (Register Select) : ต่อเข้า PB4 (Arduino Pin 12)  [0 = Command, 1 = Data]
 *   * EN (Enable Strobe)   : ต่อเข้า PB3 (Arduino Pin 11)  [Pulse High -> Low]
 *   * RW (Read/Write)      : ต่อลงกราวด์ GND (โหมด Write-Only ตลอดเวลา)
 *   * V0 (Contrast)        : ต่อขากลาง Potentiometer ปรับความคมชัด
 *   * D4 (Data 4)          : ต่อเข้า PD5 (Arduino Pin 5)
 *   * D5 (Data 5)          : ต่อเข้า PD4 (Arduino Pin 4)
 *   * D6 (Data 6)          : ต่อเข้า PD3 (Arduino Pin 3)
 *   * D7 (Data 7)          : ต่อเข้า PD2 (Arduino Pin 2)
 *
 * - สวิตช์ปุ่มกด SW1: ต่อเข้า PB0 (Arduino Pin 8) แบบ Pull-Up
 *   * กดปุ่มเพื่อเพิ่มค่านับแสดงบนบรรทัดที่ 2 แบบ Interactive
 * ==============================================================================
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>
#include <stdio.h>

// กำหนดนิยามขาควบคุม
#define LCD_RS_PIN     PB4     // Pin 12
#define LCD_EN_PIN     PB3     // Pin 11
#define SW_PIN         PB0     // Pin 8

// ส่งพัลส์สัญญาณ EN (Strobe Pulse: High -> Low) เพื่อให้ LCD อ่านข้อมูลบนบัส
void lcd_pulse_enable(void) {
    PORTB |= (1 << LCD_EN_PIN);
    _delay_us(2);              // Pulse width > 450 ns
    PORTB &= ~(1 << LCD_EN_PIN);
    _delay_us(50);             // Execution time delay
}

// ส่งข้อมูล 4 บิต (Half-byte / Nibble) ไปยังขา D4-D7 (PD5-PD2)
void lcd_write_4bits(uint8_t nibble) {
    // ล้างค่าเดิมบนขา PD2-PD5 ก่อน
    PORTD &= ~((1 << PD2) | (1 << PD3) | (1 << PD4) | (1 << PD5));

    // กำหนดค่าบิตตามนิบล
    if (nibble & 0x01) PORTD |= (1 << PD5); // Bit 0 -> D4
    if (nibble & 0x02) PORTD |= (1 << PD4); // Bit 1 -> D5
    if (nibble & 0x04) PORTD |= (1 << PD3); // Bit 2 -> D6
    if (nibble & 0x08) PORTD |= (1 << PD2); // Bit 3 -> D7

    lcd_pulse_enable();
}

// ส่งคำสั่ง 8 บิต (Command) ไปยัง LCD ในโหมด 4-Bit
void lcd_send_cmd(uint8_t cmd) {
    PORTB &= ~(1 << LCD_RS_PIN); // RS = 0 (Command Mode)
    lcd_write_4bits((cmd >> 4) & 0x0F); // ส่ง 4 บิตบนก่อน
    lcd_write_4bits(cmd & 0x0F);        // ส่ง 4 บิตล่างตาม
    if (cmd == 0x01 || cmd == 0x02) {
        _delay_ms(2); // คำสั่ง Clear / Home ใช้เวลาประมวลผลนานกว่าปกติ
    } else {
        _delay_us(50);
    }
}

// ส่งข้อมูลตัวอักษร 8 บิต (Data Character) ไปยัง LCD ในโหมด 4-Bit
void lcd_send_data(uint8_t data) {
    PORTB |= (1 << LCD_RS_PIN);  // RS = 1 (Data Mode)
    lcd_write_4bits((data >> 4) & 0x0F); // ส่ง 4 บิตบน
    lcd_write_4bits(data & 0x0F);        // ส่ง 4 บิตล่าง
    _delay_us(50);
}

// กำหนดตำแหน่งเคอร์เซอร์ (Row 0-1, Col 0-15)
void lcd_set_cursor(uint8_t row, uint8_t col) {
    uint8_t addr = (row == 0) ? (0x80 + col) : (0xC0 + col);
    lcd_send_cmd(addr);
}

// ส่งข้อความแบบสตริง (String) ไปยัง LCD
void lcd_print(const char *str) {
    while (*str) {
        lcd_send_data((uint8_t)*str++);
    }
}

// ฟังก์ชันเริ่มต้นการทำงานของ LCD ตามมาตรฐาน HD44780 (Initialization Sequence)
void lcd_init(void) {
    // กำหนดขาพอร์ตเป็น OUTPUT
    DDRB |= (1 << LCD_RS_PIN) | (1 << LCD_EN_PIN);
    DDRD |= (1 << PD2) | (1 << PD3) | (1 << PD4) | (1 << PD5);

    PORTB &= ~((1 << LCD_RS_PIN) | (1 << LCD_EN_PIN));
    _delay_ms(50); // รอไฟเลี้ยงคงที่หลังเปิดเครื่อง > 40ms

    // ขั้นตอน Boot เข้าสู่โหมด 4-Bit ตามสเปก Hitachi HD44780
    lcd_write_4bits(0x03);
    _delay_ms(5);
    lcd_write_4bits(0x03);
    _delay_us(150);
    lcd_write_4bits(0x03);
    _delay_us(150);
    lcd_write_4bits(0x02); // คำสั่งสลับเข้าสู่โหมด 4-Bit!
    _delay_us(150);

    // ส่งคำสั่ง Configuration
    lcd_send_cmd(0x28); // Function Set: 4-bit bus, 2 lines, 5x8 font
    lcd_send_cmd(0x0C); // Display ON, Cursor OFF, Blink OFF
    lcd_send_cmd(0x06); // Entry Mode: Increment cursor automatically
    lcd_send_cmd(0x01); // Clear Display
    _delay_ms(2);
}

int main(void) {
    // ตั้งค่าปุ่มกด SW1 (PB0) เป็น Input Pull-Up
    DDRB &= ~(1 << SW_PIN);
    PORTB |= (1 << SW_PIN);

    // เริ่มต้นหน้าจอ LCD
    lcd_init();

    // แสดงข้อความคงที่บนบรรทัดที่ 1 (Line 1)
    lcd_set_cursor(0, 0);
    lcd_print("CDTI EMBEDDED");

    uint16_t press_count = 0;
    uint8_t last_btn = 1;
    char buffer[17];

    while (1) {
        // อัปเดตข้อความบนบรรทัดที่ 2
        snprintf(buffer, sizeof(buffer), "Count: %-5u", press_count);
        lcd_set_cursor(1, 0);
        lcd_print(buffer);

        // ตรวจจับการกดปุ่ม SW1 พร้อม Debounce
        uint8_t cur_btn = (PINB & (1 << SW_PIN)) ? 1 : 0;
        if (last_btn == 1 && cur_btn == 0) {
            _delay_ms(25); // Debounce
            if (!(PINB & (1 << SW_PIN))) {
                press_count++;
            }
        }
        last_btn = cur_btn;

        _delay_ms(50);
    }

    return 0;
}

