/**
 * ==============================================================================
 * Project: Sample 12 - เกมทดสอบความเร็วในการตอบสนอง (Reaction Time Game) บน LCD 16x2
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (AVR-GCC)
 * Author: Embedded System Design Exam Preparation (CDTI)
 * ==============================================================================
 * 
 * [การเชื่อมต่อวงจรฮาร์ดแวร์]
 * 1. จอแสดงผล LCD 16x2 (โหมด 4 บิต):
 *    - ขา RS -> PB4 (Arduino Pin 12)
 *    - ขา EN -> PB3 (Arduino Pin 11)
 *    - ขา RW -> GND  (สั่งเขียนข้อมูลเข้าหน้าจอเสมอ)
 *    - ขา D4 -> PD5 (Arduino Pin 5)
 *    - ขา D5 -> PD4 (Arduino Pin 4)
 *    - ขา D6 -> PD3 (Arduino Pin 3)
 *    - ขา D7 -> PD2 (Arduino Pin 2)
 *    - ขา D0-D3 ไม่ต่อ (NC)
 *    - ขา VSS ต่อ GND, VDD ต่อ 5V, V0 ต่อขากลาง Potentiometer 10k
 *    - ขา BLA (Backlight+) ต่อ 5V ผ่าน R = 470 โอห์ม, BLK (Backlight-) ต่อ GND
 *
 * 2. หลอดไฟแจ้งเตือนเป้าหมาย (Alert Target LED):
 *    - ขั้วบวก (Anode) -> PD7 (Arduino Pin 7) ผ่านตัวต้านทาน 470 โอห์ม
 *    - ขั้วลบ (Cathode) -> GND
 *
 * 3. สวิตช์ปุ่มกด (Active-Low พร้อม Internal Pull-up):
 *    - SW_START (เริ่มเกม)     -> PB0 (Arduino Pin 8)
 *    - SW_REACT (ปุ่มกดตอบสนอง) -> PB1 (Arduino Pin 9)
 * ==============================================================================
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>
#include <stdio.h>
#include <stdbool.h>

// กำหนดนิยามขา LCD Control
#define LCD_RS_PIN      PB4     // Pin 12
#define LCD_EN_PIN      PB3     // Pin 11

// ขาหลอดไฟแจ้งเตือน
#define LED_ALERT_PIN   PD7     // Pin 7

// ขาสวิตช์ปุ่มกด
#define SW_START_PIN    PB0     // Pin 8 (Start Game)
#define SW_REACT_PIN    PB1     // Pin 9 (Hit Trigger)

// --- ฟังก์ชันควบคุมสัญญาณพัลส์ Enable ของ LCD ---
static void lcd_pulse_en(void) {
    PORTB |= (1 << LCD_EN_PIN);
    _delay_us(2);
    PORTB &= ~(1 << LCD_EN_PIN);
    _delay_us(50);
}

// --- ฟังก์ชันส่งข้อมูลระดับ Nibble (4 บิต) ไปยังขา PD2-PD5 ---
static void lcd_write_nibble(uint8_t nibble) {
    // ล้างค่าขา PD2 ถึง PD5 เดิม
    PORTD &= ~((1 << PD2) | (1 << PD3) | (1 << PD4) | (1 << PD5));

    // แมปบิต 0..3 ของ nibble เข้ากับ PD5..PD2
    // nibble bit 0 -> D4 -> PD5
    // nibble bit 1 -> D5 -> PD4
    // nibble bit 2 -> D6 -> PD3
    // nibble bit 3 -> D7 -> PD2
    if (nibble & 0x01) PORTD |= (1 << PD5);
    if (nibble & 0x02) PORTD |= (1 << PD4);
    if (nibble & 0x04) PORTD |= (1 << PD3);
    if (nibble & 0x08) PORTD |= (1 << PD2);

    lcd_pulse_en();
}

// --- ฟังก์ชันส่งคำสั่ง (Command) ขนาด 8 บิตไปยัง LCD ---
void lcd_send_cmd(uint8_t cmd) {
    PORTB &= ~(1 << LCD_RS_PIN); // RS = 0 สำหรับคำสั่ง
    lcd_write_nibble((cmd >> 4) & 0x0F); // ส่ง 4 บิตบน
    lcd_write_nibble(cmd & 0x0F);        // ส่ง 4 บิตล่าง
    if (cmd == 0x01 || cmd == 0x02) {
        _delay_ms(2); // คำสั่ง Clear Screen หรือ Return Home ใช้เวลานานกว่าปกติ
    }
}

// --- ฟังก์ชันส่งข้อมูลตัวอักษร (Data/Character) ขนาด 8 บิตไปยัง LCD ---
void lcd_send_data(uint8_t data) {
    PORTB |= (1 << LCD_RS_PIN);  // RS = 1 สำหรับข้อมูลตัวอักษร
    lcd_write_nibble((data >> 4) & 0x0F);
    lcd_write_nibble(data & 0x0F);
}

// --- ฟังก์ชันส่งข้อความสตริง ---
void lcd_print(const char *str) {
    while (*str) {
        lcd_send_data((uint8_t)*str++);
    }
}

// --- ฟังก์ชันย้ายตำแหน่ง Cursor (row: 0-1, col: 0-15) ---
void lcd_set_cursor(uint8_t row, uint8_t col) {
    uint8_t addr = (row == 0) ? (0x80 + col) : (0xC0 + col);
    lcd_send_cmd(addr);
}

// --- ฟังก์ชันเริ่มต้นการทำงานของ LCD ในโหมด 4 บิต ---
void lcd_init_4bit(void) {
    _delay_ms(50); // รอแรงดันไฟเลี้ยง LCD เสถียร (> 40ms)

    PORTB &= ~(1 << LCD_RS_PIN);

    // ลำดับการเริ่มต้นพิเศษตามมาตรฐาน HD44780
    lcd_write_nibble(0x03);
    _delay_ms(5);
    lcd_write_nibble(0x03);
    _delay_us(150);
    lcd_write_nibble(0x03);
    _delay_us(150);

    // เปลี่ยนเข้าสู่โหมด 4-Bit Interface
    lcd_write_nibble(0x02);
    _delay_us(150);

    // Function Set: 4-bit, 2 บรรทัด, ฟอนต์ 5x8
    lcd_send_cmd(0x28);
    // Display Control: เปิดจอภาพ, ปิดเคอร์เซอร์, ปิดการกะพริบ
    lcd_send_cmd(0x0C);
    // Clear Display
    lcd_send_cmd(0x01);
    // Entry Mode: เลื่อนเคอร์เซอร์ไปทางขวาอัตโนมัติ
    lcd_send_cmd(0x06);
}

// ตัวสร้างเลขสุ่มเทียมอย่างง่าย (LFSR Pseudo-Random Generator)
static uint16_t lfsr = 0xACE1;
static uint16_t get_random(void) {
    uint16_t bit = ((lfsr >> 0) ^ (lfsr >> 2) ^ (lfsr >> 3) ^ (lfsr >> 5)) & 1;
    lfsr = (lfsr >> 1) | (bit << 15);
    return lfsr;
}

int main(void) {
    // --------------------------------------------------------------------------
    // 1. ตั้งค่าพอร์ตและทิศทาง I/O
    // --------------------------------------------------------------------------
    // ขา LCD Data (PD2..PD5) และ Alert LED (PD7) เป็น Output
    DDRD |= (1 << PD2) | (1 << PD3) | (1 << PD4) | (1 << PD5) | (1 << LED_ALERT_PIN);
    PORTD &= ~(1 << LED_ALERT_PIN); // ปิดไฟ LED เริ่มต้น

    // ขา LCD Control (PB3=EN, PB4=RS) เป็น Output
    DDRB |= (1 << LCD_RS_PIN) | (1 << LCD_EN_PIN);

    // ขาสวิตช์ PB0 (SW_START), PB1 (SW_REACT) เป็น Input
    DDRB &= ~((1 << SW_START_PIN) | (1 << SW_REACT_PIN));
    // เปิด Internal Pull-up บน PB0, PB1
    PORTB |= (1 << SW_START_PIN) | (1 << SW_REACT_PIN);

