        while (PINB & (1 << SW_START_PIN)) {
            // หมุนวน LFSR seed ระหว่างรอ เพื่อให้ได้ค่าสุ่มที่ขึ้นกับจังหวะการกดของผู้เล่น
            lfsr += 37;
        }
