// --- ฟังก์ชันควบคุมสัญญาณพัลส์ Enable ของ LCD ---
static void lcd_pulse_en(void) {
    PORTB |= (1 << LCD_EN_PIN);
    _delay_us(2);
    PORTB &= ~(1 << LCD_EN_PIN);
    _delay_us(50);
}

// --- ฟังก์ชันส่งข้อมูลระดับ Nibble (4 บิต) ไปยังขา PD2-PD5 ---
static void lcd_write_nibble(uint8_t nibble) {
    // ล้างค่าขา PD2 ถึง PD5 เดิม
    PORTD &= ~((1 << PD2) | (1 << PD3) | (1 << PD4) | (1 << PD5));

    // แมปบิต 0..3 ของ nibble เข้ากับ PD5..PD2
