/**
 * ==============================================================================
 * Project: Sample 16 - ระบบล็อครหัสผ่านความปลอดภัย 4 หลัก (PIN Code Lock) บน LCD 16x2
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (AVR-GCC)
 * Author: Embedded System Design Exam Preparation (CDTI)
 * ==============================================================================
 * 
 * [รายละเอียดฮาร์ดแวร์]
 * 1. จอแสดงผล LCD 16x2 (โหมด 4 บิต):
 *    - ขา RS -> PB4 (Arduino Pin 12)
 *    - ขา EN -> PB3 (Arduino Pin 11)
 *    - ขา RW -> GND
 *    - ขา D4 -> PD5 (Arduino Pin 5)
 *    - ขา D5 -> PD4 (Arduino Pin 4)
 *    - ขา D6 -> PD3 (Arduino Pin 3)
 *    - ขา D7 -> PD2 (Arduino Pin 2)
 *
 * 2. หลอดไฟสถานะ (Status LEDs):
 *    - LED_UNLOCK (เขียว) : PD6 (Arduino Pin 6)  -> ติดสว่างเมื่อรหัสผ่านถูกต้อง
 *    - LED_ALARM  (แดง)   : PD7 (Arduino Pin 7)  -> กะพริบเตือนเมื่อรหัสผ่านผิด
 *
 * 3. สวิตช์ปุ่มกด 3 ปุ่ม (Active-Low พร้อม Internal Pull-up):
 *    - SW_DIGIT : PB0 (Arduino Pin 8)  -> เปลี่ยนค่าตัวเลขหลักปัจจุบัน (0-9)
 *    - SW_ENTER : PB1 (Arduino Pin 9)  -> ยืนยันตัวเลขหลักนี้ และเลื่อนไปหลักถัดไป
 *    - SW_CLEAR : PB2 (Arduino Pin 10) -> ล้างการป้อนรหัสกลับไปเริ่มหลักที่ 1 ใหม่
 * 
 * [รหัสผ่านลับของระบบ]
 * - MASTER_PIN = "2569" (ตรงกับปี พ.ศ. ข้อสอบ CDTI 2569)
 * ==============================================================================
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>
#include <stdio.h>
#include <stdbool.h>

// ขาควบคุม LCD
#define LCD_RS_PIN      PB4     // Pin 12
#define LCD_EN_PIN      PB3     // Pin 11

// ขาสวิตช์ปุ่มกด
#define SW_DIGIT_PIN    PB0     // Pin 8 (Increment digit 0-9)
#define SW_ENTER_PIN    PB1     // Pin 9 (Confirm digit / Submit)
#define SW_CLEAR_PIN    PB2     // Pin 10 (Clear input)

// ขาหลอดไฟแสดงผล
#define LED_UNLOCK_PIN  PD6     // Pin 6 (Green - Access Granted)
#define LED_ALARM_PIN   PD7     // Pin 7 (Red - Access Denied)

// รหัสผ่านลับของระบบ
const uint8_t SECRET_PIN[4] = { 2, 5, 6, 9 };

// --- ฟังก์ชันควบคุมพัลส์ Enable ของ LCD ---
static void lcd_pulse_en(void) {
    PORTB |= (1 << LCD_EN_PIN);
    _delay_us(2);
    PORTB &= ~(1 << LCD_EN_PIN);
    _delay_us(50);
}

// --- ฟังก์ชันส่ง Nibble (4 บิต) ไปยังขา PD2-PD5 ---
static void lcd_write_nibble(uint8_t nibble) {
    PORTD &= ~((1 << PD2) | (1 << PD3) | (1 << PD4) | (1 << PD5));
    if (nibble & 0x01) PORTD |= (1 << PD5); // D4
    if (nibble & 0x02) PORTD |= (1 << PD4); // D5
    if (nibble & 0x04) PORTD |= (1 << PD3); // D6
    if (nibble & 0x08) PORTD |= (1 << PD2); // D7
    lcd_pulse_en();
}

void lcd_send_cmd(uint8_t cmd) {
    PORTB &= ~(1 << LCD_RS_PIN);
    lcd_write_nibble((cmd >> 4) & 0x0F);
    lcd_write_nibble(cmd & 0x0F);
    if (cmd == 0x01 || cmd == 0x02) _delay_ms(2);
}

void lcd_send_data(uint8_t data) {
    PORTB |= (1 << LCD_RS_PIN);
    lcd_write_nibble((data >> 4) & 0x0F);
    lcd_write_nibble(data & 0x0F);
}

void lcd_print(const char *str) {
    while (*str) lcd_send_data((uint8_t)*str++);
}

void lcd_set_cursor(uint8_t row, uint8_t col) {
    uint8_t addr = (row == 0) ? (0x80 + col) : (0xC0 + col);
    lcd_send_cmd(addr);
}

void lcd_init_4bit(void) {
    _delay_ms(50);
    PORTB &= ~(1 << LCD_RS_PIN);
    lcd_write_nibble(0x03); _delay_ms(5);
    lcd_write_nibble(0x03); _delay_us(150);
    lcd_write_nibble(0x03); _delay_us(150);
    lcd_write_nibble(0x02); _delay_us(150);
    lcd_send_cmd(0x28); // 4-bit, 2 lines, 5x8
    lcd_send_cmd(0x0C); // Display ON, Cursor OFF
    lcd_send_cmd(0x01); // Clear Display
    lcd_send_cmd(0x06); // Auto increment
}

int main(void) {
    // --------------------------------------------------------------------------
    // 1. ตั้งค่าพอร์ตและทิศทาง I/O
    // --------------------------------------------------------------------------
    // ขา LCD Data (PD2..PD5) และหลอดไฟ LED (PD6=Unlock, PD7=Alarm) เป็น Output
    DDRD |= (1 << PD2) | (1 << PD3) | (1 << PD4) | (1 << PD5) | (1 << LED_UNLOCK_PIN) | (1 << LED_ALARM_PIN);
    PORTD &= ~((1 << LED_UNLOCK_PIN) | (1 << LED_ALARM_PIN)); // ดับไฟเริ่มต้น

    // ขา LCD Control (PB3=EN, PB4=RS) เป็น Output
    DDRB |= (1 << LCD_RS_PIN) | (1 << LCD_EN_PIN);

    // ขาสวิตช์ PB0 (Digit), PB1 (Enter), PB2 (Clear) เป็น Input พร้อมเปิด Pull-up
    DDRB &= ~((1 << SW_DIGIT_PIN) | (1 << SW_ENTER_PIN) | (1 << SW_CLEAR_PIN));
    PORTB |= (1 << SW_DIGIT_PIN) | (1 << SW_ENTER_PIN) | (1 << SW_CLEAR_PIN);

    // --------------------------------------------------------------------------
    // 2. เริ่มต้นจอภาพ LCD
    // --------------------------------------------------------------------------
    lcd_init_4bit();

    uint8_t entered_pin[4] = { 0, 0, 0, 0 };
    uint8_t current_pos = 0;   // ตำแหน่งหลักที่กำลังป้อน (0 ถึง 3)
    uint8_t current_val = 0;   // ตัวเลขที่กำลังเลือกในหลักปัจจุบัน (0 ถึง 9)
    uint8_t attempts = 3;      // จำนวนครั้งที่ป้อนผิดได้

    bool need_display_update = true;

    while (1) {
        // อัปเดตหน้าจอหลักเมื่อมีการเปลี่ยนแปลง
        if (need_display_update) {
            need_display_update = false;
            lcd_send_cmd(0x01);
            lcd_set_cursor(0, 0);
            lcd_print("SECURITY LOCK");

            lcd_set_cursor(1, 0);
            lcd_print("PIN: [");
            for (uint8_t i = 0; i < 4; i++) {
                if (i < current_pos) {
                    lcd_send_data('*'); // ซ่อนรหัสหลักที่ยืนยันแล้ว
                } else if (i == current_pos) {
                    lcd_send_data('0' + current_val); // แสดงตัวเลขที่กำลังปรับ
                } else {
                    lcd_send_data('_'); // หลักที่ยังไม่ได้ป้อน
                }
            }
            lcd_print("]");
        }

        // ตรวจจับปุ่มกด SW_DIGIT (เพิ่มค่า 0-9)
        if (!(PINB & (1 << SW_DIGIT_PIN))) {
            _delay_ms(20); // Debounce
            if (!(PINB & (1 << SW_DIGIT_PIN))) {
                current_val++;
                if (current_val > 9) current_val = 0;
                need_display_update = true;
                while (!(PINB & (1 << SW_DIGIT_PIN))); // รอจนปล่อยปุ่ม
            }
        }

        // ตรวจจับปุ่มกด SW_ENTER (ยืนยันหลักปัจจุบัน)
        if (!(PINB & (1 << SW_ENTER_PIN))) {
            _delay_ms(20);
            if (!(PINB & (1 << SW_ENTER_PIN))) {
                entered_pin[current_pos] = current_val;
                current_pos++;
                current_val = 0; // รีเซ็ตค่าเริ่มต้นสำหรับหลักถัดไป

                if (current_pos >= 4) {
                    // --- ป้อนครบ 4 หลักแล้ว ตรวจสอบรหัสผ่าน ---
                    bool is_correct = true;
                    for (uint8_t i = 0; i < 4; i++) {
                        if (entered_pin[i] != SECRET_PIN[i]) {
                            is_correct = false;
                            break;
                        }
                    }

                    lcd_send_cmd(0x01);
                    if (is_correct) {
                        // รหัสผ่านถูกต้อง (ACCESS GRANTED)
                        PORTD |= (1 << LED_UNLOCK_PIN); // เปิดไฟสีเขียว
                        lcd_set_cursor(0, 1);
                        lcd_print("ACCESS GRANTED");
                        lcd_set_cursor(1, 0);
                        lcd_print("[SYSTEM UNLOCK]");

                        _delay_ms(4000); // ปลดล็อคค้างไว้ 4 วินาที
                        PORTD &= ~(1 << LED_UNLOCK_PIN);
                        attempts = 3; // รีเซ็ตจำนวนครั้ง
                    } else {
                        // รหัสผ่านผิด (ACCESS DENIED)
                        if (attempts > 0) attempts--;
                        lcd_set_cursor(0, 1);
                        lcd_print("ACCESS DENIED!");
                        char buf[17];
                        snprintf(buf, sizeof(buf), "Attempts Left: %u", attempts);
                        lcd_set_cursor(1, 0);
                        lcd_print(buf);

                        // กะพริบไฟสีแดงแจ้งเตือน 5 ครั้ง
                        for (uint8_t k = 0; k < 5; k++) {
                            PORTD |= (1 << LED_ALARM_PIN);
                            _delay_ms(150);
                            PORTD &= ~(1 << LED_ALARM_PIN);
                            _delay_ms(150);
                        }
                    }

                    // รีเซ็ตสถานะกลับไปรอป้อนรอบใหม่
                    current_pos = 0;
                    current_val = 0;
                }

                need_display_update = true;
                while (!(PINB & (1 << SW_ENTER_PIN)));
            }
        }

        // ตรวจจับปุ่มกด SW_CLEAR (ล้างค่ากลับหลักที่ 1)
        if (!(PINB & (1 << SW_CLEAR_PIN))) {
            _delay_ms(20);
            if (!(PINB & (1 << SW_CLEAR_PIN))) {
                current_pos = 0;
                current_val = 0;
                need_display_update = true;
                while (!(PINB & (1 << SW_CLEAR_PIN)));
            }
        }

        _delay_ms(15);
    }

    return 0;
}

