/**
 * ==============================================================================
 * Project: Sample 14 - เมนูควบคุมแบบโต้ตอบหลายระดับบน LCD 16x2 ด้วยสวิตช์ 4 ปุ่ม
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (AVR-GCC)
 * Author: Embedded System Design Exam Preparation (CDTI)
 * ==============================================================================
 * 
 * [การจัดสรรขาพอร์ตฮาร์ดแวร์]
 * 1. จอแสดงผล LCD 16x2 (โหมด 4 บิต):
 *    - ขา RS -> PB4 (Arduino Pin 12)
 *    - ขา EN -> PB3 (Arduino Pin 11)
 *    - ขา RW -> GND
 *    - ขา D4 -> PD5 (Arduino Pin 5)
 *    - ขา D5 -> PD4 (Arduino Pin 4)
 *    - ขา D6 -> PD3 (Arduino Pin 3)
 *    - ขา D7 -> PD2 (Arduino Pin 2)
 *
 * 2. สวิตช์นำทาง 4 ปุ่ม (Active-Low พร้อม Internal Pull-up):
 *    - SW_UP     : PB0 (Arduino Pin 8)  -> เลื่อนเคอร์เซอร์ขึ้น
 *    - SW_DOWN   : PB1 (Arduino Pin 9)  -> เลื่อนเคอร์เซอร์ลง
 *    - SW_SELECT : PB2 (Arduino Pin 10) -> เลือกรายการ / ตกลง
 *    - SW_BACK   : PD7 (Arduino Pin 7)  -> ย้อนกลับเมนูก่อนหน้า
 *
 * 3. อุปกรณ์เอาต์พุตที่ควบคุมได้:
 *    - LED 1 : PD6 (Arduino Pin 6)  -> สั่ง เปิด/ปิด จากเมนู LED Control
 *    - LED 2 : PB5 (Arduino Pin 13) -> สั่ง เปิด/ปิด จากเมนู LED Control
 *
 * 4. เซนเซอร์อินพุต:
 *    - Potentiometer 10k : ขา A0 (PC0 / ADC0) -> อ่านค่าและแสดงผลแบบเรียลไทม์
 * ==============================================================================
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>
#include <stdio.h>
#include <stdbool.h>

// ขาควบคุม LCD
#define LCD_RS_PIN      PB4     // Pin 12
#define LCD_EN_PIN      PB3     // Pin 11

// ขาสวิตช์ 4 ปุ่ม
#define SW_UP_PIN       PB0     // Pin 8
#define SW_DOWN_PIN     PB1     // Pin 9
#define SW_SEL_PIN      PB2     // Pin 10
#define SW_BACK_PIN     PD7     // Pin 7

// ขาโหลด LED
#define LED1_PIN        PD6     // Pin 6
#define LED2_PIN        PB5     // Pin 13

// สถานะของเมนู (Menu States)
typedef enum {
    MENU_MAIN = 0,
    SUBMENU_LED,
    SUBMENU_ADC,
    SUBMENU_INFO
} MenuState_t;

// --- ฟังก์ชันย่อยควบคุมสัญญาณพัลส์ Enable ของ LCD ---
static void lcd_pulse_en(void) {
    PORTB |= (1 << LCD_EN_PIN);
    _delay_us(2);
    PORTB &= ~(1 << LCD_EN_PIN);
    _delay_us(50);
}

// --- ฟังก์ชันส่ง Nibble (4 บิต) ไปยังขา PD2-PD5 ---
static void lcd_write_nibble(uint8_t nibble) {
    PORTD &= ~((1 << PD2) | (1 << PD3) | (1 << PD4) | (1 << PD5));
    if (nibble & 0x01) PORTD |= (1 << PD5); // D4
    if (nibble & 0x02) PORTD |= (1 << PD4); // D5
    if (nibble & 0x04) PORTD |= (1 << PD3); // D6
    if (nibble & 0x08) PORTD |= (1 << PD2); // D7
    lcd_pulse_en();
}

void lcd_send_cmd(uint8_t cmd) {
    PORTB &= ~(1 << LCD_RS_PIN);
    lcd_write_nibble((cmd >> 4) & 0x0F);
    lcd_write_nibble(cmd & 0x0F);
    if (cmd == 0x01 || cmd == 0x02) _delay_ms(2);
}

void lcd_send_data(uint8_t data) {
    PORTB |= (1 << LCD_RS_PIN);
    lcd_write_nibble((data >> 4) & 0x0F);
    lcd_write_nibble(data & 0x0F);
}

void lcd_print(const char *str) {
    while (*str) lcd_send_data((uint8_t)*str++);
}

void lcd_set_cursor(uint8_t row, uint8_t col) {
    uint8_t addr = (row == 0) ? (0x80 + col) : (0xC0 + col);
    lcd_send_cmd(addr);
}

void lcd_init_4bit(void) {
    _delay_ms(50);
    PORTB &= ~(1 << LCD_RS_PIN);
    lcd_write_nibble(0x03); _delay_ms(5);
    lcd_write_nibble(0x03); _delay_us(150);
    lcd_write_nibble(0x03); _delay_us(150);
    lcd_write_nibble(0x02); _delay_us(150);
    lcd_send_cmd(0x28); // 4-bit, 2 lines, 5x8
    lcd_send_cmd(0x0C); // Display ON, Cursor OFF
    lcd_send_cmd(0x01); // Clear Display
    lcd_send_cmd(0x06); // Auto increment
}

// --- ฟังก์ชันเริ่มต้นและอ่านค่า ADC0 ---
void adc_init(void) {
    ADMUX = (1 << REFS0); // AVCC อ้างอิง
    ADCSRA = (1 << ADEN) | (1 << ADPS2) | (1 << ADPS1) | (1 << ADPS0); // Prescaler 128
}

uint16_t adc_read(void) {
    ADCSRA |= (1 << ADSC);
    while (ADCSRA & (1 << ADSC));
    return ADC;
}

int main(void) {
    // --------------------------------------------------------------------------
    // 1. ตั้งค่าพอร์ต I/O
    // --------------------------------------------------------------------------
    // ขา LCD Data (PD2..PD5) และ LED1 (PD6) เป็น Output
    DDRD |= (1 << PD2) | (1 << PD3) | (1 << PD4) | (1 << PD5) | (1 << LED1_PIN);
    // ขา SW_BACK (PD7) เป็น Input พร้อมเปิด Pull-up
    DDRD &= ~(1 << SW_BACK_PIN);
    PORTD |= (1 << SW_BACK_PIN);
    PORTD &= ~(1 << LED1_PIN); // ปิด LED1 เริ่มต้น

    // ขา LCD Control (PB3, PB4) และ LED2 (PB5) เป็น Output
    DDRB |= (1 << LCD_RS_PIN) | (1 << LCD_EN_PIN) | (1 << LED2_PIN);
    PORTB &= ~(1 << LED2_PIN); // ปิด LED2 เริ่มต้น

    // ขา SW_UP (PB0), SW_DOWN (PB1), SW_SEL (PB2) เป็น Input พร้อมเปิด Pull-up
    DDRB &= ~((1 << SW_UP_PIN) | (1 << SW_DOWN_PIN) | (1 << SW_SEL_PIN));
    PORTB |= (1 << SW_UP_PIN) | (1 << SW_DOWN_PIN) | (1 << SW_SEL_PIN);

    // --------------------------------------------------------------------------
    // 2. เริ่มต้นระบบ LCD และ ADC
    // --------------------------------------------------------------------------
    lcd_init_4bit();
    adc_init();

    MenuState_t current_state = MENU_MAIN;
    uint8_t main_cursor = 0;   // 0: LED Control, 1: ADC Monitor, 2: System Info
    uint8_t led_cursor = 0;    // 0: LED1, 1: LED2
    bool led1_on = false;
    bool led2_on = false;

    char buffer[17];
    bool need_redraw = true;

    while (1) {
        // ----------------------------------------------------------------------
        // ตรวจจับการกดปุ่มทั้ง 4 ปุ่ม (Active-Low)
        // ----------------------------------------------------------------------
        bool btn_up = !(PINB & (1 << SW_UP_PIN));
        bool btn_down = !(PINB & (1 << SW_DOWN_PIN));
        bool btn_sel = !(PINB & (1 << SW_SEL_PIN));
        bool btn_back = !(PIND & (1 << SW_BACK_PIN));

        // ----------------------------------------------------------------------
        // FSM จัดการสถานะเมนู
        // ----------------------------------------------------------------------
        switch (current_state) {
            case MENU_MAIN:
                if (btn_up) {
                    _delay_ms(20);
                    if (!(PINB & (1 << SW_UP_PIN))) {
                        if (main_cursor > 0) main_cursor--;
                        need_redraw = true;
                        while (!(PINB & (1 << SW_UP_PIN))); // รอปล่อยปุ่ม
                    }
                } else if (btn_down) {
                    _delay_ms(20);
                    if (!(PINB & (1 << SW_DOWN_PIN))) {
                        if (main_cursor < 2) main_cursor++;
                        need_redraw = true;
                        while (!(PINB & (1 << SW_DOWN_PIN)));
                    }
                } else if (btn_sel) {
                    _delay_ms(20);
                    if (!(PINB & (1 << SW_SEL_PIN))) {
                        if (main_cursor == 0) current_state = SUBMENU_LED;
                        else if (main_cursor == 1) current_state = SUBMENU_ADC;
                        else if (main_cursor == 2) current_state = SUBMENU_INFO;
                        need_redraw = true;
                        while (!(PINB & (1 << SW_SEL_PIN)));
                    }
                }

                if (need_redraw) {
                    need_redraw = false;
                    lcd_send_cmd(0x01);
                    if (main_cursor == 0) {
                        lcd_set_cursor(0, 0); lcd_print(">1.LED Control");
                        lcd_set_cursor(1, 0); lcd_print(" 2.ADC Monitor");
                    } else if (main_cursor == 1) {
                        lcd_set_cursor(0, 0); lcd_print(" 1.LED Control");
                        lcd_set_cursor(1, 0); lcd_print(">2.ADC Monitor");
                    } else {
                        lcd_set_cursor(0, 0); lcd_print(">3.System Info");
                        lcd_set_cursor(1, 0); lcd_print("  (CDTI 2026)");
                    }
                }
                break;

            case SUBMENU_LED:
                if (btn_back) {
                    _delay_ms(20);
                    if (!(PIND & (1 << SW_BACK_PIN))) {
                        current_state = MENU_MAIN;
                        need_redraw = true;
                        while (!(PIND & (1 << SW_BACK_PIN)));
                    }
                } else if (btn_up || btn_down) {
                    _delay_ms(20);
                    led_cursor = !led_cursor;
                    need_redraw = true;
                    _delay_ms(200);
                } else if (btn_sel) {
                    _delay_ms(20);
                    if (!(PINB & (1 << SW_SEL_PIN))) {
                        if (led_cursor == 0) {
                            led1_on = !led1_on;
                            if (led1_on) PORTD |= (1 << LED1_PIN);
                            else PORTD &= ~(1 << LED1_PIN);
                        } else {
                            led2_on = !led2_on;
                            if (led2_on) PORTB |= (1 << LED2_PIN);
                            else PORTB &= ~(1 << LED2_PIN);
                        }
                        need_redraw = true;
                        while (!(PINB & (1 << SW_SEL_PIN)));
                    }
                }

                if (need_redraw) {
                    need_redraw = false;
                    lcd_send_cmd(0x01);
                    lcd_set_cursor(0, 0);
                    snprintf(buffer, sizeof(buffer), "%cLED1: [%s]", (led_cursor == 0) ? '>' : ' ', led1_on ? "ON " : "OFF");
                    lcd_print(buffer);

                    lcd_set_cursor(1, 0);
                    snprintf(buffer, sizeof(buffer), "%cLED2: [%s]", (led_cursor == 1) ? '>' : ' ', led2_on ? "ON " : "OFF");
                    lcd_print(buffer);
                }
                break;

            case SUBMENU_ADC:
                if (btn_back) {
                    _delay_ms(20);
                    if (!(PIND & (1 << SW_BACK_PIN))) {
                        current_state = MENU_MAIN;
                        need_redraw = true;
                        while (!(PIND & (1 << SW_BACK_PIN)));
                    }
                } else {
                    // อ่านและอัปเดตแรงดันอนาล็อกอย่างต่อเนื่องแบบเรียลไทม์
                    uint16_t val = adc_read();
                    uint16_t mv = (uint16_t)(((uint32_t)val * 5000UL) / 1023UL);
                    uint16_t v_int = mv / 1000;
                    uint16_t v_frac = (mv % 1000) / 10;

                    lcd_set_cursor(0, 0);
                    snprintf(buffer, sizeof(buffer), "ADC: %4u / 1023", val);
                    lcd_print(buffer);

                    lcd_set_cursor(1, 0);
                    snprintf(buffer, sizeof(buffer), "Volt: %u.%02uV [BACK]", v_int, v_frac);
                    lcd_print(buffer);
                    _delay_ms(100);
                }
                break;

            case SUBMENU_INFO:
                if (btn_back) {
                    _delay_ms(20);
                    if (!(PIND & (1 << SW_BACK_PIN))) {
                        current_state = MENU_MAIN;
                        need_redraw = true;
                        while (!(PIND & (1 << SW_BACK_PIN)));
                    }
                }
                if (need_redraw) {
                    need_redraw = false;
                    lcd_send_cmd(0x01);
                    lcd_set_cursor(0, 0);
                    lcd_print("ATmega328P 16MHz");
                    lcd_set_cursor(1, 0);
                    lcd_print("CDTI Embed 2569 ");
                }
                break;
        }

        _delay_ms(15);
    }

    return 0;
}

