// --- ฟังก์ชันเริ่มต้นและอ่านค่า ADC0 ---
void adc_init(void) {
    ADMUX = (1 << REFS0); // AVCC อ้างอิง
    ADCSRA = (1 << ADEN) | (1 << ADPS2) | (1 << ADPS1) | (1 << ADPS0); // Prescaler 128
}

