    // ขา LCD Control (PB3, PB4) และ LED2 (PB5) เป็น Output
    DDRB |= (1 << LCD_RS_PIN) | (1 << LCD_EN_PIN) | (1 << LED2_PIN);
    PORTB &= ~(1 << LED2_PIN); // ปิด LED2 เริ่มต้น

    // ขา SW_UP (PB0), SW_DOWN (PB1), SW_SEL (PB2) เป็น Input พร้อมเปิด Pull-up
    DDRB &= ~((1 << SW_UP_PIN) | (1 << SW_DOWN_PIN) | (1 << SW_SEL_PIN));
    PORTB |= (1 << SW_UP_PIN) | (1 << SW_DOWN_PIN) | (1 << SW_SEL_PIN);

