 *    - ขา EN -> PB3 (Arduino Pin 11)
 *    - ขา RW -> GND
 *    - ขา D4 -> PD5 (Arduino Pin 5)
 *    - ขา D5 -> PD4 (Arduino Pin 4)
 *    - ขา D6 -> PD3 (Arduino Pin 3)
 *    - ขา D7 -> PD2 (Arduino Pin 2)
 *
 * 2. เซนเซอร์อุณหภูมิจำลอง (Potentiometer 10k):
 *    - ขา A0 (PC0 / ADC0) รับแรงดัน 0.0V ถึง 5.0V จำลองอุณหภูมิ 0.0 ถึง 100.0 °C
 *
 * 3. พัดลมระบายความร้อนจำลอง (PWM Fan LED):
 *    - ขา PD6 (Arduino Pin 6 / OC0A) ขับสัญญาณ Hardware Timer0 Fast PWM (0-255)
 *
 * 4. หลอดไฟเตือนอุณหภูมิเกิน (Overheat Alarm LED):
 *    - ขา PB2 (Arduino Pin 10) ผ่าน R = 470 โอห์ม (กะพริบเมื่อ Temp >= 60 °C)
 *
 * 5. สวิตช์ปุ่มกด (Active-Low พร้อม Internal Pull-up):
 *    - SW_MODE  : PB0 (Arduino Pin 8) -> สลับโหมด [AUTO] / [MANUAL]
 *    - SW_SPEED : PB1 (Arduino Pin 9) -> ในโหมด MANUAL กดปรับความเร็วพัดลม (0% -> 33% -> 66% -> 100%)
 * ==============================================================================
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>
#include <stdio.h>
#include <stdbool.h>

// ขาควบคุม LCD
#define LCD_RS_PIN      PB4     // Pin 12
#define LCD_EN_PIN      PB3     // Pin 11

// ขาสวิตช์ปุ่มกด
#define SW_MODE_PIN     PB0     // Pin 8 (Auto / Manual toggle)
#define SW_SPEED_PIN    PB1     // Pin 9 (Manual speed step)

// ขาหลอดไฟเตือน
#define LED_ALARM_PIN   PB2     // Pin 10 (Overheat Alarm LED)

// ขา PWM Fan
#define FAN_PWM_PIN     PD6     // Pin 6 (Timer0 OC0A)

// --- ฟังก์ชันควบคุมสัญญาณ LCD 4 บิต ---
static void lcd_pulse_en(void) {
    PORTB |= (1 << LCD_EN_PIN);
    _delay_us(2);
    PORTB &= ~(1 << LCD_EN_PIN);
    _delay_us(50);
}

static void lcd_write_nibble(uint8_t nibble) {
    PORTD &= ~((1 << PD2) | (1 << PD3) | (1 << PD4) | (1 << PD5));
    if (nibble & 0x01) PORTD |= (1 << PD5); // D4
    if (nibble & 0x02) PORTD |= (1 << PD4); // D5
    if (nibble & 0x04) PORTD |= (1 << PD3); // D6
    if (nibble & 0x08) PORTD |= (1 << PD2); // D7
    lcd_pulse_en();
}

void lcd_send_cmd(uint8_t cmd) {
    PORTB &= ~(1 << LCD_RS_PIN);
    lcd_write_nibble((cmd >> 4) & 0x0F);
    lcd_write_nibble(cmd & 0x0F);
    if (cmd == 0x01 || cmd == 0x02) _delay_ms(2);
}

void lcd_send_data(uint8_t data) {
    PORTB |= (1 << LCD_RS_PIN);
    lcd_write_nibble((data >> 4) & 0x0F);
    lcd_write_nibble(data & 0x0F);
}

void lcd_print(const char *str) {
    while (*str) lcd_send_data((uint8_t)*str++);
}

void lcd_set_cursor(uint8_t row, uint8_t col) {
    uint8_t addr = (row == 0) ? (0x80 + col) : (0xC0 + col);
    lcd_send_cmd(addr);
}

void lcd_init_4bit(void) {
    _delay_ms(50);
    PORTB &= ~(1 << LCD_RS_PIN);
    lcd_write_nibble(0x03); _delay_ms(5);
    lcd_write_nibble(0x03); _delay_us(150);
    lcd_write_nibble(0x03); _delay_us(150);
    lcd_write_nibble(0x02); _delay_us(150);
    lcd_send_cmd(0x28); // 4-bit, 2 lines, 5x8
    lcd_send_cmd(0x0C); // Display ON, Cursor OFF
    lcd_send_cmd(0x01); // Clear Display
    lcd_send_cmd(0x06); // Auto increment
}

// --- ฟังก์ชันเริ่มต้น ADC0 และ Timer0 Fast PWM ---
void adc_init(void) {
    ADMUX = (1 << REFS0); // AVCC 5V
    ADCSRA = (1 << ADEN) | (1 << ADPS2) | (1 << ADPS1) | (1 << ADPS0); // Prescaler 128
}

uint16_t adc_read(void) {
    ADCSRA |= (1 << ADSC);
    while (ADCSRA & (1 << ADSC));
    return ADC;
}

void timer0_pwm_init(void) {
    // กำหนดขา PD6 เป็น Output
    DDRD |= (1 << FAN_PWM_PIN);

    // Fast PWM Mode บนขา OC0A, Non-inverting, Prescaler = 64 (ความถี่ ~976 Hz)
    TCCR0A = (1 << COM0A1) | (1 << WGM01) | (1 << WGM00);
    TCCR0B = (1 << CS01) | (1 << CS00);
    OCR0A = 0;
}

int main(void) {
    // --------------------------------------------------------------------------
    // 1. ตั้งค่าพอร์ตและทิศทาง I/O
    // --------------------------------------------------------------------------
    // ขา LCD Data (PD2..PD5) และ PWM Fan (PD6) เป็น Output
    DDRD |= (1 << PD2) | (1 << PD3) | (1 << PD4) | (1 << PD5) | (1 << FAN_PWM_PIN);

    // ขา LCD Control (PB3, PB4) และ Overheat Alarm LED (PB2) เป็น Output
    DDRB |= (1 << LCD_RS_PIN) | (1 << LCD_EN_PIN) | (1 << LED_ALARM_PIN);
    PORTB &= ~(1 << LED_ALARM_PIN);

    // ขาสวิตช์ PB0 (Mode) และ PB1 (Speed) เป็น Input พร้อมเปิด Pull-up
    DDRB &= ~((1 << SW_MODE_PIN) | (1 << SW_SPEED_PIN));
    PORTB |= (1 << SW_MODE_PIN) | (1 << SW_SPEED_PIN);

    // --------------------------------------------------------------------------
    // 2. เริ่มต้นระบบ LCD, ADC, และ PWM
    // --------------------------------------------------------------------------
    lcd_init_4bit();
    adc_init();
    timer0_pwm_init();

    bool is_auto_mode = true;
    uint8_t manual_speed_step = 0; // 0=0%, 1=33%, 2=66%, 3=100%
    uint8_t current_duty = 0;
    bool alarm_blink_state = false;

    char line1_buf[17];
    char line2_buf[17];

    while (1) {
        // อ่านค่าอนาล็อกจาก Potentiometer (0 - 1023)
        uint16_t raw_adc = adc_read();

        // คำนวณอุณหภูมิจำลอง: 0 ถึง 100.0 °C
        // temp_x10 = (raw * 1000) / 1023
        uint16_t temp_x10 = (uint16_t)(((uint32_t)raw_adc * 1000UL) / 1023UL);
        uint8_t temp_int = temp_x10 / 10;
        uint8_t temp_dec = temp_x10 % 10;

        // ----------------------------------------------------------------------
        // ตรวจจับการกดปุ่มสลับโหมด SW_MODE (PB0)
        // ----------------------------------------------------------------------
        if (!(PINB & (1 << SW_MODE_PIN))) {
            _delay_ms(20);
            if (!(PINB & (1 << SW_MODE_PIN))) {
                is_auto_mode = !is_auto_mode;
                while (!(PINB & (1 << SW_MODE_PIN))); // รอจนปล่อยปุ่ม
            }
        }

        // ----------------------------------------------------------------------
        // ตรวจจับการกดปุ่มปรับความเร็วในโหมด MANUAL: SW_SPEED (PB1)
        // ----------------------------------------------------------------------
        if (!is_auto_mode && !(PINB & (1 << SW_SPEED_PIN))) {
            _delay_ms(20);
            if (!(PINB & (1 << SW_SPEED_PIN))) {
                manual_speed_step++;
                if (manual_speed_step > 3) manual_speed_step = 0;
                while (!(PINB & (1 << SW_SPEED_PIN)));
            }
        }

        // ----------------------------------------------------------------------
        // คำนวณความเร็วพัดลม (Duty Cycle) ตามโหมดการทำงาน
        // ----------------------------------------------------------------------
        if (is_auto_mode) {
            // โหมดอัตโนมัติ (Proportional Closed-Loop):
            // - อุณหภูมิต่ำกว่า 30 °C -> ปิดพัดลม (Duty = 0)
            // - อุณหภูมิ 30 - 60 °C   -> เพิ่มความเร็วตามสัดส่วน (Duty = 64 ถึง 255)
            // - อุณหภูมิ >= 60 °C    -> พัดลมทำงาน 100% (Duty = 255)
            if (temp_int < 30) {
                current_duty = 0;
            } else if (temp_int < 60) {
                // สเกลจาก (30..60 °C) ไปยัง (64..255)
                uint16_t span = (temp_int - 30) * (255 - 64) / 30;
                current_duty = 64 + (uint8_t)span;
            } else {
                current_duty = 255;
            }
        } else {
            // โหมดปรับมือ (Manual Mode):
            switch (manual_speed_step) {
                case 0: current_duty = 0; break;
                case 1: current_duty = 85; break;   // 33%
                case 2: current_duty = 170; break;  // 66%
                case 3: current_duty = 255; break;  // 100%
            }
        }

        // ส่งค่าไปยังฮาร์ดแวร์ PWM เพื่อปรับความเร็วรอบพัดลมทันที
        OCR0A = current_duty;
        uint8_t fan_percent = (uint8_t)(((uint16_t)current_duty * 100) / 255);

        // ----------------------------------------------------------------------
        // จัดการระบบแจ้งเตือนความร้อนเกิน (Overheat Alarm >= 60 °C)
        // ----------------------------------------------------------------------
        if (temp_int >= 60) {
            alarm_blink_state = !alarm_blink_state;
            if (alarm_blink_state) {
                PORTB |= (1 << LED_ALARM_PIN);
            } else {
                PORTB &= ~(1 << LED_ALARM_PIN);
            }
        } else {
            PORTB &= ~(1 << LED_ALARM_PIN); // ปิดไฟเตือนเมื่ออุณหภูมิปกติ
        }

        // ----------------------------------------------------------------------
        // แสดงผลบนจอ LCD 16x2
        // ----------------------------------------------------------------------
        snprintf(line1_buf, sizeof(line1_buf), "T:%2u.%uC [%s]",
                 temp_int, temp_dec, is_auto_mode ? "AUTO" : "MANU");
        lcd_set_cursor(0, 0);
        lcd_print(line1_buf);

        if (temp_int >= 60) {
            snprintf(line2_buf, sizeof(line2_buf), "Fan:%3u%% *ALARM*", fan_percent);
        } else {
            snprintf(line2_buf, sizeof(line2_buf), "Fan:%3u%% [NORM ]", fan_percent);
        }
        lcd_set_cursor(1, 0);
        lcd_print(line2_buf);

        _delay_ms(100);
    }

    return 0;
}

