/**
 * ==============================================================================
 * Project: Sample 08 - Master Exam System: โวลต์มิเตอร์ดิจิทัลแบบหลายจอแสดงผล
 * (Integrated Digital Voltmeter: ADC + LCD 16x2 + 7-Segment + Warning LED + Buttons)
 * Target MCU: ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (AVR-GCC)
 * Author: Embedded System Design Exam Preparation (CDTI)
 * ==============================================================================
 * 
 * [รายละเอียดสถาปัตยกรรมและการจัดสรรพอร์ต (Full Pin Mapping)]
 * 1. อินพุตแอนะล็อก (Analog Input):
 *    - Potentiometer 10k โอห์ม ต่อเข้าขา A0 (PC0 / ADC0) รับแรงดัน 0.00V - 5.00V
 * 
 * 2. จอแสดงผล LCD 16x2 (โหมด 4-Bit):
 *    - RS: PB4 (Digital Pin 12)
 *    - EN: PB3 (Digital Pin 11)
 *    - RW: GND (Write-only)
 *    - D4: PD5 (Digital Pin 5)
 *    - D5: PD4 (Digital Pin 4)
 *    - D6: PD3 (Digital Pin 3)
 *    - D7: PD2 (Digital Pin 2)
 * 
 * 3. จอแสดงผล 7-Segment Common Cathode (แสดงหลักหน่วยของแรงดัน 0-5V):
 *    - Seg a: PD0 (Pin 0)
 *    - Seg b: PD1 (Pin 1)
 *    - Seg c: PD6 (Pin 6)
 *    - Seg d: PD7 (Pin 7)
 *    - Seg e: PB2 (Pin 10)
 *    - Seg f: PC1 (Pin A1)
 *    - Seg g: PC2 (Pin A2)
 *    - COM: ต่อ GND
 * 
 * 4. ไฟสัญญาณเตือน (Warning Alarm LED):
 *    - LED Alarm: PB5 (Digital Pin 13) ผ่าน R = 470 โอห์ม (ติดเมื่อแรงดัน > 3.50V)
 * 
 * 5. สวิตช์ควบคุม (Control Buttons):
 *    - SW1 (Hold / Run): PB0 (Digital Pin 8)
 *    - SW2 (Display Mode): PB1 (Digital Pin 9)
 * ==============================================================================
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>
#include <stdio.h>

// นิยามขาควบคุม LCD
#define LCD_RS_PIN      PB4     // Pin 12
#define LCD_EN_PIN      PB3     // Pin 11

// นิยามขา LED และ Buttons
#define ALARM_LED_PIN   PB5     // Pin 13
#define SW_HOLD_PIN     PB0     // Pin 8
#define SW_MODE_PIN     PB1     // Pin 9

// ฟังก์ชัน LCD 4-Bit
static void lcd_pulse(void) {
    PORTB |= (1 << LCD_EN_PIN);
    _delay_us(2);
    PORTB &= ~(1 << LCD_EN_PIN);
    _delay_us(50);
}

static void lcd_write_4bits(uint8_t n) {
    PORTD &= ~((1 << PD2) | (1 << PD3) | (1 << PD4) | (1 << PD5));
    if (n & 0x01) PORTD |= (1 << PD5); // D4
    if (n & 0x02) PORTD |= (1 << PD4); // D5
    if (n & 0x04) PORTD |= (1 << PD3); // D6
    if (n & 0x08) PORTD |= (1 << PD2); // D7
    lcd_pulse();
}

static void lcd_cmd(uint8_t c) {
    PORTB &= ~(1 << LCD_RS_PIN);
    lcd_write_4bits((c >> 4) & 0x0F);
    lcd_write_4bits(c & 0x0F);
    if (c == 0x01 || c == 0x02) _delay_ms(2);
    else _delay_us(50);
}

static void lcd_data(uint8_t d) {
    PORTB |= (1 << LCD_RS_PIN);
    lcd_write_4bits((d >> 4) & 0x0F);
    lcd_write_4bits(d & 0x0F);
    _delay_us(50);
}

static void lcd_set_cursor(uint8_t row, uint8_t col) {
    lcd_cmd((row == 0 ? 0x80 : 0xC0) + col);
}

static void lcd_print(const char *s) {
    while (*s) lcd_data((uint8_t)*s++);
}

static void lcd_init(void) {
    DDRB |= (1 << LCD_RS_PIN) | (1 << LCD_EN_PIN);
    DDRD |= (1 << PD2) | (1 << PD3) | (1 << PD4) | (1 << PD5);

    PORTB &= ~((1 << LCD_RS_PIN) | (1 << LCD_EN_PIN));
    _delay_ms(50);

    lcd_write_4bits(0x03);
    _delay_ms(5);
    lcd_write_4bits(0x03);
    _delay_us(150);
    lcd_write_4bits(0x03);
    _delay_us(150);
    lcd_write_4bits(0x02); // 4-bit mode
    _delay_us(150);

    lcd_cmd(0x28); // 4-bit, 2 lines, 5x8
    lcd_cmd(0x0C); // Display ON
    lcd_cmd(0x06); // Increment
    lcd_cmd(0x01); // Clear
    _delay_ms(2);
}

// ฟังก์ชันโมดูล ADC
static void adc_init(void) {
    ADMUX = (1 << REFS0); // AVcc = 5V, ADC0
    ADCSRA = (1 << ADEN) | (1 << ADPS2) | (1 << ADPS1) | (1 << ADPS0); // Prescaler 128
}

static uint16_t adc_read(void) {
    ADCSRA |= (1 << ADSC);
    while (ADCSRA & (1 << ADSC));
    return ADC;
}

int main(void) {
    // 1. ตั้งค่าทิศทางพอร์ต
    // ALARM LED Output
    DDRB |= (1 << ALARM_LED_PIN);
    PORTB &= ~(1 << ALARM_LED_PIN);

    // Buttons Inputs + Pull-up
    DDRB &= ~((1 << SW_HOLD_PIN) | (1 << SW_MODE_PIN));
    PORTB |= (1 << SW_HOLD_PIN) | (1 << SW_MODE_PIN);

    // 2. เริ่มต้นฮาร์ดแวร์
    lcd_init();
    adc_init();

    uint8_t is_hold = 0;
    uint8_t display_mode = 0; // 0 = Voltage, 1 = Raw ADC
    uint16_t adc_val = 0;
    uint8_t last_hold_btn = 1;
    uint8_t last_mode_btn = 1;

    char line_buf[17];

    while (1) {
        // ตรวจจับปุ่ม SW1 (Hold Toggle)
        uint8_t cur_hold = (PINB & (1 << SW_HOLD_PIN)) ? 1 : 0;
        if (last_hold_btn == 1 && cur_hold == 0) {
            _delay_ms(20);
            if (!(PINB & (1 << SW_HOLD_PIN))) {
                is_hold ^= 1;
            }
        }
        last_hold_btn = cur_hold;

        // ตรวจจับปุ่ม SW2 (Mode Toggle)
        uint8_t cur_mode = (PINB & (1 << SW_MODE_PIN)) ? 1 : 0;
        if (last_mode_btn == 1 && cur_mode == 0) {
            _delay_ms(20);
            if (!(PINB & (1 << SW_MODE_PIN))) {
                display_mode ^= 1;
            }
        }
        last_mode_btn = cur_mode;

        // อ่านค่า ADC เฉพาะเมื่อไม่ได้อยู่ในโหมด HOLD
        if (!is_hold) {
            adc_val = adc_read();
        }

        // คำนวณค่าแรงดันจริง: V = (ADC * 5.0) / 1024
        // คำนวณเป็นมิลลิโวลต์เพื่อความแม่นยำสูง (Fixed-Point Math)
        uint32_t milli_volts = ((uint32_t)adc_val * 5000UL) / 1024UL;
        uint16_t volts_int = milli_volts / 1000;
        uint16_t volts_dec = (milli_volts % 1000) / 10; // ทศนิยม 2 ตำแหน่ง

        // ควบคุม Alarm LED (เตือนเมื่อ V > 3.50 V)
        if (milli_volts > 3500) {
            PORTB |= (1 << ALARM_LED_PIN); // ติดไฟเตือน
        } else {
            PORTB &= ~(1 << ALARM_LED_PIN); // ดับ
        }

        // แสดงผลบน LCD
        lcd_set_cursor(0, 0);
        if (is_hold) {
            snprintf(line_buf, sizeof(line_buf), "VOLT:%u.%02uV [HOLD]", volts_int, volts_dec);
        } else {
            snprintf(line_buf, sizeof(line_buf), "VOLT:%u.%02uV [RUN] ", volts_int, volts_dec);
        }
        lcd_print(line_buf);

        lcd_set_cursor(1, 0);
        if (display_mode == 0) {
            // โหมดแสดง Bar Graph
            uint8_t bars = (adc_val * 16) / 1024;
            char bar_str[17];
            for (uint8_t i = 0; i < 16; i++) {
                bar_str[i] = (i < bars) ? '=' : ' ';
            }
            bar_str[16] = '\0';
            lcd_print(bar_str);
        } else {
            // โหมดแสดงค่าดิบ ADC Raw
            snprintf(line_buf, sizeof(line_buf), "ADC RAW: %-4u/1023", adc_val);
            lcd_print(line_buf);
        }

        _delay_ms(80);
    }

    return 0;
}

