#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

// Multitasking without blocking delays
// Task 1: LED1 (PB0) toggle every 500ms (1 Hz blink)
// Task 2: LED2 (PB1) toggle every 150ms (3.3 Hz blink)
// Task 3: SW1 (PD2) toggles LED3 (PB2) instantly on press (0 latency!)
int main(void) {
    DDRB |= (1 << PB0) | (1 << PB1) | (1 << PB2);
    PORTB &= ~((1 << PB0) | (1 << PB1) | (1 << PB2));
    DDRD &= ~(1 << PD2); // SW1 Input
    PORTD |= (1 << PD2);  // Pull-Up

    uint16_t t1 = 0, t2 = 0;
    uint8_t last_sw = 1;

    while (1) {
        // Task 1: 500ms
        t1 += 5;
        if (t1 >= 500) {
            PORTB ^= (1 << PB0);
            t1 = 0;
        }

        // Task 2: 150ms
        t2 += 5;
        if (t2 >= 150) {
            PORTB ^= (1 << PB1);
            t2 = 0;
        }

        // Task 3: Zero-Latency Button Handling
        uint8_t sw = (PIND & (1 << PD2)) ? 1 : 0;
        if (last_sw == 1 && sw == 0) {
            PORTB ^= (1 << PB2); // Immediate toggle!
        }
        last_sw = sw;

        _delay_ms(5); // 5ms cooperative time slice
    }
    return 0;
}

