#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

int main(void) {
    DDRB |= 0x1F;   // PB0: Heartbeat, PB1..PB4: Chaser
    PORTB &= ~0x1F;
    DDRD &= ~(1 << PD2); // SW1 Input
    PORTD |= (1 << PD2);

    uint16_t t_hb = 0, t_chase = 0;
    uint8_t chase_pos = 0;
    int8_t dir = 1;
    uint8_t last_sw = 1;

    while (1) {
        // Task 1: Heartbeat (PB0) at 1Hz (500ms ON / 500ms OFF)
        t_hb += 10;
        if (t_hb >= 500) {
            PORTB ^= (1 << PB0);
            t_hb = 0;
        }

        // Task 2: Smooth LED Chaser (PB1..PB4) at 80ms
        t_chase += 10;
        if (t_chase >= 80) {
            chase_pos = (chase_pos + dir + 4) % 4;
            PORTB = (PORTB & ~0x1E) | (1 << (chase_pos + 1));
            t_chase = 0;
        }

        // Task 3: Zero-lag Direction Switcher Button
        uint8_t sw = (PIND & (1 << PD2)) ? 1 : 0;
        if (last_sw == 1 && sw == 0) {
            dir = -dir; // Reverses chaser with zero pause!
        }
        last_sw = sw;

        _delay_ms(10);
    }
    return 0;
}

