    // Prescaler 64: 16MHz / (64 * 1000Hz) - 1 = 249
    TCCR0A = (1 << WGM01);
    TCCR0B = (1 << CS01) | (1 << CS00);
    OCR0A = 249;
    TIMSK0 |= (1 << OCIE0A);

    sei();

    uint32_t t_last_1000 = 0;
    uint32_t t_last_200 = 0;
    uint8_t last_sw = 1;

    while (1) {
        uint32_t now = g_system_ticks;

        // Task A (1000ms period): LED0 Heartbeat
        if (now - t_last_1000 >= 1000) {
            PORTB ^= (1 << PB0);
            t_last_1000 = now;
