#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

const uint8_t seg_digits[10] = {
    0x3F, 0x06, 0x5B, 0x4F, 0x66, 0x6D, 0x7D, 0x07, 0x7F, 0x6F
};

int main(void) {
    DDRD = 0x7F;        // PD0..PD6 Output for 7-Segment
    PORTD = seg_digits[0];
    DDRB &= ~((1 << PB0) | (1 << PB1)); // PB0, PB1 Input
    PORTB |= (1 << PB0) | (1 << PB1);
    DDRB |= (1 << PB2); // PB2 Output (Interactive LED)
    PORTB &= ~(1 << PB2);

    uint8_t count = 0;
    uint16_t t_7seg = 0;
    uint16_t seg_interval = 1000;
    uint8_t last_sw2 = 1;

    while (1) {
        // Task 1 (Background): Auto 7-Segment increment
        t_7seg += 10;
        if (t_7seg >= seg_interval) {
            count = (count + 1) % 10;
            PORTD = seg_digits[count];
            t_7seg = 0;
        }

        // Task 2 (Interactive): Hold SW1 to speed up count
        if (!(PINB & (1 << PB0))) seg_interval = 250;
        else seg_interval = 1000;

        // Task 3 (Interactive): SW2 toggles LED with 0 latency
        uint8_t sw2 = (PINB & (1 << PB1)) ? 1 : 0;
        if (last_sw2 == 1 && sw2 == 0) {
            PORTB ^= (1 << PB2);
        }
        last_sw2 = sw2;

        _delay_ms(10);
    }
    return 0;
}

