#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

uint16_t adc_read(void) {
    ADCSRA |= (1 << ADSC);
    while (ADCSRA & (1 << ADSC));
    return ADC;
}

int main(void) {
    DDRB |= 0x07; // PB0: Normal Green, PB1: Alarm Red, PB2: Heartbeat
    PORTB &= ~0x07;
    DDRD &= ~(1 << PD2); // SW1: Mute
    PORTD |= (1 << PD2);

    ADMUX = (1 << REFS0);
    ADCSRA = (1 << ADEN) | (1 << ADPS2) | (1 << ADPS1) | (1 << ADPS0);

    uint16_t t_adc = 0, t_hb = 0, t_alarm = 0;
    uint16_t adc_val = 0;
    uint8_t muted = 0;

    while (1) {
        // Task 1: Non-blocking ADC sampling every 100ms
        t_adc += 10;
        if (t_adc >= 100) {
            adc_val = adc_read();
            t_adc = 0;
        }

        // Task 2: System Heartbeat at 1Hz (PB2)
        t_hb += 10;
        if (t_hb >= 500) {
            PORTB ^= (1 << PB2);
            t_hb = 0;
        }

        // Task 3: Over-voltage condition (>3.5V = >716 raw ADC)
        if (adc_val > 716) {
            PORTB &= ~(1 << PB0); // Normal Green OFF
            t_alarm += 10;
            if (t_alarm >= 80) { // Fast 12.5Hz Strobe
                if (!muted) PORTB ^= (1 << PB1);
                else PORTB &= ~(1 << PB1);
                t_alarm = 0;
            }
        } else {
            PORTB |= (1 << PB0);  // Normal Green ON
            PORTB &= ~(1 << PB1); // Alarm OFF
            muted = 0; // Unmute automatically when normal
        }

        // Task 4: User Mute Button
        if (!(PIND & (1 << PD2))) {
            muted = 1;
        }

        _delay_ms(10);
    }
    return 0;
}

