#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

typedef enum { TRAFFIC_GREEN, TRAFFIC_YELLOW, TRAFFIC_RED_PED } LightState;

int main(void) {
    DDRB |= 0x0F; // PB0: Red, PB1: Yellow, PB2: Green, PB3: Walk/Beeper
    PORTB &= ~0x0F;
    DDRD &= ~((1 << PD2) | (1 << PD3)); // PD2: Ped Button, PD3: Emergency
    PORTD |= (1 << PD2) | (1 << PD3);

    LightState state = TRAFFIC_GREEN;
    uint16_t t_state = 0;
    uint16_t t_beep = 0;
    uint8_t ped_request = 0;

    while (1) {
        // Immediate Emergency Check (Zero Latency Override)
        if (!(PIND & (1 << PD3))) {
            PORTB = (1 << PB1); // Caution Yellow solid
            _delay_ms(50);
            continue;
        }

        // Check Pedestrian Call Button
        if (!(PIND & (1 << PD2))) {
            ped_request = 1;
        }

        t_state += 20;

        switch (state) {
            case TRAFFIC_GREEN:
                PORTB = (1 << PB2);
                if ((t_state >= 3000 && ped_request) || t_state >= 5000) {
                    state = TRAFFIC_YELLOW;
                    t_state = 0;
                }
                break;

            case TRAFFIC_YELLOW:
                PORTB = (1 << PB1);
                if (t_state >= 1200) {
                    state = TRAFFIC_RED_PED;
                    t_state = 0;
                }
                break;

            case TRAFFIC_RED_PED:
                // Red car light solid, Pedestrian Walk + Beeper pulsing at 5Hz
                t_beep += 20;
                if (t_beep >= 100) {
                    PORTB ^= (1 << PB3);
                    t_beep = 0;
                }
                PORTB |= (1 << PB0); // Car Red ON

                if (t_state >= 3000) {
                    state = TRAFFIC_GREEN;
                    ped_request = 0;
                    t_state = 0;
                }
                break;
        }

        _delay_ms(20);
    }
    return 0;
}

