#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

#define LCD_RS_PIN PB4
#define LCD_EN_PIN PB3

void lcd_pulse_en(void) {
    PORTB |= (1 << LCD_EN_PIN);
    _delay_us(1);
    PORTB &= ~(1 << LCD_EN_PIN);
    _delay_us(50);
}

void lcd_send_nibble(uint8_t nibble) {
    PORTD &= ~((1 << PD2) | (1 << PD3) | (1 << PD4) | (1 << PD5));
    if (nibble & 0x01) PORTD |= (1 << PD5);
    if (nibble & 0x02) PORTD |= (1 << PD4);
    if (nibble & 0x04) PORTD |= (1 << PD3);
    if (nibble & 0x08) PORTD |= (1 << PD2);
    lcd_pulse_en();
}

void lcd_cmd(uint8_t cmd) {
    PORTB &= ~(1 << LCD_RS_PIN);
    lcd_send_nibble(cmd >> 4);
    lcd_send_nibble(cmd & 0x0F);
    if (cmd == 0x01 || cmd == 0x02) _delay_ms(2);
}

void lcd_data(uint8_t data) {
    PORTB |= (1 << LCD_RS_PIN);
    lcd_send_nibble(data >> 4);
    lcd_send_nibble(data & 0x0F);
}

void lcd_print(const char* str) {
    while (*str) lcd_data(*str++);
}

void lcd_init_4bit(void) {
    DDRB |= (1 << LCD_RS_PIN) | (1 << LCD_EN_PIN);
    DDRD |= (1 << PD2) | (1 << PD3) | (1 << PD4) | (1 << PD5);
    _delay_ms(50);
    lcd_send_nibble(0x03); _delay_ms(5);
    lcd_send_nibble(0x03); _delay_us(150);
    lcd_send_nibble(0x03); _delay_us(150);
    lcd_send_nibble(0x02); _delay_us(150);
    lcd_cmd(0x28);
    lcd_cmd(0x0C);
    lcd_cmd(0x06);
    lcd_cmd(0x01);
}

int main(void) {
    DDRB |= (1 << PB0) | (1 << PB1); // LEDs on PB0, PB1
    PORTB &= ~((1 << PB0) | (1 << PB1));

    lcd_init_4bit();
    lcd_cmd(0x80);
    lcd_print("TASK1: RUNNING");

    uint16_t t_led = 0, t_lcd = 0;
    uint8_t uptime = 0;

    while (1) {
        // Task 1: Smooth LED Toggle (80ms)
        t_led += 10;
        if (t_led >= 80) {
            PORTB ^= (1 << PB0);
            t_led = 0;
        }

        // Task 2: Background LCD Update (500ms)
        t_lcd += 10;
        if (t_lcd >= 500) {
            uptime++;
            lcd_cmd(0xC0);
            lcd_data('U'); lcd_data('p'); lcd_data(':'); lcd_data(' ');
            lcd_data('0' + (uptime / 100) % 10);
            lcd_data('0' + (uptime / 10) % 10);
            lcd_data('0' + (uptime % 10));
            lcd_data('s');
            PORTB ^= (1 << PB1); // Toggle status indicator
            t_lcd = 0;
        }

        _delay_ms(10);
    }
    return 0;
}

