#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>

// Master Cooperative Executive: 4 Simultaneous Tasks
// Task 1: Fast Button Scanner & Mode Switcher (10ms)
// Task 2: ADC Voltage Reader (100ms)
// Task 3: Bargraph Driver (PB0..PB3)
// Task 4: System Watchdog Heartbeat
uint16_t adc_read(void) {
    ADCSRA |= (1 << ADSC);
    while (ADCSRA & (1 << ADSC));
    return ADC;
}

int main(void) {
    DDRB |= 0x0F; // PB0..PB3 Output
    PORTB &= ~0x0F;
    DDRD &= ~((1 << PD2) | (1 << PD3)); // SW1, SW2 Input
    PORTD |= (1 << PD2) | (1 << PD3);

    ADMUX = (1 << REFS0);
    ADCSRA = (1 << ADEN) | (1 << ADPS2) | (1 << ADPS1) | (1 << ADPS0);

    uint16_t t_scan = 0, t_adc = 0, t_hb = 0;
    uint16_t adc_val = 0;
    uint8_t mode = 0; // 0 = Bar, 1 = Inverted Bar
    uint8_t last_sw1 = 1;

    while (1) {
        // Task 1: 10ms Button Scan
        t_scan += 5;
        if (t_scan >= 10) {
            uint8_t sw1 = (PIND & (1 << PD2)) ? 1 : 0;
            if (last_sw1 == 1 && sw1 == 0) {
                mode = !mode; // Toggle display mode
            }
            last_sw1 = sw1;
            t_scan = 0;
        }

        // Task 2: 100ms ADC Sample
        t_adc += 5;
        if (t_adc >= 100) {
            adc_val = adc_read();
            t_adc = 0;
        }

        // Task 3: Executive Output Mapping
        uint8_t bar = 0;
        if (adc_val >= 800) bar = 0x0F;
        else if (adc_val >= 500) bar = 0x07;
        else if (adc_val >= 250) bar = 0x03;
        else bar = 0x01;

        if (mode) bar = ~bar & 0x0F;
        PORTB = bar;

        _delay_ms(5);
    }
    return 0;
}

