    if (nibble & 0x04) PORTD |= (1 << PD3); // D6
    if (nibble & 0x08) PORTD |= (1 << PD2); // D7
    lcd_pulse_enable();
}

void lcd_send_cmd(uint8_t cmd) {
    PORTB &= ~(1 << LCD_RS_PIN);
    lcd_write_4bits((cmd >> 4) & 0x0F);
    lcd_write_4bits(cmd & 0x0F);
    if (cmd == 0x01 || cmd == 0x02) _delay_ms(2);
    else _delay_us(50);
}

void lcd_send_data(uint8_t data) {
    PORTB |= (1 << LCD_RS_PIN);
    lcd_write_4bits((data >> 4) & 0x0F);
    lcd_write_4bits(data & 0x0F);
    _delay_us(50);
}

void lcd_print(const char *str) {
    while (*str) lcd_send_data(*str++);
}

void lcd_set_cursor(uint8_t row, uint8_t col) {
    uint8_t addr = (row == 0) ? (0x80 + col) : (0xC0 + col);
    lcd_send_cmd(addr);
}

void lcd_init(void) {
    DDRB |= (1 << LCD_RS_PIN) | (1 << LCD_EN_PIN);
    PORTB &= ~((1 << LCD_RS_PIN) | (1 << LCD_EN_PIN));
    DDRD |= (1 << PD2) | (1 << PD3) | (1 << PD4) | (1 << PD5);

    _delay_ms(50);
    lcd_write_4bits(0x03);
    _delay_ms(5);
    lcd_write_4bits(0x03);
    _delay_us(150);
    lcd_write_4bits(0x03);
    _delay_us(150);
    lcd_write_4bits(0x02); // 4-bit mode
    _delay_us(150);

    lcd_send_cmd(0x28); // 2 lines, 5x8 font
    lcd_send_cmd(0x0C); // Display ON, Cursor OFF
    lcd_send_cmd(0x06); // Entry mode auto increment
    lcd_send_cmd(0x01); // Clear display
    _delay_ms(2);
}

void adc_init(void) {
    ADMUX = (1 << REFS0); // AVCC with external capacitor at AREF, Channel A0
    ADCSRA = (1 << ADEN) | (1 << ADPS2) | (1 << ADPS1) | (1 << ADPS0); // Prescaler 128 (125 kHz)
}

uint16_t adc_read(void) {
    ADCSRA |= (1 << ADSC);
    while (ADCSRA & (1 << ADSC));
    return ADC;
}

int main(void) {
    // Hardware Setup:
    // Buttons: D8 (PB0), D9 (PB1), D10 (PB2) as INPUT_PULLUP
    DDRB &= ~((1 << PB0) | (1 << PB1) | (1 << PB2));
    PORTB |= (1 << PB0) | (1 << PB1) | (1 << PB2);

    // LEDs: D13 (PB5), A1 (PC1), A2 (PC2) as OUTPUT
    DDRB |= (1 << PB5);
    DDRC |= (1 << PC1) | (1 << PC2);
    PORTB &= ~(1 << PB5);
    PORTC &= ~((1 << PC1) | (1 << PC2));

    adc_init();
    lcd_init();

    char line_buf[17];

    uint8_t state = 0; // 0: STOP, 1: RUN, 2: JOG
    uint16_t timer_lcd = 0;
    uint16_t timer_strobe = 0;
    uint8_t strobe_state = 0;

    lcd_set_cursor(0, 0);
    lcd_print("IND. MIXER READY");
    lcd_set_cursor(1, 0);
    lcd_print("SW1:START SW2:ST");

    while (1) {
        _delay_ms(1);
        timer_lcd++;
        timer_strobe++;

        // Read Buttons (Active-Low)
        uint8_t sw1 = (PINB & (1 << PB0)) == 0;
        uint8_t sw2 = (PINB & (1 << PB1)) == 0;
        uint8_t sw3 = (PINB & (1 << PB2)) == 0;

        // State Machine
        if (sw2) {
            state = 0; // Emergency Stop
        } else if (sw1 && state != 1) {
            state = 1; // Start
        } else if (sw3) {
            state = 2; // Jogging
        } else if (state == 2 && !sw3) {
            state = 0; // Release Jog
        }

        // Read Speed Sensor (Potentiometer A0)
        uint16_t raw_adc = adc_read();
        uint8_t speed_pct = (uint32_t)raw_adc * 100 / 1023;

        // Outputs
        if (state == 1 || state == 2) {
            PORTB |= (1 << PB5); // RUN LED ON
        } else {
            PORTB &= ~(1 << PB5); // RUN LED OFF
        }

        // Warning Strobe if speed > 85%
        if (speed_pct > 85) {
            if (timer_strobe >= 100) {
                timer_strobe = 0;
                strobe_state = !strobe_state;
                if (strobe_state) PORTC |= (1 << PC1);
                else PORTC &= ~(1 << PC1);
            }
            PORTC &= ~(1 << PC2); // Disable Heater
        } else {
            PORTC &= ~(1 << PC1); // Warning OFF
            if (state == 1) PORTC |= (1 << PC2); // Heater ON in normal run
            else PORTC &= ~(1 << PC2);
        }

        // LCD Telemetry Refresh (Every 250 ms)
        if (timer_lcd >= 250) {
            timer_lcd = 0;
            const char *st_str = (state == 1) ? "RUN " : (state == 2) ? "JOG " : "STOP";
            sprintf(line_buf, "Mixer:%s Spd:%2d%%", st_str, speed_pct);
            lcd_set_cursor(0, 0);
            lcd_print(line_buf);

            sprintf(line_buf, "Htr:%s  Alm:%s", (PORTC & (1 << PC2)) ? "ON " : "OFF", (speed_pct > 85) ? "WARN" : "OK  ");
            lcd_set_cursor(1, 0);
            lcd_print(line_buf);
        }
    }

}

