int main(void) {
    // Hardware Setup:
    // Buttons: D8 (PB0), D9 (PB1), D10 (PB2) as INPUT_PULLUP
    DDRB &= ~((1 << PB0) | (1 << PB1) | (1 << PB2));
    PORTB |= (1 << PB0) | (1 << PB1) | (1 << PB2);

    // LEDs: D13 (PB5), A1 (PC1), A2 (PC2) as OUTPUT
    DDRB |= (1 << PB5);
    DDRC |= (1 << PC1) | (1 << PC2);
    PORTB &= ~(1 << PB5);
    PORTC &= ~((1 << PC1) | (1 << PC2));

    adc_init();
    lcd_init();

    char line_buf[17];

    uint16_t tare_offset = 0;
    uint8_t dosing_active = 0;
    uint16_t target_weight = 2500;
    uint16_t timer_lcd = 0;

    lcd_set_cursor(0, 0);
    lcd_print("DIGITAL DOSER V1");
    _delay_ms(500);

    while (1) {
        _delay_ms(1);
        timer_lcd++;

        // Read Buttons
        uint8_t sw_tare = (PINB & (1 << PB0)) == 0;
        uint8_t sw_dose = (PINB & (1 << PB1)) == 0;
        uint8_t sw_preset = (PINB & (1 << PB2)) == 0;

        uint16_t raw_adc = adc_read();
        uint16_t gross_weight = (uint32_t)raw_adc * 5000 / 1023; // 0 - 5000 grams

        if (sw_tare) {
            tare_offset = gross_weight;
            _delay_ms(200); // Simple debounce
        }

        uint16_t net_weight = (gross_weight >= tare_offset) ? (gross_weight - tare_offset) : 0;

        if (sw_dose) {
            dosing_active = !dosing_active;
            _delay_ms(200);
        }

        if (sw_preset) {
            if (target_weight == 1000) target_weight = 2500;
            else if (target_weight == 2500) target_weight = 4000;
            else target_weight = 1000;
            _delay_ms(200);
        }

        // Valve Control (LED1 PB5)
        if (dosing_active && net_weight < target_weight && gross_weight < 4500) {
            PORTB |= (1 << PB5); // Valve Open
        } else {
            PORTB &= ~(1 << PB5); // Valve Closed
            if (dosing_active && net_weight >= target_weight) dosing_active = 0;
        }

        // Tolerance Indicator (LED2 PC1)
        if (net_weight >= target_weight && net_weight <= target_weight + 100) {
            PORTC |= (1 << PC1);
        } else {
            PORTC &= ~(1 << PC1);
        }

        // Overload Alarm (LED3 PC2)
        if (gross_weight >= 4500) {
            PORTC |= (1 << PC2); // Overload
        } else {
            PORTC &= ~(1 << PC2);
        }

        if (timer_lcd >= 200) {
            timer_lcd = 0;
            sprintf(line_buf, "Net:%4dg Tar:%4d", net_weight, target_weight);
            lcd_set_cursor(0, 0);
            lcd_print(line_buf);

            sprintf(line_buf, "Vlv:%s  %s", (PORTB & (1 << PB5)) ? "OPEN" : "OFF ", (gross_weight >= 4500) ? "OVERLOAD" : "NORMAL  ");
            lcd_set_cursor(1, 0);
            lcd_print(line_buf);
        }
    }

}

