/*
 * Project: Sample74_Multitasking_Smart_Elevator_Dispatcher - Sample74 Multitasking Smart Elevator Dispatcher
 * Description: 4-Floor Smart Elevator Dispatcher with Overload Interlock
 * Target MCU: Microchip ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (GNU avr-gcc)
 * Architecture: Non-Blocking Cooperative Multitasking Super-Loop
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>
#include <stdint.h>

// Common Cathode 7-Segment Lookup Table (0-9, dash, blank)
const uint8_t seg_table[12] = {
    0x3F, // 0
    0x06, // 1
    0x5B, // 2
    0x4F, // 3
    0x66, // 4
    0x6D, // 5
    0x7D, // 6
    0x07, // 7
    0x7F, // 8
    0x6F, // 9
    0x40, // '-'
    0x00  // blank
};

void adc_init(void) {
    ADMUX = (1 << REFS0); // AVCC reference, Channel A0
    ADCSRA = (1 << ADEN) | (1 << ADPS2) | (1 << ADPS1) | (1 << ADPS0); // Prescaler 128
}

uint16_t adc_read(void) {
    ADCSRA |= (1 << ADSC);
    while (ADCSRA & (1 << ADSC));
    return ADC;
}

int main(void) {
    // 7-Segment on PORTD (PD0..PD7) as OUTPUT
    DDRD = 0xFF;
    PORTD = 0x00;

    // LEDs on D8 (PB0), D9 (PB1) as OUTPUT
    DDRB |= (1 << PB0) | (1 << PB1);
    PORTB &= ~((1 << PB0) | (1 << PB1));

    // Buttons on A1 (PC1), A2 (PC2), A3 (PC3) as INPUT_PULLUP
    DDRC &= ~((1 << PC1) | (1 << PC2) | (1 << PC3));
    PORTC |= (1 << PC1) | (1 << PC2) | (1 << PC3);

    adc_init();

    uint8_t current_floor = 1;
    uint8_t target_floor = 1;
    uint16_t travel_timer = 0;
    uint16_t dp_timer = 0;
    uint8_t dp_state = 0;

    while (1) {
        _delay_ms(1);

        // Read Call Buttons (A1=Flr1, A2=Flr2, A3=Flr3)
        if ((PINC & (1 << PC1)) == 0) target_floor = 1;
        if ((PINC & (1 << PC2)) == 0) target_floor = 2;
        if ((PINC & (1 << PC3)) == 0) target_floor = 3;

        // Cabin Load Sensor
        uint16_t raw_adc = adc_read();
        uint8_t overload = (raw_adc > 850); // > 85% load

        if (overload) {
            // Overload alarm: halt motion and flash both LEDs
            dp_timer++;
            if (dp_timer >= 100) {
                dp_timer = 0;
                dp_state = !dp_state;
                if (dp_state) {
                    PORTB |= (1 << PB0) | (1 << PB1);
                    PORTD = seg_table[current_floor] | 0x80;
                } else {
                    PORTB &= ~((1 << PB0) | (1 << PB1));
                    PORTD = seg_table[current_floor];
                }
            }
            continue;
        }

        // Elevator Movement State Machine
        if (current_floor < target_floor) {
            // Moving UP: Motor UP LED (PB0) ON
            PORTB |= (1 << PB0);
            PORTB &= ~(1 << PB1);

            travel_timer++;
            dp_timer++;
            if (dp_timer >= 150) {
                dp_timer = 0;
                dp_state = !dp_state;
            }
            PORTD = seg_table[current_floor] | (dp_state ? 0x80 : 0x00);

            if (travel_timer >= 1200) { // 1.2s per floor
                travel_timer = 0;
                current_floor++;
            }
        } else if (current_floor > target_floor) {
            // Moving DOWN: Motor DOWN LED (PB1) ON
            PORTB |= (1 << PB1);
            PORTB &= ~(1 << PB0);

            travel_timer++;
            dp_timer++;
            if (dp_timer >= 150) {
                dp_timer = 0;
                dp_state = !dp_state;
            }
            PORTD = seg_table[current_floor] | (dp_state ? 0x80 : 0x00);

            if (travel_timer >= 1200) {
                travel_timer = 0;
                current_floor--;
            }
        } else {
            // Arrived at target floor
            PORTB &= ~((1 << PB0) | (1 << PB1)); // Motors OFF
            PORTD = seg_table[current_floor];    // Solid Floor Number
            travel_timer = 0;
        }
    }

}

