 * Language: Embedded C (GNU avr-gcc)
 * Architecture: Non-Blocking Cooperative Multitasking Super-Loop
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>
#include <stdint.h>

// Common Cathode 7-Segment Lookup Table (0-9, dash, blank)
const uint8_t seg_table[12] = {
    0x3F, // 0
    0x06, // 1
    0x5B, // 2
    0x4F, // 3
    0x66, // 4
    0x6D, // 5
    0x7D, // 6
    0x07, // 7
    0x7F, // 8
    0x6F, // 9
    0x40, // '-'
    0x00  // blank
};

void adc_init(void) {
    ADMUX = (1 << REFS0); // AVCC reference, Channel A0
    ADCSRA = (1 << ADEN) | (1 << ADPS2) | (1 << ADPS1) | (1 << ADPS0); // Prescaler 128
}

uint16_t adc_read(void) {
    ADCSRA |= (1 << ADSC);
    while (ADCSRA & (1 << ADSC));
    return ADC;
}

int main(void) {
    // 7-Segment on PORTD (PD0..PD7) as OUTPUT
    DDRD = 0xFF;
    PORTD = 0x00;

    // LEDs on D8 (PB0), D9 (PB1) as OUTPUT
    DDRB |= (1 << PB0) | (1 << PB1);
    PORTB &= ~((1 << PB0) | (1 << PB1));

    // Buttons on A1 (PC1), A2 (PC2), A3 (PC3) as INPUT_PULLUP
    DDRC &= ~((1 << PC1) | (1 << PC2) | (1 << PC3));
    PORTC |= (1 << PC1) | (1 << PC2) | (1 << PC3);

    adc_init();

    uint8_t remaining_attempts = 3;
    uint8_t pin_seq[4] = {1, 2, 1, 2};
    uint8_t entered_seq[4] = {0, 0, 0, 0};
    uint8_t pin_idx = 0;
    uint16_t unlock_timer = 0;
    uint16_t lockout_timer = 0;

    PORTD = seg_table[3]; // Show 3 attempts remaining

    while (1) {
        _delay_ms(1);

        if (lockout_timer > 0) {
            lockout_timer--;
            uint8_t sec_left = lockout_timer / 1000;
            PORTD = seg_table[sec_left % 10];
            // Flash Siren Alarm (PB1)
            if ((lockout_timer / 100) % 2) PORTB |= (1 << PB1);
            else PORTB &= ~(1 << PB1);

            if (lockout_timer == 0) {
                remaining_attempts = 3;
                PORTD = seg_table[3];
                PORTB &= ~(1 << PB1);
            }
            continue;
        }

        if (unlock_timer > 0) {
            unlock_timer--;
            PORTB |= (1 << PB0); // Solenoid Unlocked
            PORTD = 0x3E; // 'U' on 7-Segment
            if (unlock_timer == 0) {
                PORTB &= ~(1 << PB0); // Relock
                PORTD = seg_table[remaining_attempts];
            }
            continue;
        }

        // Read Buttons: A1=Digit 1, A2=Digit 2, A3=Enter
        uint8_t btn1 = (PINC & (1 << PC1)) == 0;
        uint8_t btn2 = (PINC & (1 << PC2)) == 0;
        uint8_t btn_enter = (PINC & (1 << PC3)) == 0;

        if (btn1) {
            if (pin_idx < 4) entered_seq[pin_idx++] = 1;
            PORTD = seg_table[1];
            _delay_ms(200);
            PORTD = seg_table[remaining_attempts];
        } else if (btn2) {
            if (pin_idx < 4) entered_seq[pin_idx++] = 2;
            PORTD = seg_table[2];
            _delay_ms(200);
            PORTD = seg_table[remaining_attempts];
        } else if (btn_enter) {
            _delay_ms(200);
            uint16_t bio_match = adc_read(); // Biometric Vein ADC
            uint8_t pin_correct = (pin_idx == 4 &&
                                   entered_seq[0] == pin_seq[0] &&
                                   entered_seq[1] == pin_seq[1] &&
                                   entered_seq[2] == pin_seq[2] &&
                                   entered_seq[3] == pin_seq[3]);

            if (pin_correct && bio_match >= 700) { // Valid PIN + Biometric >= 68%
                unlock_timer = 4000; // Unlock for 4 seconds
                remaining_attempts = 3;
            } else {
                if (remaining_attempts > 1) {
                    remaining_attempts--;
                    PORTD = seg_table[remaining_attempts];
                } else {
                    lockout_timer = 9000; // 9-second security lockout
                }
            }
            pin_idx = 0;
        }
    }

}

