 * Project: Sample77_Multitasking_Highway_Toll_Gate_Barrier - Sample77 Multitasking Highway Toll Gate Barrier
 * Description: Electronic Toll Collection (ETC) Highway Barrier System
 * Target MCU: Microchip ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (GNU avr-gcc)
 * Architecture: Non-Blocking Cooperative Multitasking Super-Loop
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>
#include <stdint.h>
#include <stdio.h>

#define LCD_RS_PIN PB4
#define LCD_EN_PIN PB3

void lcd_pulse_enable(void) {
    PORTB |= (1 << LCD_EN_PIN);
    _delay_us(2);
    PORTB &= ~(1 << LCD_EN_PIN);
    _delay_us(50);
}

void lcd_write_4bits(uint8_t nibble) {
    PORTD &= ~((1 << PD2) | (1 << PD3) | (1 << PD4) | (1 << PD5));
    if (nibble & 0x01) PORTD |= (1 << PD5); // D4
    if (nibble & 0x02) PORTD |= (1 << PD4); // D5
    if (nibble & 0x04) PORTD |= (1 << PD3); // D6
    if (nibble & 0x08) PORTD |= (1 << PD2); // D7
    lcd_pulse_enable();
}

void lcd_send_cmd(uint8_t cmd) {
    PORTB &= ~(1 << LCD_RS_PIN);
    lcd_write_4bits((cmd >> 4) & 0x0F);
    lcd_write_4bits(cmd & 0x0F);
    if (cmd == 0x01 || cmd == 0x02) _delay_ms(2);
    else _delay_us(50);
}

void lcd_send_data(uint8_t data) {
    PORTB |= (1 << LCD_RS_PIN);
    lcd_write_4bits((data >> 4) & 0x0F);
    lcd_write_4bits(data & 0x0F);
    _delay_us(50);
}

void lcd_print(const char *str) {
    while (*str) lcd_send_data(*str++);
}

void lcd_set_cursor(uint8_t row, uint8_t col) {
    uint8_t addr = (row == 0) ? (0x80 + col) : (0xC0 + col);
    lcd_send_cmd(addr);
}

void lcd_init(void) {
    DDRB |= (1 << LCD_RS_PIN) | (1 << LCD_EN_PIN);
    PORTB &= ~((1 << LCD_RS_PIN) | (1 << LCD_EN_PIN));
    DDRD |= (1 << PD2) | (1 << PD3) | (1 << PD4) | (1 << PD5);

    _delay_ms(50);
    lcd_write_4bits(0x03);
    _delay_ms(5);
    lcd_write_4bits(0x03);
    _delay_us(150);
    lcd_write_4bits(0x03);
    _delay_us(150);
    lcd_write_4bits(0x02); // 4-bit mode
    _delay_us(150);

    lcd_send_cmd(0x28); // 2 lines, 5x8 font
    lcd_send_cmd(0x0C); // Display ON, Cursor OFF
    lcd_send_cmd(0x06); // Entry mode auto increment
    lcd_send_cmd(0x01); // Clear display
    _delay_ms(2);
}

void adc_init(void) {
    ADMUX = (1 << REFS0); // AVCC with external capacitor at AREF, Channel A0
    ADCSRA = (1 << ADEN) | (1 << ADPS2) | (1 << ADPS1) | (1 << ADPS0); // Prescaler 128 (125 kHz)
}

uint16_t adc_read(void) {
    ADCSRA |= (1 << ADSC);
    while (ADCSRA & (1 << ADSC));
    return ADC;
}

int main(void) {
    // Hardware Setup:
    // Buttons: D8 (PB0), D9 (PB1), D10 (PB2) as INPUT_PULLUP
    DDRB &= ~((1 << PB0) | (1 << PB1) | (1 << PB2));
    PORTB |= (1 << PB0) | (1 << PB1) | (1 << PB2);

    // LEDs: D13 (PB5), A1 (PC1), A2 (PC2) as OUTPUT
    DDRB |= (1 << PB5);
    DDRC |= (1 << PC1) | (1 << PC2);
    PORTB &= ~(1 << PB5);
    PORTC &= ~((1 << PC1) | (1 << PC2));

    adc_init();
    lcd_init();

    char line_buf[17];

    uint8_t gate_open = 0;
    uint16_t gate_timer = 0;
    uint16_t timer_lcd = 0;
    uint8_t veh_class = 0; // 0: None, 1: Car, 2: Bus, 3: Heavy Truck

    while (1) {
        _delay_ms(1);
        timer_lcd++;

        // Read Buttons: PB0=Vehicle In, PB1=Paid, PB2=Manual Open
        uint8_t sw_veh  = (PINB & (1 << PB0)) == 0;
        uint8_t sw_paid = (PINB & (1 << PB1)) == 0;
        uint8_t sw_man  = (PINB & (1 << PB2)) == 0;

        uint16_t raw_adc = adc_read(); // Vehicle Height/Weight
        if (sw_veh) {
            if (raw_adc < 350) veh_class = 1;      // Car ($20)
            else if (raw_adc < 750) veh_class = 2; // Bus ($40)
            else veh_class = 3;                   // Heavy Truck ($60)
            _delay_ms(150);
        }

        if (sw_paid || sw_man) {
            gate_open = 1;
            gate_timer = 5000; // 5-second barrier gate open
            _delay_ms(150);
        }

        if (gate_timer > 0) {
            gate_timer--;
            PORTB |= (1 << PB5);  // Gate Green LED ON
            PORTC &= ~(1 << PC1); // Red Stop OFF
            if (gate_timer == 0) {
                gate_open = 0;
                veh_class = 0;
            }
        } else {
            PORTB &= ~(1 << PB5); // Gate Green OFF
            PORTC |= (1 << PC1);  // Red Stop ON
        }

        if (timer_lcd >= 200) {
            timer_lcd = 0;
            const char *c_name = (veh_class == 1) ? "CAR   $20" : (veh_class == 2) ? "BUS   $40" : (veh_class == 3) ? "TRUCK $60" : "NO VEHICLE";
            sprintf(line_buf, "CLS:%s", c_name);
            lcd_set_cursor(0, 0);
            lcd_print(line_buf);

            sprintf(line_buf, "GATE:%s %2d.%1ds", gate_open ? "OPEN " : "CLOSE", gate_timer / 1000, (gate_timer % 1000) / 100);
            lcd_set_cursor(1, 0);
            lcd_print(line_buf);
        }
    }

}

