/*
 * Project: Sample78_Multitasking_Dual_Display_Workcell - Sample78 Multitasking Dual Display Workcell
 * Description: Automated Assembly Workcell with Stage Progress Indicator & Cycle Timer
 * Target MCU: Microchip ATmega328P (Arduino Uno @ 16 MHz)
 * Language: Embedded C (GNU avr-gcc)
 * Architecture: Non-Blocking Cooperative Multitasking Super-Loop
 */

#define F_CPU 16000000UL
#include <avr/io.h>
#include <util/delay.h>
#include <stdint.h>

// Common Cathode 7-Segment Lookup Table (0-9, dash, blank)
const uint8_t seg_table[12] = {
    0x3F, // 0
    0x06, // 1
    0x5B, // 2
    0x4F, // 3
    0x66, // 4
    0x6D, // 5
    0x7D, // 6
    0x07, // 7
    0x7F, // 8
    0x6F, // 9
    0x40, // '-'
    0x00  // blank
};

void adc_init(void) {
    ADMUX = (1 << REFS0); // AVCC reference, Channel A0
    ADCSRA = (1 << ADEN) | (1 << ADPS2) | (1 << ADPS1) | (1 << ADPS0); // Prescaler 128
}

uint16_t adc_read(void) {
    ADCSRA |= (1 << ADSC);
    while (ADCSRA & (1 << ADSC));
    return ADC;
}

int main(void) {
    // 7-Segment on PORTD (PD0..PD7) as OUTPUT
    DDRD = 0xFF;
    PORTD = 0x00;

    // LEDs on D8 (PB0), D9 (PB1) as OUTPUT
    DDRB |= (1 << PB0) | (1 << PB1);
    PORTB &= ~((1 << PB0) | (1 << PB1));

    // Buttons on A1 (PC1), A2 (PC2), A3 (PC3) as INPUT_PULLUP
    DDRC &= ~((1 << PC1) | (1 << PC2) | (1 << PC3));
    PORTC |= (1 << PC1) | (1 << PC2) | (1 << PC3);

    adc_init();

    uint8_t current_stage = 0;
    uint8_t cycle_running = 0;
    uint16_t stage_timer = 0;

    PORTD = seg_table[0];

    while (1) {
        _delay_ms(1);

        uint8_t sw_start = (PINC & (1 << PC1)) == 0;
        uint8_t sw_step  = (PINC & (1 << PC2)) == 0;
        uint8_t sw_estop = (PINC & (1 << PC3)) == 0;

        if (sw_estop) {
            cycle_running = 0;
            current_stage = 0;
            PORTD = 0x40; // '-' Fault Indicator
            PORTB &= ~(1 << PB0); // RUN LED OFF
            PORTB |= (1 << PB1);  // FAULT LED ON
            _delay_ms(300);
            continue;
        }

        if (sw_start && !cycle_running) {
            cycle_running = 1;
            current_stage = 1;
            PORTB |= (1 << PB0);  // RUN ON
            PORTB &= ~(1 << PB1); // FAULT OFF
            _delay_ms(200);
        }

        if (sw_step && !cycle_running) {
            current_stage = (current_stage + 1) % 10;
            PORTD = seg_table[current_stage];
            _delay_ms(200);
        }

        // Potentiometer controls dwell time (300ms to 2000ms per stage)
        uint16_t raw_adc = adc_read();
        uint16_t dwell_ms = 300 + (uint32_t)raw_adc * 1700 / 1023;

        if (cycle_running) {
            PORTD = seg_table[current_stage];
            stage_timer++;
            if (stage_timer >= dwell_ms) {
                stage_timer = 0;
                current_stage++;
                if (current_stage > 9) {
                    current_stage = 0;
                    cycle_running = 0;
                    PORTB &= ~(1 << PB0); // Cycle Complete
                }
            }
        }
    }

}

