    uint8_t mode = 0;
    uint16_t lap_count = 0;
    uint16_t timer_heartbeat = 0;
    uint16_t timer_lcd = 0;
    uint32_t system_millis = 0;

    lcd_set_cursor(0, 0);
    lcd_print("CDTI GRAND PRIX");
    lcd_set_cursor(1, 0);
    lcd_print("MASTER EXECUTIVE");
    _delay_ms(500);

    while (1) {
        _delay_ms(1);
        system_millis++;
        timer_heartbeat++;
        timer_lcd++;

        // System Heartbeat Strobe (LED1 PB5)
        if (timer_heartbeat >= 500) {
            timer_heartbeat = 0;
            PORTB ^= (1 << PB5);
        }

        // Multi-Task Button Scan
        uint8_t sw_mode  = (PINB & (1 << PB0)) == 0;
        uint8_t sw_lap   = (PINB & (1 << PB1)) == 0;
        uint8_t sw_estop = (PINB & (1 << PB2)) == 0;

        if (sw_estop) {
            PORTC &= ~((1 << PC1) | (1 << PC2)); // Emergency Kill
            PORTB &= ~(1 << PB5);
            lcd_set_cursor(0, 0);
            lcd_print("EMERGENCY STOP! ");
            lcd_set_cursor(1, 0);
            lcd_print("SYSTEM SHUTDOWN ");
            while (1) {
                PORTC ^= (1 << PC1); // Rapid Alarm Strobe
                _delay_ms(100);
            }
        }

        if (sw_mode) { mode = !mode; _delay_ms(150); }
        if (sw_lap)  { lap_count++;  _delay_ms(150); }

        // ADC Throttle Sensor
        uint16_t throttle = adc_read();
        uint8_t speed_pct = (uint32_t)throttle * 100 / 1023;

        // Threshold Output Actuator (LED3 PC2)
        if (speed_pct > 50) PORTC |= (1 << PC2);
        else PORTC &= ~(1 << PC2);

        // Warning Alarm (LED2 PC1)
        if (speed_pct > 90) PORTC |= (1 << PC1);
        else PORTC &= ~(1 << PC1);

        if (timer_lcd >= 200) {
            timer_lcd = 0;
            if (mode == 0) {
                sprintf(line_buf, "Spd:%2d%%  Lap:%3d", speed_pct, lap_count);
                lcd_set_cursor(0, 0);
                lcd_print(line_buf);

                sprintf(line_buf, "Act:%s  T:%4lus", (PORTC & (1 << PC2)) ? "ON " : "OFF", system_millis / 1000);
                lcd_set_cursor(1, 0);
                lcd_print(line_buf);
            } else {
                sprintf(line_buf, "ADC:%4u RawThrot", throttle);
                lcd_set_cursor(0, 0);
                lcd_print(line_buf);

                sprintf(line_buf, "SYS_TICKS:%6lu", system_millis);
                lcd_set_cursor(1, 0);
                lcd_print(line_buf);
            }
        }
    }

}

